def candidate_library(library_id: str) -> tuple[Candidate, ...]:
    """Return one named immutable candidate library."""

    try:
        return CANDIDATE_LIBRARIES[library_id]
    except KeyError as exc:
        choices = ", ".join(sorted(CANDIDATE_LIBRARIES))
