def candidate_library_fingerprint(
    candidates: tuple[Candidate, ...] = CANDIDATES,
) -> str:
    """Return a stable fingerprint for the exact predeclared strategy library."""

    payload = [
        {
            "name": candidate.name,
            "description": candidate.description,
            "weights": candidate.weights,
        }
        for candidate in candidates
    ]
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def stability_score_with_drawdown_cap(
    stability_score: float | None,
    max_drawdown: float | None,
    cap: float = STRICT_DEVELOPMENT_MAX_DRAWDOWN,
) -> float | None:
    """Keep a stability score only when its development drawdown satisfies ``cap``."""

    if stability_score is None or max_drawdown is None or float(max_drawdown) < cap:
        return None
    return float(stability_score)


def positive_year_stability_score(
    year_returns: list[float], max_drawdown: float | None
) -> float | None:
    """Score only a development sample with at least two, all-positive calendar years."""

    if (
        len(year_returns) < 2
        or any(value <= 0.0 for value in year_returns)
        or max_drawdown is None
    ):
        return None
    return float(min(year_returns) - 0.5 * abs(float(max_drawdown)))


def apply_regime_filter(frame: pd.DataFrame, regime_filter: str) -> pd.DataFrame:
    """Return signal rows allowed by a close-known market-breadth state."""

    if regime_filter not in REGIME_FILTERS:
        choices = ", ".join(sorted(REGIME_FILTERS))
        raise ValueError(
            f"unknown regime_filter {regime_filter!r}; choose one of: {choices}"
        )
    if regime_filter == "always":
        return frame
    if regime_filter == "breadth_5_positive":
        condition = frame["market_breadth_5"].gt(0.0)
    elif regime_filter == "breadth_20_positive":
        condition = frame["market_breadth_20"].gt(0.0)
    elif regime_filter == "breadth_5_above_20":
        condition = frame["market_breadth_5"].gt(frame["market_breadth_20"])
    elif regime_filter == "breadth_5_and_20_positive":
        condition = frame["market_breadth_5"].gt(0.0) & frame["market_breadth_20"].gt(
            0.0
        )
    elif regime_filter == "breadth_5_positive_and_above_20":
        condition = frame["market_breadth_5"].gt(0.0) & frame["market_breadth_5"].gt(
            frame["market_breadth_20"]
        )
    elif regime_filter == "breadth_5_above_20_and_20_positive":
        condition = frame["market_breadth_5"].gt(frame["market_breadth_20"]) & frame[
            "market_breadth_20"
        ].gt(0.0)
    elif regime_filter == "breadth_20_positive_and_volatility_below_trailing_p75":
        condition = frame["market_breadth_20"].gt(0.0) & frame[
            "market_volatility_20"
        ].le(frame["market_volatility_20_trailing_p75"])
    elif regime_filter == "breadth_20_positive_and_volatility_below_trailing_p50":
        condition = frame["market_breadth_20"].gt(0.0) & frame[
            "market_volatility_20"
        ].le(frame["market_volatility_20_trailing_p50"])
    elif regime_filter == "breadth_20_positive_and_dispersion_below_trailing_p75":
        condition = frame["market_breadth_20"].gt(0.0) & frame[
            "market_return_dispersion_1"
        ].le(frame["market_return_dispersion_1_trailing_p75"])
    elif regime_filter == "breadth_20_positive_and_above_ma20_majority":
        condition = frame["market_breadth_20"].gt(0.0) & frame[
            "market_above_ma20_fraction"
        ].gt(0.5)
    elif (
        regime_filter
        == "breadth_20_positive_and_volatility_below_trailing_p75_and_above_ma20_majority"
    ):
        condition = (
            frame["market_breadth_20"].gt(0.0)
            & frame["market_volatility_20"].le(
                frame["market_volatility_20_trailing_p75"]
            )
            & frame["market_above_ma20_fraction"].gt(0.5)
        )
    else:
        condition = (
            frame["market_breadth_20"].gt(0.0)
            & frame["market_volatility_20"].le(
                frame["market_volatility_20_trailing_p50"]
            )
            & frame["market_above_ma20_fraction"].gt(0.5)
        )
    return frame.loc[condition.fillna(False)].copy()


def _timestamp() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _atomic_write_text(destination: Path, content: str) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", dir=destination.parent, delete=False
    ) as handle:
        handle.write(content)
        temporary = Path(handle.name)
    temporary.replace(destination)


def _atomic_write_parquet(destination: Path, frame: pd.DataFrame) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        suffix=".parquet", dir=destination.parent, delete=False
    ) as handle:
        temporary = Path(handle.name)
    frame.to_parquet(temporary, index=False, compression="zstd")
    temporary.replace(destination)


def _json_default(value: Any) -> Any:
    if isinstance(value, (pd.Timestamp, dt.datetime, dt.date)):
        return value.isoformat()
    if isinstance(value, np.generic):
        return value.item()
    raise TypeError(f"cannot serialize {type(value).__name__}")


def a_share_trade_fees(
    notional: float, side: str, rules: AShareExecutionRules
) -> dict[str, float]:
    """Calculate the configurable fees for one ordinary A-share stock trade."""

    rules.validate()
    if notional < 0:
        raise ValueError("notional must not be negative")
    if side not in {"buy", "sell"}:
        raise ValueError("side must be 'buy' or 'sell'")
    commission = (
        max(notional * rules.commission_rate, rules.commission_min) if notional else 0.0
    )
    transfer_fee = notional * rules.transfer_fee_rate
    stamp_duty = notional * rules.stamp_duty_rate if side == "sell" else 0.0
    return {
        "commission": float(commission),
        "transfer_fee": float(transfer_fee),
        "stamp_duty": float(stamp_duty),
        "total": float(commission + transfer_fee + stamp_duty),
    }


def buy_cash_required(
    price: float, quantity: int, rules: AShareExecutionRules
) -> float:
    """Return cash needed to buy an integer number of shares, including fees."""

    if price <= 0:
        raise ValueError("price must be positive")
    if quantity < 0 or quantity % rules.lot_size:
        raise ValueError("quantity must be a non-negative whole number of board lots")
    notional = price * quantity
    return float(notional + a_share_trade_fees(notional, "buy", rules)["total"])


def affordable_board_lots(
    price: float, budget: float, rules: AShareExecutionRules
) -> int:
    """Return the largest board-lot quantity whose buy cash does not exceed budget."""

    if budget < 0:
        raise ValueError("budget must not be negative")
    if price <= 0:
        raise ValueError("price must be positive")
    one_lot_cost = buy_cash_required(price, rules.lot_size, rules)
    if one_lot_cost > budget:
        return 0
    estimated_lots = int(
        budget
        // (
            price
            * rules.lot_size
            * (1.0 + rules.commission_rate + rules.transfer_fee_rate)
        )
    )
    lots = max(1, estimated_lots)
    while (
        lots and buy_cash_required(price, lots * rules.lot_size, rules) > budget + 1e-9
    ):
        lots -= 1
    return lots * rules.lot_size


def plan_lot_orders(
    candidates: list[dict[str, Any]], capital: float, rules: AShareExecutionRules
) -> dict[str, Any]:
    """Create an order-sized pilot plan without redistributing skipped slots.

    A skipped expensive stock intentionally leaves cash unused.  Reassigning
    that cash to a lower-ranked name would make a different, untested strategy.
    """

    rules.validate()
    if capital <= 0:
        raise ValueError("capital must be positive")
    if not candidates:
        raise ValueError("at least one candidate is required")
    if len(candidates) * rules.target_weight > rules.max_gross_exposure + 1e-12:
        raise ValueError("candidate target weights exceed max_gross_exposure")

    target_cash = capital * rules.target_weight
    orders: list[dict[str, Any]] = []
    for fallback_rank, candidate in enumerate(candidates, start=1):
        price = float(candidate["reference_close"])
        quantity = affordable_board_lots(price, target_cash, rules)
        rank = int(candidate.get("rank", fallback_rank))
        name = str(candidate.get("name", ""))
        instrument = str(candidate["instrument"])
        if quantity == 0:
            one_lot_cash = buy_cash_required(price, rules.lot_size, rules)
            orders.append(
                {
                    "rank": rank,
                    "instrument": instrument,
                    "name": name,
                    "reference_close": price,
                    "target_weight": rules.target_weight,
                    "status": "skipped_insufficient_budget_for_one_lot",
                    "minimum_one_lot_cash": one_lot_cash,
                    "target_cash": target_cash,
                    "reason": "Cash is not reallocated to preserve the declared equal-weight candidate rule.",
                }
            )
            continue

        notional = price * quantity
        buy_fees = a_share_trade_fees(notional, "buy", rules)
        sell_fees_at_reference = a_share_trade_fees(notional, "sell", rules)
        buy_cash = notional + buy_fees["total"]
        orders.append(
            {
                "rank": rank,
                "instrument": instrument,
                "name": name,
                "reference_close": price,
                "target_weight": rules.target_weight,
                "status": "planned_at_reference_price",
                "quantity": quantity,
                "board_lots": quantity // rules.lot_size,
                "notional": notional,
                "buy_fees": buy_fees,
                "estimated_buy_cash": buy_cash,
                "estimated_sell_fees_at_reference": sell_fees_at_reference,
                "estimated_round_trip_fees_at_reference": buy_fees["total"]
                + sell_fees_at_reference["total"],
                "actual_portfolio_weight": buy_cash / capital,
            }
        )

    planned = [
        order for order in orders if order["status"] == "planned_at_reference_price"
    ]
    total_buy_cash = float(sum(order["estimated_buy_cash"] for order in planned))
    max_buy_cash = capital * rules.max_gross_exposure
    if total_buy_cash > max_buy_cash + 1e-9:
        raise RuntimeError("lot plan exceeds configured max_gross_exposure")
    return {
        "capital": capital,
        "rules": {
            "lot_size": rules.lot_size,
            "commission_rate": rules.commission_rate,
            "commission_min": rules.commission_min,
            "transfer_fee_rate": rules.transfer_fee_rate,
            "stamp_duty_rate": rules.stamp_duty_rate,
            "max_gross_exposure": rules.max_gross_exposure,
            "target_weight": rules.target_weight,
        },
        "target_cash_per_candidate": target_cash,
        "max_pilot_cash": max_buy_cash,
        "orders": orders,
        "summary": {
            "requested_candidates": len(candidates),
            "planned_candidates": len(planned),
            "skipped_candidates": len(candidates) - len(planned),
            "estimated_buy_cash": total_buy_cash,
            "actual_gross_exposure": total_buy_cash / capital,
            "cash_remaining_after_plan": capital - total_buy_cash,
            "unused_pilot_budget": max_buy_cash - total_buy_cash,
        },
        "limitations": [
            "Reference close is for sizing only; it is not a live quote, order price, or buy instruction.",
            "The plan does not model intraday price movement, limit-up/limit-down, suspension, slippage, or order fills.",
            "Skipped slots are not reallocated; changing that rule requires a separately tested portfolio construction policy.",
        ],
    }


def file_sha256(path: Path) -> str:
    """Return the content fingerprint recorded alongside every experiment."""

    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def point_in_time_interval_fingerprint(
    path: Path,
    *,
    start: str,
    end: str,
) -> dict[str, Any]:
    """Fingerprint normalized instrument intervals clipped to a frozen range."""

    frame = pd.read_csv(
        path.expanduser().resolve(),
        sep="\t",
        header=None,
        names=["instrument", "active_start", "active_end"],
        dtype={"instrument": "string"},
    )
    frame["active_start"] = pd.to_datetime(
        frame["active_start"], errors="coerce"
    ).dt.normalize()
    frame["active_end"] = pd.to_datetime(
        frame["active_end"], errors="coerce"
    ).dt.normalize()
    if (
        frame.empty
        or frame[["instrument", "active_start", "active_end"]].isna().any().any()
        or frame["instrument"].duplicated().any()
        or not frame["instrument"].str.fullmatch(r"(?:SH6|SZ[03])\d{5}", na=False).all()
        or frame["active_start"].gt(frame["active_end"]).any()
    ):
        raise ValueError(f"invalid point-in-time instrument file: {path}")
    start_date = pd.Timestamp(start).normalize()
    end_date = pd.Timestamp(end).normalize()
    clipped = frame.loc[
        frame["active_start"].le(end_date) & frame["active_end"].ge(start_date)
    ].copy()
    clipped["active_start"] = clipped["active_start"].clip(lower=start_date)
    clipped["active_end"] = clipped["active_end"].clip(upper=end_date)
    clipped = clipped.sort_values("instrument", kind="stable")
    records = [
        {
            "instrument": str(row.instrument),
            "active_start": pd.Timestamp(row.active_start).date().isoformat(),
            "active_end": pd.Timestamp(row.active_end).date().isoformat(),
        }
        for row in clipped.itertuples(index=False)
    ]
    encoded = json.dumps(
        records, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return {"sha256": hashlib.sha256(encoded).hexdigest(), "intervals": len(records)}


def local_calendar_range_fingerprint(
    path: Path,
    *,
    start: str,
    end: str,
) -> dict[str, Any]:
    """Fingerprint normalized local sessions inside a frozen date range."""

    values = pd.to_datetime(
        path.expanduser().resolve().read_text(encoding="utf-8").splitlines(),
        errors="coerce",
    )
    if pd.isna(values).any():
        raise ValueError(f"invalid local calendar file: {path}")
    sessions = pd.DatetimeIndex(values).normalize().unique().sort_values()
    sessions = sessions[
        (sessions >= pd.Timestamp(start).normalize())
        & (sessions <= pd.Timestamp(end).normalize())
    ]
    if sessions.empty:
        raise ValueError(f"local calendar has no sessions in frozen range: {path}")
    encoded = json.dumps(
        [date.date().isoformat() for date in sessions],
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    return {"sha256": hashlib.sha256(encoded).hexdigest(), "sessions": len(sessions)}


def dataframe_content_sha256(frame: pd.DataFrame) -> str:
    """Match the rich-data manifest's stable, storage-independent frame hash."""

    content = frame.to_csv(index=False, lineterminator="\n").encode("utf-8")
    return hashlib.sha256(content).hexdigest()


def resolve_repository_record_path(value: str | Path) -> Path:
    """Resolve repository-relative paths stored by immutable rich-data records."""

    path = Path(value).expanduser()
    if not path.is_absolute():
        path = REPO_ROOT / path
    return path.resolve()


def load_json_record(path: Path, *, kind: str | None = None) -> dict[str, Any]:
    """Load one immutable JSON record and optionally enforce its kind."""

    path = path.expanduser().resolve()
    if not path.exists():
        raise FileNotFoundError(f"JSON record does not exist: {path}")
    try:
        record = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise ValueError(f"JSON record is invalid: {path}") from error
    if not isinstance(record, dict):
        raise ValueError(f"JSON record must contain an object: {path}")
    if kind is not None and record.get("kind") != kind:
        raise ValueError(f"expected {kind!r}, got {record.get('kind')!r}: {path}")
    return record


def load_research_frontier_contract(
    path: Path = DEFAULT_RESEARCH_FRONTIER_CONTRACT,
) -> dict[str, Any]:
    """Load the fingerprint-frozen inventory of authoritative historical branches."""

    path = path.expanduser().resolve()
    if file_sha256(path) != RESEARCH_FRONTIER_CONTRACT_SHA256:
        raise ValueError("three-day research frontier contract fingerprint mismatch")
    contract = load_json_record(
        path, kind="a_share_three_day_research_frontier_contract"
    )
    if contract.get("status") != (
        "frozen_after_current_accepted_price_diagnostics_before_any_new_data_mechanism"
    ):
        raise ValueError(
            "three-day research frontier contract has an unsupported status"
        )
    groups = list(contract.get("evidence_groups") or [])
    expected = contract.get("expected_result") or {}
    if len(groups) != expected.get("evidence_group_count"):
        raise ValueError("three-day research frontier evidence-group count changed")
    if not groups or any(not isinstance(item, dict) for item in groups):
        raise ValueError(
            "three-day research frontier evidence groups must be non-empty objects"
        )
    return contract


