    path = path.expanduser().resolve()
    if file_sha256(path) != TUSHARE_SW_INDUSTRY_BREADTH_SYMBOL_REPAIR_SHA256:
        raise ValueError("Tushare SW symbol-repair fingerprint mismatch")
