def load_tushare_free_float_scarcity_research_record(
    path: Path = DEFAULT_TUSHARE_FREE_FLOAT_SCARCITY_RESEARCH_RECORD,
) -> dict[str, Any]:
    """Enforce the terminal no-return rejection in every clone."""

    path = path.expanduser().resolve()
    if file_sha256(path) != TUSHARE_FREE_FLOAT_SCARCITY_RESEARCH_RECORD_SHA256:
        raise ValueError(
            "Tushare free-float-scarcity research-record fingerprint mismatch"
        )
    record = load_json_record(
        path, kind="a_share_tushare_free_float_scarcity_research_record"
    )
    evidence = record.get("evidence_chain") or {}
    capacity = record.get("source_and_capacity_result") or {}
    uniqueness = record.get("uniqueness_result") or {}
    neighbor = uniqueness.get("named_near_neighbor") or {}
    decision = record.get("decision") or {}
    terminal = evidence.get("terminal_no_return_audit") or {}
    if (
        record.get("status")
        != "terminal_rejected_at_no_return_uniqueness_gate_insufficient_pairwise_sessions"
        or (evidence.get("full_source_record") or {}).get("sha256")
        != TUSHARE_FREE_FLOAT_SCARCITY_FULL_SOURCE_RECORD_SHA256
        or (evidence.get("full_source_manifest") or {}).get("sha256")
        != TUSHARE_FREE_FLOAT_SCARCITY_FULL_MANIFEST_SHA256
        or terminal.get("sha256")
        != "062a6ef240caeeaac3a39ed811a22d8042e858c1a83485514af2818a1100b70e"
        or capacity.get("potential_complete_cohorts") != 540
        or capacity.get("minimum_required_cohorts") != 200
        or capacity.get("capacity_gate_passed") is not True
        or uniqueness.get("comparison_field_count") != 54
        or uniqueness.get("fields_with_minimum_sessions") != 46
        or uniqueness.get("nearest_existing_field") != "liquidity_5"
        or not math.isclose(
            float(
                uniqueness.get(
                    "maximum_observed_absolute_median_daily_rank_correlation"
                )
            ),
            0.2558649244428563,
            rel_tol=0.0,
            abs_tol=1e-15,
        )
        or neighbor.get("comparison_field") != "free_float_cap_proxy"
        or not math.isclose(
            float(neighbor.get("median_daily_rank_correlation")),
            -0.13715972731775472,
            rel_tol=0.0,
            abs_tol=1e-15,
        )
        or uniqueness.get("uniqueness_gate_passed") is not False
        or decision.get("both_no_return_gates_passed") is not False
        or decision.get("factor_return_diagnostic_allowed") is not False
        or decision.get("same_source_snapshot_rerun_allowed") is not False
        or decision.get("aggregation_scoring_selection_sizing_or_orders_allowed")
        is not False
        or record.get("price_fields_loaded_for_capacity") != []
        or record.get("forward_return_fields_read") is not False
        or record.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError("Tushare free-float-scarcity terminal research record changed")
    terminal_path = resolve_repository_record_path(str(terminal.get("path") or ""))
    if terminal_path.exists() and file_sha256(terminal_path) != terminal["sha256"]:
        raise ValueError("Tushare free-float-scarcity terminal no-return audit changed")
    return record


