def normalize_fundamental_rows(
    rows: Iterable[dict[str, Any]], report_date: str
) -> pd.DataFrame:
    """Reduce provider-specific financial rows to the PIT fields needed by research.

    Eastmoney can expose later corrections for a prior report.  Keeping the
    earliest notice per instrument/report period is a conservative approximation
    of the first public disclosure, but it is not an immutable vendor PIT data
    set; that caveat is carried into every experiment record.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=FUNDAMENTAL_COLUMNS)
    frame = pd.DataFrame(
        {
            "instrument": raw.get("SECURITY_CODE", pd.Series(dtype="object")).map(
                qlib_symbol
            ),
            "report_date": pd.to_datetime(report_date),
            "announcement_date": pd.to_datetime(
                raw.get("NOTICE_DATE"), errors="coerce"
            ),
            "roe": pd.to_numeric(raw.get("WEIGHTAVG_ROE"), errors="coerce"),
            "net_profit": pd.to_numeric(raw.get("PARENT_NETPROFIT"), errors="coerce"),
            "revenue_yoy": pd.to_numeric(raw.get("YSTZ"), errors="coerce"),
            "profit_yoy": pd.to_numeric(raw.get("SJLTZ"), errors="coerce"),
        }
    )
    frame = frame.dropna(subset=["instrument", "announcement_date"])
    frame = frame.sort_values(
        ["instrument", "report_date", "announcement_date"], kind="stable"
    )
    return frame.drop_duplicates(
        ["instrument", "report_date"], keep="first"
    ).reset_index(drop=True)


def normalize_performance_forecast_rows(
    rows: Iterable[dict[str, Any]], report_date: str
) -> pd.DataFrame:
    """Reduce forecast notices to dated, numerically auditable event fields.

    The endpoint mixes revenue, EPS, non-recurring-profit, and net-profit
    forecasts.  Only its ``PREDICT_FINANCE_CODE == '004'`` rows describe the
    parent-company net profit stated by this research hypothesis.  The lower
    and upper YoY forecast midpoint is the directional forecast and their
    distance is its disclosed uncertainty.  A later announcement is retained
    as a new event: when it was publicly filed it could have superseded an
    earlier forecast.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=PERFORMANCE_FORECAST_COLUMNS)
    finance_code = raw.get(
        "PREDICT_FINANCE_CODE", pd.Series(index=raw.index, dtype="object")
    )
    raw = raw.loc[finance_code.astype("string").eq("004")].copy()
    if raw.empty:
        return pd.DataFrame(columns=PERFORMANCE_FORECAST_COLUMNS)
    lower = pd.to_numeric(
        raw.get("ADD_AMP_LOWER", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    upper = pd.to_numeric(
        raw.get("ADD_AMP_UPPER", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    midpoint = pd.concat([lower, upper], axis=1).mean(axis=1)
    frame = pd.DataFrame(
        {
            "instrument": raw.get("SECURITY_CODE", pd.Series(dtype="object")).map(
                qlib_symbol
            ),
            "report_date": pd.to_datetime(report_date),
            "announcement_date": pd.to_datetime(
                raw.get("NOTICE_DATE"), errors="coerce"
            ),
            "forecast_type": raw.get(
                "PREDICT_TYPE", pd.Series(index=raw.index, dtype="object")
            ).astype("string"),
            "forecast_turnaround": raw.get(
                "PREDICT_TYPE", pd.Series(index=raw.index, dtype="object")
            )
            .astype("string")
            .fillna("")
            .eq("扭亏")
            .astype(float),
            "forecast_profit_yoy": midpoint,
            "forecast_profit_yoy_width": (upper - lower).abs(),
        }
    )
    frame = frame.dropna(subset=["instrument", "announcement_date"])
    frame = frame.sort_values(
        ["instrument", "report_date", "announcement_date"], kind="stable"
    )
    return frame.drop_duplicates(
        ["instrument", "report_date", "announcement_date"], keep="first"
    ).reset_index(drop=True)


def normalize_billboard_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate same-day billboard reasons into only close-known event inputs.

    A stock can satisfy multiple disclosure reasons on a session.  The raw
    money fields can be identical for duplicate reasons or differ for separate
    abnormal-trading windows, so each ratio is represented by its same-day
    median rather than an unsafe sum.  The number of distinct reasons is
    retained as an independent event-intensity measure.  Provider fields that
    describe returns after the event are intentionally absent from this
    schema.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=BILLBOARD_EVENT_COLUMNS)
    net = pd.to_numeric(
        raw.get("BILLBOARD_NET_AMT", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    deal = pd.to_numeric(
        raw.get("BILLBOARD_DEAL_AMT", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    floating = pd.to_numeric(
        raw.get("FREE_MARKET_CAP", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    with np.errstate(divide="ignore", invalid="ignore"):
        net_to_float = net / floating
        net_to_deal = net / deal
        deal_to_float = deal / floating
    frame = pd.DataFrame(
        {
            "instrument": raw.get("SECURITY_CODE", pd.Series(dtype="object")).map(
                qlib_symbol
            ),
            "trade_date": pd.to_datetime(raw.get("TRADE_DATE"), errors="coerce"),
            "billboard_net_flow_to_float": net_to_float,
            "billboard_net_flow_to_deal": net_to_deal,
            "billboard_deal_to_float": deal_to_float,
            "_reason": raw.get(
                "EXPLANATION", pd.Series(index=raw.index, dtype="object")
            ).astype("string"),
        }
    )
    frame = frame.replace([np.inf, -np.inf], np.nan).dropna(
        subset=["instrument", "trade_date"]
    )
    aggregated = (
        frame.groupby(["instrument", "trade_date"], as_index=False, sort=True)
        .agg(
            billboard_net_flow_to_float=("billboard_net_flow_to_float", "median"),
            billboard_net_flow_to_deal=("billboard_net_flow_to_deal", "median"),
            billboard_deal_to_float=("billboard_deal_to_float", "median"),
            billboard_reason_count=("_reason", "nunique"),
        )
        .loc[:, list(BILLBOARD_EVENT_COLUMNS)]
    )
    aggregated["billboard_reason_count"] = pd.to_numeric(
        aggregated["billboard_reason_count"], errors="coerce"
    ).astype(float)
    return aggregated.sort_values(
        ["instrument", "trade_date"], kind="stable"
    ).reset_index(drop=True)


def normalize_major_holder_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate major-holder changes by the date they were publicly noticed.

    ``CHANGE_FREE_RATIO`` is a disclosed percentage of freely tradable shares.
    It is treated as a magnitude and signed only by the provider's explicit
    ``DIRECTION`` label, not by the historical transaction date or the source
    price.  This deliberately leaves all current quotes, execution prices,
    and unannounced transaction dates out of the event snapshot.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=MAJOR_HOLDER_EVENT_COLUMNS)
    direction = raw.get("DIRECTION", pd.Series(index=raw.index, dtype="object")).astype(
        "string"
    )
    ratio = pd.to_numeric(
        raw.get("CHANGE_FREE_RATIO", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    ).abs()
    increase = ratio.where(direction.eq("增持"), 0.0)
    decrease = ratio.where(direction.eq("减持"), 0.0)
    frame = pd.DataFrame(
        {
            "instrument": raw.get("SECURITY_CODE", pd.Series(dtype="object")).map(
                qlib_symbol
            ),
            "announcement_date": pd.to_datetime(
                raw.get("NOTICE_DATE"), errors="coerce"
            ),
            "major_holder_increase_free_ratio": increase,
            "major_holder_decrease_free_ratio": decrease,
        }
    )
    frame = frame.dropna(subset=["instrument", "announcement_date"])
    frame["major_holder_net_change_free_ratio"] = (
        frame["major_holder_increase_free_ratio"]
        - frame["major_holder_decrease_free_ratio"]
    )
    aggregated = (
        frame.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            major_holder_net_change_free_ratio=(
                "major_holder_net_change_free_ratio",
                "sum",
            ),
            major_holder_increase_free_ratio=(
                "major_holder_increase_free_ratio",
                "sum",
            ),
            major_holder_decrease_free_ratio=(
                "major_holder_decrease_free_ratio",
                "sum",
            ),
            major_holder_event_count=("instrument", "size"),
        )
        .loc[:, list(MAJOR_HOLDER_EVENT_COLUMNS)]
    )
    for column in MAJOR_HOLDER_EVENT_COLUMNS[2:]:
        aggregated[column] = pd.to_numeric(aggregated[column], errors="coerce")
    return aggregated.sort_values(
        ["instrument", "announcement_date"], kind="stable"
    ).reset_index(drop=True)


def normalize_block_trade_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate block trades to same-close stock/day features without outcomes.

    The premium/discount is weighted by disclosed deal amount, while turnover
    ratio and count accumulate across all transactions of that stock/session.
    Raw prices are not retained: only the provider's already-derived
    contemporaneous premium and turnover ratio enter the event snapshot.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=BLOCK_TRADE_EVENT_COLUMNS)
    amount = pd.to_numeric(
        raw.get("DEAL_AMT", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    premium = pd.to_numeric(
        raw.get("PREMIUM_RATIO", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    turnover = pd.to_numeric(
        raw.get("TURNOVER_RATE", pd.Series(index=raw.index, dtype="float64")),
        errors="coerce",
    )
    frame = pd.DataFrame(
        {
            "instrument": raw.get("SECURITY_CODE", pd.Series(dtype="object")).map(
                qlib_symbol
            ),
            "trade_date": pd.to_datetime(raw.get("TRADE_DATE"), errors="coerce"),
            "_amount": amount,
            "_premium_x_amount": premium * amount,
            "_premium_weight": amount.where(premium.notna()),
            "block_trade_turnover_rate": turnover,
        }
    )
    frame = frame.replace([np.inf, -np.inf], np.nan).dropna(
        subset=["instrument", "trade_date"]
    )
    grouped = frame.groupby(
        ["instrument", "trade_date"], as_index=False, sort=True
    ).agg(
        _amount=("_amount", "sum"),
        _premium_x_amount=("_premium_x_amount", "sum"),
        _premium_weight=("_premium_weight", "sum"),
        block_trade_turnover_rate=("block_trade_turnover_rate", "sum"),
        block_trade_event_count=("instrument", "size"),
    )
    with np.errstate(divide="ignore", invalid="ignore"):
        grouped["block_trade_premium_ratio"] = (
            grouped["_premium_x_amount"] / grouped["_premium_weight"]
        )
    aggregated = grouped.loc[:, list(BLOCK_TRADE_EVENT_COLUMNS)].replace(
        [np.inf, -np.inf], np.nan
    )
    for column in BLOCK_TRADE_EVENT_COLUMNS[2:]:
        aggregated[column] = pd.to_numeric(aggregated[column], errors="coerce")
    return aggregated.sort_values(
        ["instrument", "trade_date"], kind="stable"
    ).reset_index(drop=True)


def normalize_margin_financing_top_flow_rows(
    rows: Iterable[dict[str, Any]],
) -> pd.DataFrame:
    """Reduce public financing data to same-close, size-normalized event fields.

    The input is already the declared daily Top-N by financing net buy.  It is
    *not* treated as an observation of no financing activity for omitted
    stocks.  Ratio normalization uses the provider's same-session market cap
    and excludes ETFs/non-A-share codes through ``qlib_symbol``.  No source
    price, same-day return, or post-event return field is retained.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=MARGIN_FINANCING_EVENT_COLUMNS)
    net_buy = pd.to_numeric(
        raw.get("RZJME", pd.Series(index=raw.index, dtype="float64")), errors="coerce"
    )
    buy = pd.to_numeric(
        raw.get("RZMRE", pd.Series(index=raw.index, dtype="float64")), errors="coerce"
    )
    balance = pd.to_numeric(
        raw.get("RZYE", pd.Series(index=raw.index, dtype="float64")), errors="coerce"
    )
    market_cap = pd.to_numeric(
        raw.get("SZ", pd.Series(index=raw.index, dtype="float64")), errors="coerce"
    )
    with np.errstate(divide="ignore", invalid="ignore"):
        net_buy_to_market_cap = net_buy / market_cap
        buy_to_market_cap = buy / market_cap
        balance_to_market_cap = balance / market_cap
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SCODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "trade_date": pd.to_datetime(raw.get("DATE"), errors="coerce"),
            "margin_net_buy_to_market_cap": net_buy_to_market_cap,
            "margin_buy_to_market_cap": buy_to_market_cap,
            "margin_balance_to_market_cap": balance_to_market_cap,
            "margin_financing_balance_growth": pd.to_numeric(
                raw.get("FIN_BALANCE_GR", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    )
    frame = frame.replace([np.inf, -np.inf], np.nan).dropna(
        subset=["instrument", "trade_date"]
    )
    for column in MARGIN_FINANCING_EVENT_COLUMNS[2:]:
        frame[column] = pd.to_numeric(frame[column], errors="coerce")
    return (
        frame.loc[:, list(MARGIN_FINANCING_EVENT_COLUMNS)]
        .sort_values(["instrument", "trade_date"], kind="stable")
        .drop_duplicates(["instrument", "trade_date"], keep="last")
        .reset_index(drop=True)
    )


def normalize_securities_lending_rows(
    rows: Iterable[dict[str, Any]],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Normalize the frozen full-market lending counts and exclude zero activity."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=SECURITIES_LENDING_EVENT_COLUMNS), {
            "input_source_rows": 0,
            "missing_or_non_a_share_rows_excluded": 0,
            "negative_raw_count_rows_excluded": 0,
            "zero_activity_rows_excluded": 0,
            "rows_written": 0,
        }
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SCODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "trade_date": pd.to_datetime(
                raw.get("DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ).dt.normalize(),
            "securities_lending_balance_shares": pd.to_numeric(
                raw.get("RQYL", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "securities_lending_sell_shares": pd.to_numeric(
                raw.get("RQMCL", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "securities_lending_repay_shares": pd.to_numeric(
                raw.get("RQCHL", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    )
    contracted = list(SECURITIES_LENDING_EVENT_COLUMNS[:5])
    complete_key = frame[contracted].notna().all(axis=1)
    missing_or_non_a_share = int((~complete_key).sum())
    complete = frame.loc[complete_key].copy()
    raw_count_columns = [
        "securities_lending_balance_shares",
        "securities_lending_sell_shares",
        "securities_lending_repay_shares",
    ]
    nonnegative = complete[raw_count_columns].ge(0.0).all(axis=1)
    negative = int((~nonnegative).sum())
    valid = complete.loc[nonnegative].copy()
    activity = (
        valid["securities_lending_sell_shares"]
        + valid["securities_lending_repay_shares"]
    )
    active = activity.gt(0.0)
    zero_activity = int((~active).sum())
    valid = valid.loc[active].copy()
    active_total = activity.loc[active]
    valid[raw_count_columns] = valid[raw_count_columns].astype("float64")
    valid[SECURITIES_LENDING_FACTOR_NAME] = (
        valid["securities_lending_repay_shares"]
        - valid["securities_lending_sell_shares"]
    ) / active_total
    result = (
        valid.loc[:, list(SECURITIES_LENDING_EVENT_COLUMNS)]
        .sort_values(["trade_date", "instrument"], kind="stable")
        .reset_index(drop=True)
    )
    stats = {
        "input_source_rows": int(len(frame)),
        "missing_or_non_a_share_rows_excluded": missing_or_non_a_share,
        "negative_raw_count_rows_excluded": negative,
        "zero_activity_rows_excluded": zero_activity,
        "rows_written": int(len(result)),
    }
    return result, stats


def _institutional_survey_detail_frame(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Collapse repeated participant rows to one dated survey event.

    The detailed Eastmoney report emits one row per received institution while
    repeating ``SUM`` for the disclosure.  The source does not expose a stable
    survey identifier, so the conservative event key is issuer plus public
    notice date and disclosed received-date range.  This helper retains no
    participant identity and is kept separate so sync pagination cannot double
    count a disclosure split between two API pages.
    """

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(
            columns=[
                "instrument",
                "announcement_date",
                "receive_start_date",
                "receive_end_date",
                "institutional_survey_org_count",
            ]
        )
    start = pd.to_datetime(
        raw.get("RECEIVE_START_DATE", pd.Series(index=raw.index, dtype="object")),
        errors="coerce",
    )
    end = pd.to_datetime(
        raw.get("RECEIVE_END_DATE", pd.Series(index=raw.index, dtype="object")),
        errors="coerce",
    )
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SECURITY_CODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("NOTICE_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "receive_start_date": start,
            "receive_end_date": end.fillna(start),
            "institutional_survey_org_count": pd.to_numeric(
                raw.get("SUM", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    )
    frame = frame.dropna(
        subset=["instrument", "announcement_date", "receive_start_date"]
    )
    return (
        frame.groupby(
            [
                "instrument",
                "announcement_date",
                "receive_start_date",
                "receive_end_date",
            ],
            as_index=False,
            sort=True,
            dropna=False,
        )["institutional_survey_org_count"]
        .max()
        .sort_values(
            ["instrument", "announcement_date", "receive_start_date"], kind="stable"
        )
        .reset_index(drop=True)
    )


def normalize_institutional_survey_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate public institutional-survey notices without participant data.

    The per-event maximum of source ``SUM`` is the reported number of received
    institutions, rather than the count of duplicated detail rows.  If a
    company discloses multiple received-date ranges on one notice date, their
    reported counts are summed and the separate events are retained as a
    second, independent intensity field.  Missing reported counts stay missing
    rather than being imputed as no institutional attention.
    """

    details = _institutional_survey_detail_frame(rows)
    return aggregate_institutional_survey_details(details)


def aggregate_institutional_survey_details(details: pd.DataFrame) -> pd.DataFrame:
    """Aggregate page-level institutional-survey events to score-time rows."""

    required = {
        "instrument",
        "announcement_date",
        "receive_start_date",
        "receive_end_date",
        "institutional_survey_org_count",
    }
    if missing := sorted(required - set(details.columns)):
        raise ValueError(
            "institutional-survey detail frame is missing columns: "
            + ", ".join(missing)
        )
    if details.empty:
        return pd.DataFrame(columns=INSTITUTIONAL_SURVEY_EVENT_COLUMNS)
    source = details.loc[:, sorted(required)].copy()
    for column in ("announcement_date", "receive_start_date", "receive_end_date"):
        source[column] = pd.to_datetime(source[column], errors="coerce")
    source["institutional_survey_org_count"] = pd.to_numeric(
        source["institutional_survey_org_count"], errors="coerce"
    )
    source = source.dropna(
        subset=["instrument", "announcement_date", "receive_start_date"]
    )
    events = source.groupby(
        ["instrument", "announcement_date", "receive_start_date", "receive_end_date"],
        as_index=False,
        sort=True,
        dropna=False,
    )["institutional_survey_org_count"].max()
    result = (
        events.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            institutional_survey_org_count=(
                "institutional_survey_org_count",
                lambda values: values.sum(min_count=1),
            ),
            institutional_survey_event_count=("receive_start_date", "size"),
        )
        .loc[:, list(INSTITUTIONAL_SURVEY_EVENT_COLUMNS)]
    )
    result["institutional_survey_event_count"] = pd.to_numeric(
        result["institutional_survey_event_count"], errors="coerce"
    ).astype(float)
    return result.sort_values(
        ["instrument", "announcement_date"], kind="stable"
    ).reset_index(drop=True)


def aggregate_institutional_survey_timing_details(
    details: pd.DataFrame,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Build the frozen issuer/announcement disclosure-lag snapshot."""

    required = {
        "instrument",
        "announcement_date",
        "receive_start_date",
        "receive_end_date",
    }
    if missing := sorted(required - set(details.columns)):
        raise ValueError(
            "institutional-survey timing detail frame is missing columns: "
            + ", ".join(missing)
        )
    if details.empty:
        return pd.DataFrame(columns=INSTITUTIONAL_SURVEY_TIMING_EVENT_COLUMNS), {
            "input_detail_rows": 0,
            "unique_received_ranges": 0,
            "invalid_start_after_end_rows": 0,
            "negative_lag_event_keys_excluded": 0,
            "rows_written": 0,
            "distinct_disclosure_lag_values": 0,
        }
    source = details.loc[:, sorted(required)].copy()
    source["instrument"] = source["instrument"].astype("string")
    for column in ("announcement_date", "receive_start_date", "receive_end_date"):
        source[column] = pd.to_datetime(source[column], errors="coerce").dt.normalize()
    source["receive_end_date"] = source["receive_end_date"].fillna(
        source["receive_start_date"]
    )
    source = source.dropna(
        subset=["instrument", "announcement_date", "receive_start_date"]
    )
    invalid_start_after_end = int(
        source["receive_start_date"].gt(source["receive_end_date"]).sum()
    )
    if invalid_start_after_end:
        raise ValueError(
            "institutional-survey timing source contains receive_start_date after receive_end_date"
        )
    ranges = source.drop_duplicates(
        ["instrument", "announcement_date", "receive_start_date", "receive_end_date"]
    )
    events = (
        ranges.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(institutional_survey_latest_receive_end_date=("receive_end_date", "max"))
        .sort_values(["instrument", "announcement_date"], kind="stable")
    )
    events["institutional_survey_disclosure_lag_days"] = (
        events["announcement_date"]
        - events["institutional_survey_latest_receive_end_date"]
    ).dt.days
    negative = events["institutional_survey_disclosure_lag_days"].lt(0)
    negative_count = int(negative.sum())
    result = events.loc[
        ~negative, list(INSTITUTIONAL_SURVEY_TIMING_EVENT_COLUMNS)
    ].copy()
    result["institutional_survey_disclosure_lag_days"] = pd.to_numeric(
        result["institutional_survey_disclosure_lag_days"], errors="coerce"
    ).astype(float)
    result = result.dropna(subset=list(INSTITUTIONAL_SURVEY_TIMING_EVENT_COLUMNS))
    result = result.drop_duplicates(["instrument", "announcement_date"], keep="last")
    result = result.sort_values(
        ["instrument", "announcement_date"], kind="stable"
    ).reset_index(drop=True)
    lags = result["institutional_survey_disclosure_lag_days"]
    stats = {
        "input_detail_rows": int(len(source)),
        "unique_received_ranges": int(len(ranges)),
        "invalid_start_after_end_rows": invalid_start_after_end,
        "negative_lag_event_keys_excluded": negative_count,
        "rows_written": int(len(result)),
        "distinct_disclosure_lag_values": int(lags.nunique()),
        "disclosure_lag_days": {
            "minimum": float(lags.min()),
            "median": float(lags.median()),
            "p95": float(lags.quantile(0.95)),
            "maximum": float(lags.max()),
        },
    }
    return result, stats


def _analyst_rating_detail_frame(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Normalize only the four preregistered analyst-rating source fields."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(
            columns=["info_code", "instrument", "announcement_date", "rating_change"]
        )
    frame = pd.DataFrame(
        {
            "info_code": raw.get(
                "infoCode", pd.Series(index=raw.index, dtype="object")
            ),
            "instrument": raw.get(
                "stockCode", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("publishDate", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ).dt.normalize(),
            "rating_change": pd.to_numeric(
                raw.get("ratingChange", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    )
    frame["info_code"] = frame["info_code"].astype("string").str.strip()
    frame.loc[frame["info_code"].eq(""), "info_code"] = pd.NA
    return frame


def aggregate_analyst_rating_details(
    details: pd.DataFrame,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Aggregate recognized rating adjustments to one issuer/publication-date event."""

    required = {"info_code", "instrument", "announcement_date", "rating_change"}
    if missing := sorted(required - set(details.columns)):
        raise ValueError(
            "analyst-rating detail frame is missing columns: " + ", ".join(missing)
        )
    if details.empty:
        return pd.DataFrame(columns=ANALYST_RATING_EVENT_COLUMNS), {
            "input_source_rows": 0,
            "missing_or_non_a_share_rows_excluded": 0,
            "unclassified_or_missing_rating_rows_excluded": 0,
            "recognized_rating_rows": 0,
            "upgrade_rows": 0,
            "rows_written": 0,
            "distinct_upgrade_share_values": 0,
        }
    source = details.loc[
        :, ["info_code", "instrument", "announcement_date", "rating_change"]
    ].copy()
    source["announcement_date"] = pd.to_datetime(
        source["announcement_date"], errors="coerce"
    ).dt.normalize()
    source["rating_change"] = pd.to_numeric(source["rating_change"], errors="coerce")
    invalid_key = (
        source[["info_code", "instrument", "announcement_date"]].isna().any(axis=1)
    )
    invalid_key_count = int(invalid_key.sum())
    source = source.loc[~invalid_key].copy()
    if source["info_code"].duplicated().any():
        duplicates = int(source["info_code"].duplicated(keep=False).sum())
        raise ValueError(
            f"analyst-rating source contains {duplicates} duplicate infoCode rows"
        )
    recognized = source["rating_change"].isin([0, 1, 2, 3])
    excluded_rating_count = int((~recognized).sum())
    valid = source.loc[recognized].copy()
    valid["is_upgrade"] = valid["rating_change"].eq(0).astype(float)
    result = (
        valid.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            analyst_rating_upgrade_share=("is_upgrade", "mean"),
            analyst_valid_rating_report_count=("is_upgrade", "size"),
        )
        .loc[:, list(ANALYST_RATING_EVENT_COLUMNS)]
        .sort_values(["instrument", "announcement_date"], kind="stable")
        .reset_index(drop=True)
    )
    result["analyst_rating_upgrade_share"] = pd.to_numeric(
        result["analyst_rating_upgrade_share"], errors="coerce"
    ).astype(float)
    result["analyst_valid_rating_report_count"] = pd.to_numeric(
        result["analyst_valid_rating_report_count"], errors="coerce"
    ).astype(float)
    stats = {
        "input_source_rows": int(len(details)),
        "missing_or_non_a_share_rows_excluded": invalid_key_count,
        "unclassified_or_missing_rating_rows_excluded": excluded_rating_count,
        "recognized_rating_rows": int(len(valid)),
        "upgrade_rows": int(valid["is_upgrade"].sum()),
        "rows_written": int(len(result)),
        "distinct_upgrade_share_values": int(
            result["analyst_rating_upgrade_share"].nunique()
        ),
    }
    return result, stats


def normalize_analyst_rating_rows(
    rows: Iterable[dict[str, Any]],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Normalize and aggregate public analyst-rating records without report text or prices."""

    return aggregate_analyst_rating_details(_analyst_rating_detail_frame(rows))


def normalize_restricted_share_unlock_rows(
    rows: Iterable[dict[str, Any]],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Normalize only the frozen non-price restricted-share unlock fields."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS), {
            "input_source_rows": 0,
            "missing_or_non_a_share_rows_excluded": 0,
            "rows_written": 0,
            "zero_ratio_rows": 0,
        }
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SECURITY_CODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "event_date": pd.to_datetime(
                raw.get("FREE_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "restricted_unlock_total_share_ratio": pd.to_numeric(
                raw.get("TOTAL_RATIO", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "restricted_unlock_actual_shares": pd.to_numeric(
                raw.get(
                    "CURRENT_FREE_SHARES", pd.Series(index=raw.index, dtype="float64")
                ),
                errors="coerce",
            ),
        }
    )
    invalid = frame[list(RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS)].isna().any(axis=1)
    result = (
        frame.loc[~invalid, list(RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS)]
        .sort_values(["instrument", "event_date"], kind="stable")
        .reset_index(drop=True)
    )
    stats = {
        "input_source_rows": int(len(frame)),
        "missing_or_non_a_share_rows_excluded": int(invalid.sum()),
        "rows_written": int(len(result)),
        "zero_ratio_rows": int(
            result["restricted_unlock_total_share_ratio"].eq(0.0).sum()
        ),
    }
    return result, stats


def _nth_trading_day_after(
    calendar: pd.DatetimeIndex, dated: pd.Series, sessions: int
) -> pd.Series:
    """Map each date to the Nth local trading session strictly after it."""

    if sessions < 1:
        raise ValueError("sessions must be positive")
    normalized_calendar = pd.DatetimeIndex(calendar).normalize().unique().sort_values()
    values = pd.to_datetime(dated, errors="coerce").dt.normalize()
    mapped = pd.Series(pd.NaT, index=dated.index, dtype="datetime64[ns]")
    valid_dates = values.notna()
    if normalized_calendar.empty or not valid_dates.any():
        return mapped
    valid_index = values.index[valid_dates]
    lookup = normalized_calendar.searchsorted(
        pd.DatetimeIndex(values.loc[valid_index]), side="right"
    ) + (sessions - 1)
    within = lookup < len(normalized_calendar)
    if within.any():
        mapped.loc[valid_index[within]] = normalized_calendar.take(
            lookup[within]
        ).values
    return mapped


def _insider_open_market_detail_frame(
    rows: Iterable[dict[str, Any]], calendar: pd.DatetimeIndex
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Normalize frozen source fields to identity-free direct-market detail rows."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=INSIDER_OPEN_MARKET_DETAIL_COLUMNS), {
            "input_source_rows": 0,
            "missing_or_non_a_share_rows_excluded": 0,
            "non_direct_market_reason_rows_excluded": 0,
            "direction_sign_inconsistent_or_zero_rows_excluded": 0,
            "calendar_mapping_rows_excluded": 0,
            "valid_direct_market_rows": 0,
            "buy_rows": 0,
            "sell_rows": 0,
            "excluded_reason_counts": {},
        }
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SCODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "transaction_date": pd.to_datetime(
                raw.get("TDATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ).dt.normalize(),
            "changed_shares": pd.to_numeric(
                raw.get("CHANNUM", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "direction": raw.get("BDFX", pd.Series(index=raw.index, dtype="object"))
            .astype("string")
            .str.strip(),
            "reason": raw.get("BDYY", pd.Series(index=raw.index, dtype="object"))
            .astype("string")
            .str.strip(),
        }
    )
    valid_key = frame[["instrument", "transaction_date"]].notna().all(axis=1)
    missing_or_non_a_share = int((~valid_key).sum())
    keyed = frame.loc[valid_key].copy()
    direct_reason = keyed["reason"].isin(INSIDER_OPEN_MARKET_REASON_WHITELIST)
    excluded_reasons = (
        keyed.loc[~direct_reason, "reason"]
        .fillna("<missing>")
        .value_counts()
        .sort_index()
    )
    direct = keyed.loc[direct_reason].copy()
    consistent_buy = direct["direction"].eq("增持") & direct["changed_shares"].gt(0.0)
    consistent_sell = direct["direction"].eq("减持") & direct["changed_shares"].lt(0.0)
    consistent = consistent_buy | consistent_sell
    direction_excluded = int((~consistent).sum())
    valid = direct.loc[consistent, ["instrument", "transaction_date"]].copy()
    valid["event_date"] = _nth_trading_day_after(
        calendar, valid["transaction_date"], sessions=3
    )
    valid["is_buy"] = consistent_buy.loc[consistent].astype(float).to_numpy()
    mapped = valid["event_date"].notna()
    calendar_excluded = int((~mapped).sum())
    result = (
        valid.loc[mapped, list(INSIDER_OPEN_MARKET_DETAIL_COLUMNS)]
        .sort_values(["instrument", "transaction_date", "event_date"], kind="stable")
        .reset_index(drop=True)
    )
    stats = {
        "input_source_rows": int(len(frame)),
        "missing_or_non_a_share_rows_excluded": missing_or_non_a_share,
        "non_direct_market_reason_rows_excluded": int((~direct_reason).sum()),
        "direction_sign_inconsistent_or_zero_rows_excluded": direction_excluded,
        "calendar_mapping_rows_excluded": calendar_excluded,
        "valid_direct_market_rows": int(len(result)),
        "buy_rows": int(result["is_buy"].sum()),
        "sell_rows": int(len(result) - result["is_buy"].sum()),
        "excluded_reason_counts": {
            str(key): int(value) for key, value in excluded_reasons.items()
        },
    }
    return result, stats


def aggregate_insider_open_market_details(details: pd.DataFrame) -> pd.DataFrame:
    """Aggregate identity-free transaction rows to the frozen stock/event snapshot."""

    if details.empty:
        return pd.DataFrame(columns=INSIDER_OPEN_MARKET_EVENT_COLUMNS)
    missing = sorted(set(INSIDER_OPEN_MARKET_DETAIL_COLUMNS) - set(details.columns))
    if missing:
        raise ValueError(
            f"insider open-market details are missing columns: {', '.join(missing)}"
        )
    result = (
        details.groupby(["instrument", "event_date"], as_index=False, sort=True)
        .agg(
            insider_open_market_latest_transaction_date=("transaction_date", "max"),
            insider_open_market_buy_share=("is_buy", "mean"),
            insider_open_market_event_count=("is_buy", "size"),
        )
        .loc[:, list(INSIDER_OPEN_MARKET_EVENT_COLUMNS)]
        .sort_values(["instrument", "event_date"], kind="stable")
        .reset_index(drop=True)
    )
    result["insider_open_market_buy_share"] = pd.to_numeric(
        result["insider_open_market_buy_share"], errors="coerce"
    ).astype(float)
    result["insider_open_market_event_count"] = pd.to_numeric(
        result["insider_open_market_event_count"], errors="raise"
    ).astype("int64")
    return result


def normalize_insider_open_market_rows(
    rows: Iterable[dict[str, Any]], calendar: pd.DatetimeIndex
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Normalize and aggregate insider direct-market records without identities or prices."""

    details, stats = _insider_open_market_detail_frame(rows, calendar)
    result = aggregate_insider_open_market_details(details)
    stats = {**stats, "rows_written": int(len(result))}
    return result, stats


def normalize_repurchase_plan_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Reduce public repurchase plans to first-plan-date, non-outcome fields."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=REPURCHASE_EVENT_COLUMNS)
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "DIM_SCODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("DIM_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "repurchase_planned_share_ratio": pd.to_numeric(
                raw.get("ZSZSX", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "repurchase_planned_amount": pd.to_numeric(
                raw.get("JESX", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    )
    frame = frame.dropna(subset=["instrument", "announcement_date"])
    return (
        frame.loc[:, list(REPURCHASE_EVENT_COLUMNS)]
        .sort_values(["instrument", "announcement_date"], kind="stable")
        .drop_duplicates(["instrument", "announcement_date"], keep="first")
        .reset_index(drop=True)
    )


def normalize_holder_count_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Reduce holder-count notices to announced, non-price change inputs."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=HOLDER_COUNT_EVENT_COLUMNS)
    frame = pd.DataFrame(
        {
            "instrument": raw.get(
                "SECURITY_CODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("HOLD_NOTICE_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "holder_count_change_ratio": pd.to_numeric(
                raw.get(
                    "HOLDER_NUM_RATIO", pd.Series(index=raw.index, dtype="float64")
                ),
                errors="coerce",
            ),
            "holder_count_change_absolute": pd.to_numeric(
                raw.get(
                    "HOLDER_NUM_CHANGE", pd.Series(index=raw.index, dtype="float64")
                ),
                errors="coerce",
            ),
        }
    )
    frame = frame.dropna(subset=["instrument", "announcement_date"])
    return (
        frame.loc[:, list(HOLDER_COUNT_EVENT_COLUMNS)]
        .sort_values(["instrument", "announcement_date"], kind="stable")
        .drop_duplicates(["instrument", "announcement_date"], keep="last")
        .reset_index(drop=True)
    )


def normalize_pledge_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate each notice-day's disclosed pledge quantities without live fields."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=PLEDGE_EVENT_COLUMNS)
    detail = pd.DataFrame(
        {
            "instrument": raw.get(
                "SECURITY_CODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("NOTICE_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "pledge_share_count": pd.to_numeric(
                raw.get("PF_NUM", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
            "pledge_total_share_ratio": pd.to_numeric(
                raw.get("PF_TSR", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    ).dropna(subset=["instrument", "announcement_date"])
    if detail.empty:
        return pd.DataFrame(columns=PLEDGE_EVENT_COLUMNS)
    result = (
        detail.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            pledge_share_count=(
                "pledge_share_count",
                lambda values: values.sum(min_count=1),
            ),
            pledge_total_share_ratio=(
                "pledge_total_share_ratio",
                lambda values: values.sum(min_count=1),
            ),
            pledge_event_count=("instrument", "size"),
        )
        .loc[:, list(PLEDGE_EVENT_COLUMNS)]
    )
    result["pledge_event_count"] = pd.to_numeric(
        result["pledge_event_count"], errors="coerce"
    ).astype(float)
    return result.sort_values(
        ["instrument", "announcement_date"], kind="stable"
    ).reset_index(drop=True)


def normalize_dividend_plan_rows(rows: Iterable[dict[str, Any]]) -> pd.DataFrame:
    """Aggregate initial public dividend-plan terms by instrument and notice date."""

    raw = pd.DataFrame(rows)
    if raw.empty:
        return pd.DataFrame(columns=DIVIDEND_PLAN_EVENT_COLUMNS)
    detail = pd.DataFrame(
        {
            "instrument": raw.get(
                "SECURITY_CODE", pd.Series(index=raw.index, dtype="object")
            ).map(qlib_symbol),
            "announcement_date": pd.to_datetime(
                raw.get("PLAN_NOTICE_DATE", pd.Series(index=raw.index, dtype="object")),
                errors="coerce",
            ),
            "dividend_cash_per_ten": pd.to_numeric(
                raw.get(
                    "PRETAX_BONUS_RMB", pd.Series(index=raw.index, dtype="float64")
                ),
                errors="coerce",
            ),
            "dividend_share_ratio": pd.to_numeric(
                raw.get("BONUS_IT_RATIO", pd.Series(index=raw.index, dtype="float64")),
                errors="coerce",
            ),
        }
    ).dropna(subset=["instrument", "announcement_date"])
    if detail.empty:
        return pd.DataFrame(columns=DIVIDEND_PLAN_EVENT_COLUMNS)
    result = (
        detail.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            dividend_cash_per_ten=(
                "dividend_cash_per_ten",
                lambda values: values.sum(min_count=1),
            ),
            dividend_share_ratio=(
                "dividend_share_ratio",
                lambda values: values.sum(min_count=1),
            ),
            dividend_plan_event_count=("instrument", "size"),
        )
        .loc[:, list(DIVIDEND_PLAN_EVENT_COLUMNS)]
    )
    result["dividend_plan_event_count"] = pd.to_numeric(
        result["dividend_plan_event_count"], errors="coerce"
    ).astype(float)
    return result.sort_values(
        ["instrument", "announcement_date"], kind="stable"
    ).reset_index(drop=True)


def merge_margin_financing_event_frames(
    existing: pd.DataFrame, fetched: pd.DataFrame
) -> pd.DataFrame:
    """Append a newer event retrieval without silently retaining duplicate days.

    Daily public source rows can be corrected after an earlier download.  On an
    explicit incremental refresh, newly fetched rows therefore replace an
    existing instrument/date pair, while all untouched historical dates remain
    in the auditable local snapshot.
    """

    frames: list[pd.DataFrame] = []
    for frame in (existing, fetched):
        if frame.empty:
            continue
        missing = sorted(set(MARGIN_FINANCING_EVENT_COLUMNS) - set(frame.columns))
        if missing:
            raise ValueError(
                f"margin-financing event frame is missing columns: {', '.join(missing)}"
            )
        frames.append(frame.loc[:, list(MARGIN_FINANCING_EVENT_COLUMNS)].copy())
    if not frames:
        return pd.DataFrame(columns=MARGIN_FINANCING_EVENT_COLUMNS)
    merged = pd.concat(frames, ignore_index=True)
    merged["trade_date"] = pd.to_datetime(merged["trade_date"], errors="coerce")
    return (
        merged.dropna(subset=["instrument", "trade_date"])
        .sort_values(["instrument", "trade_date"], kind="stable")
        .drop_duplicates(["instrument", "trade_date"], keep="last")
        .reset_index(drop=True)
    )


def _eastmoney_session() -> requests.Session:
    """Create the common public-datacenter session used by dated snapshots."""

    session = requests.Session()
    session.headers.update(
        {
            "Accept": "application/json, text/plain, */*",
            "Referer": "https://data.eastmoney.com/",
            "User-Agent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)",
        }
    )
    return session


def sync_fundamental_reports(
    report_dates: Iterable[str],
    output: Path,
    manifest: Path,
    *,
    report_frequency: str,
    manifest_metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Download dated public financial reports and write an auditable local snapshot."""

    dates = list(report_dates)
    if report_frequency not in {"annual", "quarterly"}:
        raise ValueError("report_frequency must be annual or quarterly")
    if not dates:
        raise ValueError("at least one report date is required")

    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    counts: dict[str, int] = {}
    for report_date in dates:
        rows = fetch_annual_report_rows(session, report_date)
        normalized = normalize_fundamental_rows(rows, report_date)
        frames.append(normalized)
        counts[report_date] = len(normalized)
        print(
            f"{report_date}: {len(normalized)} normalized {report_frequency}-report rows"
        )

    merged = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=FUNDAMENTAL_COLUMNS)
    )
    merged = merged.sort_values(
        ["instrument", "report_date", "announcement_date"], kind="stable"
    )
    merged = merged.drop_duplicates(
        ["instrument", "report_date"], keep="first"
    ).reset_index(drop=True)
    if merged.empty:
        raise RuntimeError(f"{report_frequency}-report sync produced no usable rows")
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "report_frequency": report_frequency,
        "report_dates": dates,
        "rows_by_report_date": counts,
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The public source is queried as it exists today; later corrections may not reproduce the original disclosure values.",
            "The research join waits until the trading day after announcement_date, but it is not a substitute for an exchange-grade point-in-time fundamentals vendor.",
        ],
    }
    if manifest_metadata:
        overlap = sorted(set(result) & set(manifest_metadata))
        if overlap:
            raise ValueError(
                "fundamental manifest metadata would overwrite core fields: "
                + ",".join(overlap)
            )
        result.update(manifest_metadata)
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_fundamentals(
    start_year: int, end_year: int, output: Path, manifest: Path
) -> dict[str, Any]:
    """Download annual quality inputs and write an auditable local snapshot."""

    return sync_fundamental_reports(
        annual_report_dates(start_year, end_year),
        output,
        manifest,
        report_frequency="annual",
    )


def sync_quarterly_fundamentals(
    start_year: int,
    end_year: int,
    output: Path,
    manifest: Path,
    through_report_date: str | None = None,
    *,
    as_of_date: dt.date | None = None,
) -> dict[str, Any]:
    """Download quarterly quality inputs for post-announcement short-horizon research."""

    dates = quarterly_report_dates(start_year, end_year)
    local_as_of = as_of_date or dt.date.today()
    latest_completed = latest_completed_quarter_end(local_as_of)
    if through_report_date is not None:
        through = pd.Timestamp(through_report_date).normalize()
        if pd.isna(through):
            raise ValueError("through_report_date must be a valid ISO date")
        if through > latest_completed:
            raise ValueError(
                "through_report_date must not exceed the latest completed "
                f"calendar quarter {latest_completed.date().isoformat()}"
            )
        dates = [date for date in dates if pd.Timestamp(date) <= through]
        if not dates:
            raise ValueError(
                "through_report_date precedes the requested quarterly range"
            )
    elif any(pd.Timestamp(date) > latest_completed for date in dates):
        raise ValueError(
            "--through-report-date is required when the requested year range "
            "extends beyond the latest completed calendar quarter "
            f"{latest_completed.date().isoformat()}"
        )
    return sync_fundamental_reports(
        dates,
        output,
        manifest,
        report_frequency="quarterly",
        manifest_metadata={
            "through_report_date": dates[-1],
            "latest_completed_quarter_end_at_sync": (
                latest_completed.date().isoformat()
            ),
        },
    )


