def sync_margin_financing_top_flow_events(
    provider_uri: Path,
    start: str,
    end: str | None,
    top_n: int,
    output: Path,
    manifest: Path,
    merge_existing: bool = False,
) -> dict[str, Any]:
    """Download one fixed daily Top-N financing-flow snapshot from local sessions.

    The local calendar determines which sessions are requested, so Chinese
    market holidays are not mistaken for failed provider calls.  If the public
    source has not yet published a local session, it is retained separately as
    source lag; no stale row is invented for that session.
    """

    if not 1 <= top_n <= 500:
        raise ValueError("top_n must be between 1 and 500")
    start_date = pd.Timestamp(start).normalize()
    if pd.isna(start_date):
        raise ValueError("start must be a valid ISO date")
    calendar = local_trading_calendar(provider_uri, end=end)
    end_date = (
        pd.Timestamp(end).normalize() if end is not None else calendar.max().normalize()
    )
    if pd.isna(end_date) or end_date < start_date:
        raise ValueError("end must be a valid ISO date not earlier than start")
    sessions = calendar[(calendar >= start_date) & (calendar <= end_date)]
    if not len(sessions):
        raise ValueError(
            "no local trading sessions fall within the requested margin-financing range"
        )
    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    unavailable_dates: list[str] = []
    rows_by_year: dict[str, int] = {}
    sessions_by_year: dict[str, int] = {}
    for position, trade_date in enumerate(sessions, start=1):
        date_text = pd.Timestamp(trade_date).date().isoformat()
        raw = fetch_margin_financing_top_flow_rows(session, date_text, top_n)
        normalized = normalize_margin_financing_top_flow_rows(raw)
        year = str(pd.Timestamp(trade_date).year)
        sessions_by_year[year] = sessions_by_year.get(year, 0) + 1
        rows_by_year[year] = rows_by_year.get(year, 0) + len(normalized)
        if normalized.empty:
            unavailable_dates.append(date_text)
        else:
            frames.append(normalized)
        if position % 50 == 0 or position == len(sessions):
            print(
                f"margin financing: {position}/{len(sessions)} sessions; "
                f"{sum(len(frame) for frame in frames)} normalized stock/day events"
            )
        # The public endpoint is queried once per local market session.  Keep a
        # small, fixed inter-request pause instead of parallelizing the source.
        time.sleep(0.05)
    fetched = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=MARGIN_FINANCING_EVENT_COLUMNS)
    )
    fetched = merge_margin_financing_event_frames(pd.DataFrame(), fetched)
    existing = (
        load_margin_financing_events(output)
        if merge_existing and output.exists()
        else pd.DataFrame()
    )
    merged = merge_margin_financing_event_frames(existing, fetched)
    if merged.empty:
        raise RuntimeError(
            "margin-financing top-flow sync produced no usable A-share events"
        )
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_MARGIN_FINANCING_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "daily_after_close_margin_financing_top_flow",
        "selection_rule": {
            "sort": "RZJME descending (same-session financing net buy amount)",
            "top_n": top_n,
            "not_observed_means_zero": False,
        },
        "requested_calendar_start": sessions.min().date().isoformat(),
        "requested_calendar_end": sessions.max().date().isoformat(),
        "sessions_requested": int(len(sessions)),
        "sessions_by_year": sessions_by_year,
        "fetched_rows_by_year": rows_by_year,
        "rows_by_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["trade_date"]).dt.year, sort=True
            )
        },
        "source_not_published_dates": unavailable_dates,
        "merge_existing": merge_existing,
        "existing_rows_before_merge": int(len(existing)),
        "fetched_rows": int(len(fetched)),
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "Only the predeclared top N financing net-buy rows per local session are retained; omitted stocks are not treated as zero flow.",
            "The public report exposes RCHANGE3DCP/RCHANGE5DCP/RCHANGE10DCP post-session price changes. They are excluded from the request, storage, and scoring schema.",
            "The source is a current public snapshot and can revise or omit historical rows; it is not an exchange-grade point-in-time financing database.",
            "The event is treated as available after its session close for a next-local-session-open decision; the source does not provide a publication timestamp to prove an earlier availability.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def institutional_survey_month_ranges(
    start_year: int, end_year: int
) -> list[tuple[str, str]]:
    """Return non-overlapping inclusive month partitions for a year range."""

    if end_year < start_year:
        raise ValueError("--end-year must not be earlier than --start-year")
    starts = pd.date_range(f"{start_year}-01-01", f"{end_year}-12-01", freq="MS")
    return [
        (
            pd.Timestamp(start).date().isoformat(),
            (pd.Timestamp(start) + pd.offsets.MonthEnd(0)).date().isoformat(),
        )
        for start in starts
    ]


def fetch_institutional_survey_partition_details(
    session: requests.Session,
    start_date: str,
    end_date: str,
    *,
    maximum_pages: int = INSTITUTIONAL_SURVEY_MAX_PAGES_PER_PARTITION,
    page_pause_seconds: float = INSTITUTIONAL_SURVEY_PAGE_PAUSE_SECONDS,
) -> tuple[list[pd.DataFrame], list[dict[str, Any]]]:
    """Fetch one verified date range, bisecting before unsafe page offsets."""

    start = pd.Timestamp(start_date).normalize()
    end = pd.Timestamp(end_date).normalize()
    if pd.isna(start) or pd.isna(end) or end < start:
        raise ValueError(
            "institutional-survey partition must use a valid inclusive date range"
        )
    if maximum_pages < 1:
        raise ValueError("institutional-survey maximum_pages must be positive")
    if page_pause_seconds < 0:
        raise ValueError("institutional-survey page pause must be non-negative")

    start_text = start.date().isoformat()
    end_text = end.date().isoformat()
    first = _eastmoney_institutional_survey_request(
        session, start_text, end_text, page_number=1
    )
    first_result = first.get("result") or {}
    pages = int(first_result.get("pages") or 0)
    advertised_count = int(first_result.get("count") or 0)
    if pages > maximum_pages:
        if start == end:
            raise RuntimeError(
                f"institutional-survey single-date partition exceeds the safe page ceiling: "
                f"{start_text}, pages={pages}, ceiling={maximum_pages}"
            )
        if page_pause_seconds:
            time.sleep(page_pause_seconds)
        midpoint = start + (end - start) // 2
        left_frames, left_records = fetch_institutional_survey_partition_details(
            session,
            start_text,
            midpoint.date().isoformat(),
            maximum_pages=maximum_pages,
            page_pause_seconds=page_pause_seconds,
        )
        right_frames, right_records = fetch_institutional_survey_partition_details(
            session,
            (midpoint + pd.Timedelta(days=1)).date().isoformat(),
            end_text,
            maximum_pages=maximum_pages,
            page_pause_seconds=page_pause_seconds,
        )
        return left_frames + right_frames, left_records + right_records

    if pages < 1:
        if advertised_count != 0:
            raise RuntimeError(
                f"institutional-survey partition reported rows without pages: "
                f"{start_text} to {end_text}, count={advertised_count}"
            )
        return [], [
            {
                "start": start_text,
                "end": end_text,
                "pages": 0,
                "advertised_source_rows": 0,
                "source_rows": 0,
                "count_verified": True,
            }
        ]

    frames: list[pd.DataFrame] = []
    source_rows = 0
    for page_number in range(1, pages + 1):
        payload = (
            first
            if page_number == 1
            else _eastmoney_institutional_survey_request(
                session, start_text, end_text, page_number=page_number
            )
        )
        result = payload.get("result") or {}
        current_pages = int(result.get("pages") or 0)
        current_count = int(result.get("count") or 0)
        if current_pages != pages or current_count != advertised_count:
            raise RuntimeError(
                f"institutional-survey partition changed during pagination: "
                f"{start_text} to {end_text}, page={page_number}"
            )
        rows = list(result.get("data") or [])
        source_rows += len(rows)
        normalized = _institutional_survey_detail_frame(rows)
        if not normalized.empty:
            frames.append(normalized)
        if page_pause_seconds:
            time.sleep(page_pause_seconds)
    if source_rows != advertised_count:
        raise RuntimeError(
            f"institutional-survey partition row-count mismatch: {start_text} to {end_text}, "
            f"advertised={advertised_count}, fetched={source_rows}"
        )
    return frames, [
        {
            "start": start_text,
            "end": end_text,
            "pages": pages,
            "advertised_source_rows": advertised_count,
            "source_rows": source_rows,
            "count_verified": True,
        }
    ]


