def fetch_insider_open_market_partition_details(
    session: requests.Session,
    start_date: str,
    end_date: str,
    calendar: pd.DatetimeIndex,
    *,
    maximum_pages: int = INSIDER_OPEN_MARKET_MAX_PAGES_PER_PARTITION,
    page_pause_seconds: float = INSIDER_OPEN_MARKET_PAGE_PAUSE_SECONDS,
) -> tuple[list[pd.DataFrame], list[dict[str, Any]]]:
    """Fetch and count-verify one insider transaction range, bisecting if needed."""

    start = pd.Timestamp(start_date).normalize()
    end = pd.Timestamp(end_date).normalize()
    if pd.isna(start) or pd.isna(end) or end < start:
        raise ValueError(
            "insider open-market partition must use a valid inclusive date range"
        )
    if maximum_pages < 1:
        raise ValueError("insider open-market maximum_pages must be positive")
    if page_pause_seconds < 0:
        raise ValueError("insider open-market page pause must be non-negative")
    start_text = start.date().isoformat()
    end_text = end.date().isoformat()
    first = _eastmoney_insider_open_market_request(session, start_text, end_text, 1)
    first_result = first["result"]
    pages = int(first_result.get("pages") or 0)
    advertised_count = int(first_result.get("count") or 0)
    if pages > maximum_pages:
        if start == end:
            raise RuntimeError(
                "insider open-market single-date partition exceeds the safe page ceiling: "
                f"{start_text}, pages={pages}, ceiling={maximum_pages}"
            )
        midpoint = start + (end - start) // 2
        left_frames, left_records = fetch_insider_open_market_partition_details(
            session,
            start_text,
            midpoint.date().isoformat(),
            calendar,
            maximum_pages=maximum_pages,
            page_pause_seconds=page_pause_seconds,
        )
        right_frames, right_records = fetch_insider_open_market_partition_details(
            session,
            (midpoint + pd.Timedelta(days=1)).date().isoformat(),
            end_text,
            calendar,
            maximum_pages=maximum_pages,
            page_pause_seconds=page_pause_seconds,
        )
        return left_frames + right_frames, left_records + right_records
    empty_record = {
        "start": start_text,
        "end": end_text,
        "pages": 0,
        "advertised_source_rows": 0,
        "source_rows": 0,
        "valid_direct_market_rows": 0,
        "missing_or_non_a_share_rows_excluded": 0,
        "non_direct_market_reason_rows_excluded": 0,
        "direction_sign_inconsistent_or_zero_rows_excluded": 0,
        "calendar_mapping_rows_excluded": 0,
        "buy_rows": 0,
        "sell_rows": 0,
        "excluded_reason_counts": {},
        "count_verified": True,
    }
    if pages < 1:
        if advertised_count != 0:
            raise RuntimeError(
                f"insider open-market partition reported rows without pages: {start_text} to {end_text}"
            )
        return [], [empty_record]

    frames: list[pd.DataFrame] = []
    totals = {
        key: 0
        for key in (
            "source_rows",
            "valid_direct_market_rows",
            "missing_or_non_a_share_rows_excluded",
            "non_direct_market_reason_rows_excluded",
            "direction_sign_inconsistent_or_zero_rows_excluded",
            "calendar_mapping_rows_excluded",
            "buy_rows",
            "sell_rows",
        )
    }
    excluded_reason_counts: dict[str, int] = {}
    for page_number in range(1, pages + 1):
        payload = (
            first
            if page_number == 1
            else _eastmoney_insider_open_market_request(
                session, start_text, end_text, page_number
            )
        )
        rows = payload["result"].get("data") or []
        totals["source_rows"] += len(rows)
        details, stats = _insider_open_market_detail_frame(rows, calendar)
        for key in totals:
            if key != "source_rows":
                totals[key] += int(stats[key])
        for reason, count in stats["excluded_reason_counts"].items():
            excluded_reason_counts[reason] = excluded_reason_counts.get(
                reason, 0
            ) + int(count)
        if not details.empty:
            frames.append(details)
        if page_pause_seconds and page_number < pages:
            time.sleep(page_pause_seconds)
    if totals["source_rows"] != advertised_count:
        raise RuntimeError(
            f"insider open-market partition row-count mismatch: {start_text} to {end_text}, "
            f"advertised={advertised_count}, fetched={totals['source_rows']}"
        )
    return frames, [
        {
            "start": start_text,
            "end": end_text,
            "pages": pages,
            "advertised_source_rows": advertised_count,
            **totals,
            "excluded_reason_counts": dict(sorted(excluded_reason_counts.items())),
            "count_verified": True,
        }
    ]


def fetch_securities_lending_session(
    session: requests.Session,
    trade_date: str,
    *,
    maximum_pages: int = SECURITIES_LENDING_MAX_PAGES_PER_SESSION,
    page_pause_seconds: float = SECURITIES_LENDING_PAGE_PAUSE_SECONDS,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Fetch, normalize, and count-verify one frozen full-market session."""

    date = pd.Timestamp(trade_date).normalize()
    if pd.isna(date):
        raise ValueError("securities-lending trade_date must be a valid date")
    if maximum_pages < 1:
        raise ValueError("securities-lending maximum_pages must be positive")
    if page_pause_seconds < 0:
        raise ValueError("securities-lending page pause must be non-negative")
    date_text = date.date().isoformat()
    first = _eastmoney_securities_lending_request(session, date_text, 1)
    first_result = first["result"]
    pages = int(first_result.get("pages") or 0)
    advertised_count = int(first_result.get("count") or 0)
    if pages < 1 or advertised_count < 1:
        raise RuntimeError(
            f"securities-lending source has no published rows for local session {date_text}"
        )
    if pages > maximum_pages:
        raise RuntimeError(
            "securities-lending single-session partition exceeds the frozen page ceiling: "
            f"{date_text}, pages={pages}, ceiling={maximum_pages}"
        )

    raw_rows: list[dict[str, Any]] = []
    for page_number in range(1, pages + 1):
        payload = (
            first
            if page_number == 1
            else _eastmoney_securities_lending_request(session, date_text, page_number)
        )
        result = payload["result"]
        if (
            int(result.get("pages") or 0) != pages
            or int(result.get("count") or 0) != advertised_count
        ):
            raise RuntimeError(
                f"securities-lending pagination metadata changed during fetch: {date_text}"
            )
        rows = result.get("data") or []
        if not isinstance(rows, list):
            raise RuntimeError(
                f"securities-lending page data is not a list: {date_text}"
            )
        raw_rows.extend(rows)
        if page_pause_seconds and page_number < pages:
            time.sleep(page_pause_seconds)
    if len(raw_rows) != advertised_count:
        raise RuntimeError(
            f"securities-lending session row-count mismatch: {date_text}, "
            f"advertised={advertised_count}, fetched={len(raw_rows)}"
        )

    normalized, stats = normalize_securities_lending_rows(raw_rows)
    reconciled = (
        int(stats["missing_or_non_a_share_rows_excluded"])
        + int(stats["negative_raw_count_rows_excluded"])
        + int(stats["zero_activity_rows_excluded"])
        + int(stats["rows_written"])
    )
    if reconciled != len(raw_rows):
        raise RuntimeError(
            f"securities-lending normalization does not reconcile to source rows: {date_text}"
        )
    if normalized.empty:
        raise RuntimeError(
            f"securities-lending session has no positive-activity A-share rows: {date_text}"
        )
    if tuple(normalized.columns) != SECURITIES_LENDING_EVENT_COLUMNS:
        raise RuntimeError(
            "securities-lending normalized columns violate the frozen contract"
        )
    if not normalized["trade_date"].eq(date).all():
        raise RuntimeError(
            f"securities-lending source returned a different trade date for {date_text}"
        )
    if normalized.duplicated(["instrument", "trade_date"]).any():
        raise RuntimeError(
            f"securities-lending session contains duplicate event keys: {date_text}"
        )
    if normalized[list(SECURITIES_LENDING_EVENT_COLUMNS)].isna().any().any():
        raise RuntimeError(
            f"securities-lending session contains missing values: {date_text}"
        )
    raw_columns = [
        "securities_lending_balance_shares",
        "securities_lending_sell_shares",
        "securities_lending_repay_shares",
    ]
    if not normalized[raw_columns].ge(0.0).all().all():
        raise RuntimeError(
            f"securities-lending session contains negative raw counts: {date_text}"
        )
    if not normalized[SECURITIES_LENDING_FACTOR_NAME].between(-1.0, 1.0).all():
        raise RuntimeError(
            f"securities-lending ratio falls outside [-1, 1]: {date_text}"
        )
    record = {
        "trade_date": date_text,
        "pages": pages,
        "advertised_source_rows": advertised_count,
        "source_rows": len(raw_rows),
        **stats,
        "active_a_share_rows": int(len(normalized)),
        "distinct_factor_values": int(
            normalized[SECURITIES_LENDING_FACTOR_NAME].nunique()
        ),
        "count_verified": True,
    }
    return normalized, record


def sync_analyst_rating_events(
    output: Path = DEFAULT_ANALYST_RATING_EVENTS,
    manifest: Path = DEFAULT_ANALYST_RATING_EVENT_MANIFEST,
) -> dict[str, Any]:
    """Build the frozen 2019--2025 analyst-rating-upgrade snapshot without prices."""

    contract = load_analyst_rating_data_contract()
    source_contract = contract["source"]
    start_year = pd.Timestamp(source_contract["publication_start"]).year
    end_year = pd.Timestamp(source_contract["publication_end"]).year
    session = _eastmoney_session()
    detail_frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    partition_records: list[dict[str, Any]] = []
    for month_start, month_end in institutional_survey_month_ranges(
        start_year, end_year
    ):
        frames, records = fetch_analyst_rating_partition_details(
            session,
            month_start,
            month_end,
            maximum_pages=ANALYST_RATING_MAX_PAGES_PER_PARTITION,
            page_pause_seconds=ANALYST_RATING_PAGE_PAUSE_SECONDS,
        )
        detail_frames.extend(frames)
        partition_records.extend(records)
        month_pages = sum(int(record["pages"]) for record in records)
        month_rows = sum(int(record["source_rows"]) for record in records)
        year = month_start[:4]
        pages_by_year[year] = pages_by_year.get(year, 0) + month_pages
        source_rows_by_year[year] = source_rows_by_year.get(year, 0) + month_rows
        print(
            f"analyst ratings {month_start[:7]}: {len(records)} verified partitions, "
            f"{month_pages} pages, {month_rows} source rows"
        )
    details = (
        pd.concat(detail_frames, ignore_index=True)
        if detail_frames
        else pd.DataFrame(
            columns=["info_code", "instrument", "announcement_date", "rating_change"]
        )
    )
    events, quality = aggregate_analyst_rating_details(details)
    if events.empty:
        raise RuntimeError(
            "analyst-rating sync produced no usable A-share rating events"
        )
    requested_years = list(range(start_year, end_year + 1))
    observed_years = sorted(
        pd.to_datetime(events["announcement_date"]).dt.year.unique().tolist()
    )
    if observed_years != requested_years:
        raise RuntimeError(
            "analyst-rating snapshot does not cover every requested year"
        )
    if tuple(events.columns) != ANALYST_RATING_EVENT_COLUMNS:
        raise RuntimeError(
            "analyst-rating snapshot columns do not match the frozen contract"
        )
    if events.duplicated(["instrument", "announcement_date"]).any():
        raise RuntimeError("analyst-rating snapshot contains duplicate event keys")
    if events[list(ANALYST_RATING_EVENT_COLUMNS)].isna().any().any():
        raise RuntimeError("analyst-rating snapshot contains missing contracted values")
    if not events["analyst_rating_upgrade_share"].between(0.0, 1.0).all():
        raise RuntimeError("analyst-rating upgrade share falls outside [0, 1]")
    if not events["analyst_valid_rating_report_count"].gt(0).all():
        raise RuntimeError("analyst-rating event has a non-positive valid-report count")
    _atomic_write_parquet(output, events)
    result = {
        "status": "completed",
        "data_contract": {
            "path": str(DEFAULT_ANALYST_RATING_DATA_CONTRACT.resolve()),
            "sha256": file_sha256(DEFAULT_ANALYST_RATING_DATA_CONTRACT),
            "preregistered_at": contract["preregistered_at"],
            "forward_return_fields_read": False,
        },
        "source": {
            "provider": source_contract["provider"],
            "endpoint": EASTMONEY_RESEARCH_REPORT_URL,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
            "requested_fields": source_contract["requested_fields"],
            "report_titles_authors_broker_identity_eps_pe_target_price_or_market_fields_requested_or_stored": False,
        },
        "event_frequency": "dated_analyst_rating_adjustment",
        "years": requested_years,
        "partition_policy": contract["snapshot_contract"]["partition_policy"],
        "verified_partitions": partition_records,
        "pages_by_year": pages_by_year,
        "source_rows_by_year": source_rows_by_year,
        "normalization_quality": quality,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in events.groupby(
                pd.to_datetime(events["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": int(len(events)),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "price_fields_loaded": [],
        "open_close_or_forward_return_fields_read": False,
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "The public research-report index is queried as it exists today and may revise or omit historical records.",
            "Publication dates have no reliable intraday timestamp, so events become usable only on the next local trading session.",
            "The provider's rating-change code is accepted as published; report text, authors, broker identity, forecasts, prices, and target prices are not requested or stored.",
            "This is a research event snapshot, not an exchange-grade point-in-time analyst-report archive.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_restricted_share_unlock_events(
    output: Path = DEFAULT_RESTRICTED_SHARE_UNLOCK_EVENTS,
    manifest: Path = DEFAULT_RESTRICTED_SHARE_UNLOCK_EVENT_MANIFEST,
) -> dict[str, Any]:
    """Build the frozen 2019--2025 unlock-pressure snapshot without prices."""

    contract = load_restricted_share_unlock_data_contract()
    source_contract = contract["source"]
    start_year = pd.Timestamp(source_contract["event_start"]).year
    end_year = pd.Timestamp(source_contract["event_end"]).year
    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    target_rows_by_year: dict[str, int] = {}
    excluded_rows_by_year: dict[str, int] = {}
    partition_records: list[dict[str, Any]] = []
    for month_start, month_end in institutional_survey_month_ranges(
        start_year, end_year
    ):
        month_frames, records = fetch_restricted_share_unlock_partition(
            session,
            month_start,
            month_end,
            maximum_pages=RESTRICTED_SHARE_UNLOCK_MAX_PAGES_PER_PARTITION,
            page_pause_seconds=RESTRICTED_SHARE_UNLOCK_PAGE_PAUSE_SECONDS,
        )
        frames.extend(month_frames)
        partition_records.extend(records)
        year = month_start[:4]
        month_pages = sum(int(record["pages"]) for record in records)
        month_source_rows = sum(int(record["source_rows"]) for record in records)
        month_target_rows = sum(int(record["target_rows"]) for record in records)
        month_excluded_rows = sum(int(record["excluded_rows"]) for record in records)
        pages_by_year[year] = pages_by_year.get(year, 0) + month_pages
        source_rows_by_year[year] = source_rows_by_year.get(year, 0) + month_source_rows
        target_rows_by_year[year] = target_rows_by_year.get(year, 0) + month_target_rows
        excluded_rows_by_year[year] = (
            excluded_rows_by_year.get(year, 0) + month_excluded_rows
        )
        print(
            f"restricted-share unlocks {month_start[:7]}: {len(records)} verified partitions, "
            f"{month_pages} pages, {month_source_rows} source rows, "
            f"{month_target_rows} target rows"
        )
    events = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS)
    )
    events = (
        events.loc[:, list(RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS)]
        .sort_values(["instrument", "event_date"], kind="stable")
        .reset_index(drop=True)
    )
    if events.empty:
        raise RuntimeError(
            "restricted-share unlock sync produced no usable A-share events"
        )
    requested_years = list(range(start_year, end_year + 1))
    observed_years = sorted(
        pd.to_datetime(events["event_date"]).dt.year.unique().tolist()
    )
    if observed_years != requested_years:
        raise RuntimeError(
            "restricted-share unlock snapshot does not cover every requested year"
        )
    if tuple(events.columns) != RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS:
        raise RuntimeError(
            "restricted-share unlock snapshot columns do not match the frozen contract"
        )
    if events.duplicated(["instrument", "event_date"]).any():
        raise RuntimeError(
            "restricted-share unlock snapshot contains duplicate event keys"
        )
    if events[list(RESTRICTED_SHARE_UNLOCK_EVENT_COLUMNS)].isna().any().any():
        raise RuntimeError(
            "restricted-share unlock snapshot contains missing contracted values"
        )
    if not events["restricted_unlock_total_share_ratio"].between(0.0, 1.0).all():
        raise RuntimeError("restricted-share unlock ratio falls outside [0, 1]")
    if not events["restricted_unlock_actual_shares"].ge(0.0).all():
        raise RuntimeError(
            "restricted-share unlock snapshot contains negative actual shares"
        )
    daily = events.groupby("event_date")["restricted_unlock_total_share_ratio"].agg(
        names="size", values="nunique"
    )
    ready = daily.loc[(daily["names"] >= 6) & (daily["values"] >= 2)]
    _atomic_write_parquet(output, events)
    result = {
        "status": "completed",
        "data_contract": {
            "path": str(DEFAULT_RESTRICTED_SHARE_UNLOCK_DATA_CONTRACT.resolve()),
            "sha256": file_sha256(DEFAULT_RESTRICTED_SHARE_UNLOCK_DATA_CONTRACT),
            "preregistered_at": contract["preregistered_at"],
            "forward_return_fields_read": False,
        },
        "source": {
            "provider": source_contract["provider"],
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report_name": EASTMONEY_RESTRICTED_SHARE_UNLOCK_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
            "requested_fields": source_contract["requested_fields"],
            "forbidden_fields_requested_or_stored": [],
            "shareholder_names_requested_or_stored": False,
        },
        "event_frequency": "dated_restricted_share_unlock",
        "years": requested_years,
        "partition_policy": contract["snapshot_contract"]["partition_policy"],
        "verified_partitions": partition_records,
        "pages_by_year": pages_by_year,
        "source_rows_by_year": source_rows_by_year,
        "target_rows_by_year": target_rows_by_year,
        "excluded_rows_by_year": excluded_rows_by_year,
        "normalization_quality": {
            "source_rows": int(sum(source_rows_by_year.values())),
            "target_rows": int(len(events)),
            "excluded_rows": int(sum(excluded_rows_by_year.values())),
            "duplicate_event_keys": 0,
            "missing_values": 0,
            "negative_actual_share_rows": 0,
            "out_of_range_ratio_rows": 0,
            "zero_ratio_rows": int(
                events["restricted_unlock_total_share_ratio"].eq(0.0).sum()
            ),
            "distinct_ratio_values": int(
                events["restricted_unlock_total_share_ratio"].nunique()
            ),
            "dates_with_at_least_six_names_and_two_values_before_quality_or_listing_gates": int(
                len(ready)
            ),
            "such_dates_by_year": {
                str(year): int(count)
                for year, count in ready.groupby(ready.index.year).size().items()
            },
        },
        "rows_by_event_year": {
            str(year): int(len(group))
            for year, group in events.groupby(
                pd.to_datetime(events["event_date"]).dt.year, sort=True
            )
        },
        "rows_written": int(len(events)),
        "event_start": events["event_date"].min().date().isoformat(),
        "event_end": events["event_date"].max().date().isoformat(),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "price_fields_loaded": [],
        "open_close_or_forward_return_fields_read": False,
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "The public unlock table is queried as it exists today and may revise historical release records.",
            "No point-in-time schedule-announcement archive is available, so an event is not usable before its unlock-date close.",
            "The factor measures realized released shares relative to total shares; it does not identify whether holders sell.",
            "This is a capacity candidate only until a separate no-return gate is frozen and passed.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_insider_open_market_events(
    output: Path = DEFAULT_INSIDER_OPEN_MARKET_EVENTS,
    manifest: Path = DEFAULT_INSIDER_OPEN_MARKET_EVENT_MANIFEST,
    provider_uri: Path = DEFAULT_PROVIDER_URI,
) -> dict[str, Any]:
    """Build the frozen 2019--2025 conservative insider transaction snapshot without prices."""

    contract = load_insider_open_market_data_contract()
    source_contract = contract["source"]
    start_year = pd.Timestamp(source_contract["transaction_start"]).year
    end_year = pd.Timestamp(source_contract["transaction_end"]).year
    calendar = local_trading_calendar(provider_uri)
    if calendar.empty:
        raise RuntimeError(
            "insider open-market sync requires a non-empty local trading calendar"
        )
    session = _eastmoney_session()
    detail_frames: list[pd.DataFrame] = []
    partition_records: list[dict[str, Any]] = []
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    valid_rows_by_year: dict[str, int] = {}
    for month_start, month_end in institutional_survey_month_ranges(
        start_year, end_year
    ):
        month_frames, records = fetch_insider_open_market_partition_details(
            session,
            month_start,
            month_end,
            calendar,
            maximum_pages=INSIDER_OPEN_MARKET_MAX_PAGES_PER_PARTITION,
            page_pause_seconds=INSIDER_OPEN_MARKET_PAGE_PAUSE_SECONDS,
        )
        detail_frames.extend(month_frames)
        partition_records.extend(records)
        year = month_start[:4]
        month_pages = sum(int(record["pages"]) for record in records)
        month_source_rows = sum(int(record["source_rows"]) for record in records)
        month_valid_rows = sum(
            int(record["valid_direct_market_rows"]) for record in records
        )
        pages_by_year[year] = pages_by_year.get(year, 0) + month_pages
        source_rows_by_year[year] = source_rows_by_year.get(year, 0) + month_source_rows
        valid_rows_by_year[year] = valid_rows_by_year.get(year, 0) + month_valid_rows
        print(
            f"insider open-market {month_start[:7]}: {len(records)} verified partitions, "
            f"{month_pages} pages, {month_source_rows} source rows, "
            f"{month_valid_rows} valid direct-market rows"
        )
    details = (
        pd.concat(detail_frames, ignore_index=True)
        if detail_frames
        else pd.DataFrame(columns=INSIDER_OPEN_MARKET_DETAIL_COLUMNS)
    )
    details = (
        details.loc[:, list(INSIDER_OPEN_MARKET_DETAIL_COLUMNS)]
        .sort_values(["instrument", "transaction_date", "event_date"], kind="stable")
        .reset_index(drop=True)
    )
    if details.empty:
        raise RuntimeError(
            "insider open-market sync produced no usable A-share transaction rows"
        )
    requested_years = list(range(start_year, end_year + 1))
    observed_transaction_years = sorted(
        pd.to_datetime(details["transaction_date"]).dt.year.unique().tolist()
    )
    if observed_transaction_years != requested_years:
        raise RuntimeError(
            "insider open-market snapshot does not cover every requested transaction year"
        )
    if any(source_rows_by_year.get(str(year), 0) < 1 for year in requested_years):
        raise RuntimeError(
            "insider open-market source returned an empty requested transaction year"
        )
    events = aggregate_insider_open_market_details(details)
    if tuple(events.columns) != INSIDER_OPEN_MARKET_EVENT_COLUMNS:
        raise RuntimeError(
            "insider open-market snapshot columns do not match the frozen contract"
        )
    if events.duplicated(["instrument", "event_date"]).any():
        raise RuntimeError("insider open-market snapshot contains duplicate event keys")
    if events[list(INSIDER_OPEN_MARKET_EVENT_COLUMNS)].isna().any().any():
        raise RuntimeError(
            "insider open-market snapshot contains missing contracted values"
        )
    if not events["insider_open_market_buy_share"].between(0.0, 1.0).all():
        raise RuntimeError("insider open-market buy share falls outside [0, 1]")
    counts = events["insider_open_market_event_count"]
    if not counts.gt(0).all() or not np.equal(counts, np.floor(counts)).all():
        raise RuntimeError("insider open-market event count must be a positive integer")
    expected_event_dates = _nth_trading_day_after(
        calendar,
        events["insider_open_market_latest_transaction_date"],
        sessions=3,
    )
    availability_errors = int((expected_event_dates != events["event_date"]).sum())
    if availability_errors:
        raise RuntimeError(
            "insider open-market snapshot violates the frozen third-session availability rule"
        )
    daily = events.groupby("event_date")["insider_open_market_buy_share"].agg(
        names="size", values="nunique"
    )
    ready = daily.loc[(daily["names"] >= 6) & (daily["values"] >= 2)]
    quality_keys = (
        "missing_or_non_a_share_rows_excluded",
        "non_direct_market_reason_rows_excluded",
        "direction_sign_inconsistent_or_zero_rows_excluded",
        "calendar_mapping_rows_excluded",
        "valid_direct_market_rows",
        "buy_rows",
        "sell_rows",
    )
    quality_totals = {
        key: int(sum(int(record[key]) for record in partition_records))
        for key in quality_keys
    }
    excluded_reason_counts: dict[str, int] = {}
    for record in partition_records:
        for reason, count in record["excluded_reason_counts"].items():
            excluded_reason_counts[reason] = excluded_reason_counts.get(
                reason, 0
            ) + int(count)
    source_rows = int(sum(source_rows_by_year.values()))
    reconciled_rows = (
        quality_totals["missing_or_non_a_share_rows_excluded"]
        + quality_totals["non_direct_market_reason_rows_excluded"]
        + quality_totals["direction_sign_inconsistent_or_zero_rows_excluded"]
        + quality_totals["calendar_mapping_rows_excluded"]
        + quality_totals["valid_direct_market_rows"]
    )
    if (
        source_rows != reconciled_rows
        or len(details) != quality_totals["valid_direct_market_rows"]
    ):
        raise RuntimeError(
            "insider open-market source-row normalization does not reconcile"
        )
    _atomic_write_parquet(output, events)
    result = {
        "status": "completed",
        "data_contract": {
            "path": str(DEFAULT_INSIDER_OPEN_MARKET_DATA_CONTRACT.resolve()),
            "sha256": file_sha256(DEFAULT_INSIDER_OPEN_MARKET_DATA_CONTRACT),
            "preregistered_at": contract["preregistered_at"],
            "forward_return_fields_read": False,
        },
        "source": {
            "provider": source_contract["provider"],
            "public_page": source_contract["public_page"],
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report_name": EASTMONEY_INSIDER_OPEN_MARKET_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
            "requested_fields": source_contract["requested_fields"],
            "forbidden_fields_requested_or_stored": [],
            "identity_fields_requested_or_stored": [],
            "price_amount_market_state_or_return_fields_requested_or_stored": [],
        },
        "event_frequency": "conservative_dated_insider_direct_open_market_transaction_aggregate",
        "transaction_years": requested_years,
        "partition_policy": contract["snapshot_contract"]["partition_policy"],
        "verified_partitions": partition_records,
        "pages_by_transaction_year": pages_by_year,
        "source_rows_by_transaction_year": source_rows_by_year,
        "valid_direct_market_rows_by_transaction_year": valid_rows_by_year,
        "normalization_quality": {
            "source_rows": source_rows,
            **quality_totals,
            "excluded_reason_counts": dict(sorted(excluded_reason_counts.items())),
            "source_row_reconciliation_errors": 0,
            "event_rows_written": int(len(events)),
            "duplicate_event_keys": 0,
            "missing_values": 0,
            "out_of_range_buy_share_rows": 0,
            "non_positive_or_non_integer_event_count_rows": 0,
            "availability_mapping_errors": availability_errors,
            "distinct_buy_share_values": int(
                events["insider_open_market_buy_share"].nunique()
            ),
            "dates_with_at_least_six_names_and_two_values_before_quality_or_listing_gates": int(
                len(ready)
            ),
            "such_dates_by_year": {
                str(year): int(count)
                for year, count in ready.groupby(ready.index.year).size().items()
            },
        },
        "rows_by_transaction_year": {
            str(year): int(len(group))
            for year, group in details.groupby(
                pd.to_datetime(details["transaction_date"]).dt.year, sort=True
            )
        },
        "rows_by_event_year": {
            str(year): int(len(group))
            for year, group in events.groupby(
                pd.to_datetime(events["event_date"]).dt.year, sort=True
            )
        },
        "rows_written": int(len(events)),
        "transaction_start": details["transaction_date"].min().date().isoformat(),
        "transaction_end": details["transaction_date"].max().date().isoformat(),
        "event_start": events["event_date"].min().date().isoformat(),
        "event_end": events["event_date"].max().date().isoformat(),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "price_fields_loaded": [],
        "open_close_or_forward_return_fields_read": False,
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "point_in_time_policy": contract["point_in_time_policy"],
        "limitations": [
            "The public transaction table is queried as it exists today and may revise or omit historical rows.",
            "No uniform historical cross-exchange filing timestamp is available; availability is synthetically delayed to the third local session close strictly after the transaction date.",
            "A filing later than the regulatory reporting window can still make synthetic availability earlier than actual publication.",
            "Only transaction-row direction is used; identities, roles, transaction prices, amounts, and share-size weights are not requested or stored.",
            "This is a capacity candidate only until a separate no-return gate is frozen and passed.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_securities_lending_events(
    output: Path = DEFAULT_SECURITIES_LENDING_EVENTS,
    manifest: Path = DEFAULT_SECURITIES_LENDING_EVENT_MANIFEST,
    provider_uri: Path = DEFAULT_PROVIDER_URI,
) -> dict[str, Any]:
    """Stream the frozen 2019--2025 full-market lending snapshot without prices."""

    import pyarrow as pa
    import pyarrow.parquet as pq

    contract = load_securities_lending_data_contract()
    source_contract = contract["source"]
    start = pd.Timestamp(source_contract["trade_start"]).normalize()
    end = pd.Timestamp(source_contract["trade_end"]).normalize()
    calendar = local_trading_calendar(provider_uri, end=end.date().isoformat())
    sessions = calendar[(calendar >= start) & (calendar <= end)]
    if sessions.empty:
        raise RuntimeError(
            "securities-lending sync requires a non-empty local trading calendar"
        )
    requested_years = list(range(start.year, end.year + 1))
    calendar_years = sorted(pd.DatetimeIndex(sessions).year.unique().tolist())
    if calendar_years != requested_years:
        raise RuntimeError(
            "local trading calendar does not cover every frozen securities-lending year"
        )

    output = output.expanduser()
    manifest = manifest.expanduser()
    output.parent.mkdir(parents=True, exist_ok=True)
    manifest.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        suffix=".parquet", dir=output.parent, delete=False
    ) as handle:
        temporary_output = Path(handle.name)
    temporary_output.unlink()
    temporary_manifest: Path | None = None
    schema = pa.schema(
        [
            pa.field("instrument", pa.string(), nullable=False),
            pa.field("trade_date", pa.timestamp("ns"), nullable=False),
            pa.field("securities_lending_balance_shares", pa.float64(), nullable=False),
            pa.field("securities_lending_sell_shares", pa.float64(), nullable=False),
            pa.field("securities_lending_repay_shares", pa.float64(), nullable=False),
            pa.field(
                "securities_lending_net_cover_ratio", pa.float64(), nullable=False
            ),
        ]
    )
    writer: pq.ParquetWriter | None = None
    executor: concurrent.futures.ThreadPoolExecutor | None = None
    completed = False
    records: list[dict[str, Any]] = []
    rows_by_year: dict[str, int] = {}
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    quality_keys = (
        "missing_or_non_a_share_rows_excluded",
        "negative_raw_count_rows_excluded",
        "zero_activity_rows_excluded",
        "rows_written",
    )
    quality_totals = {key: 0 for key in quality_keys}
    thread_state = threading.local()

    def fetch_one(value: pd.Timestamp) -> tuple[pd.DataFrame, dict[str, Any]]:
        if not hasattr(thread_state, "session"):
            thread_state.session = _eastmoney_session()
        return fetch_securities_lending_session(
            thread_state.session,
            pd.Timestamp(value).date().isoformat(),
            maximum_pages=SECURITIES_LENDING_MAX_PAGES_PER_SESSION,
            page_pause_seconds=SECURITIES_LENDING_PAGE_PAUSE_SECONDS,
        )

    try:
        writer = pq.ParquetWriter(temporary_output, schema, compression="zstd")
        executor = concurrent.futures.ThreadPoolExecutor(
            max_workers=SECURITIES_LENDING_FETCH_WORKERS,
            thread_name_prefix="securities-lending",
        )
        results = executor.map(fetch_one, sessions)
        for position, (frame, record) in enumerate(results, start=1):
            expected_date = pd.Timestamp(sessions[position - 1]).date().isoformat()
            if record["trade_date"] != expected_date:
                raise RuntimeError(
                    "securities-lending worker returned an out-of-order session"
                )
            table = pa.Table.from_pandas(
                frame.loc[:, list(SECURITIES_LENDING_EVENT_COLUMNS)],
                schema=schema,
                preserve_index=False,
                safe=True,
            )
            writer.write_table(table)
            records.append(record)
            year = expected_date[:4]
            rows_by_year[year] = rows_by_year.get(year, 0) + int(record["rows_written"])
            pages_by_year[year] = pages_by_year.get(year, 0) + int(record["pages"])
            source_rows_by_year[year] = source_rows_by_year.get(year, 0) + int(
                record["source_rows"]
            )
            for key in quality_keys:
                quality_totals[key] += int(record[key])
            if position % 25 == 0 or position == len(sessions):
                print(
                    f"securities lending: {position}/{len(sessions)} verified sessions; "
                    f"{sum(rows_by_year.values())} active A-share rows"
                )
        executor.shutdown(wait=True)
        executor = None
        writer.close()
        writer = None

        if len(records) != len(sessions) or not all(
            record["count_verified"] for record in records
        ):
            raise RuntimeError(
                "securities-lending snapshot lacks a verified local session"
            )
        source_rows = int(sum(source_rows_by_year.values()))
        reconciled_rows = (
            quality_totals["missing_or_non_a_share_rows_excluded"]
            + quality_totals["negative_raw_count_rows_excluded"]
            + quality_totals["zero_activity_rows_excluded"]
            + quality_totals["rows_written"]
        )
        if source_rows != reconciled_rows:
            raise RuntimeError(
                "securities-lending full-snapshot row counts do not reconcile"
            )
        parquet = pq.ParquetFile(temporary_output)
        rows_written = int(parquet.metadata.num_rows)
        if rows_written != quality_totals["rows_written"] or rows_written < 1:
            raise RuntimeError(
                "securities-lending streamed Parquet row count is invalid"
            )
        if tuple(parquet.schema_arrow.names) != SECURITIES_LENDING_EVENT_COLUMNS:
            raise RuntimeError("securities-lending streamed Parquet schema is invalid")
        if sorted(int(year) for year in rows_by_year) != requested_years:
            raise RuntimeError(
                "securities-lending snapshot does not cover every requested year"
            )

        ready_records = [
            record
            for record in records
            if int(record["active_a_share_rows"]) >= 6
            and int(record["distinct_factor_values"]) >= 2
        ]
        output_sha256 = file_sha256(temporary_output)
        result = {
            "status": "completed",
            "data_contract": {
                "path": str(DEFAULT_SECURITIES_LENDING_DATA_CONTRACT.resolve()),
                "sha256": file_sha256(DEFAULT_SECURITIES_LENDING_DATA_CONTRACT),
                "preregistered_at": contract["preregistered_at"],
                "forward_return_fields_read": False,
            },
            "source": {
                "provider": source_contract["provider"],
                "endpoint": EASTMONEY_DATACENTER_URL,
                "report_name": EASTMONEY_MARGIN_FINANCING_REPORT,
                "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                "requested_fields": source_contract["requested_fields"],
                "forbidden_fields_requested_or_stored": [],
                "identity_price_market_cap_financing_or_return_fields_requested_or_stored": [],
            },
            "event_frequency": "daily_after_close_securities_lending_activity",
            "trade_years": requested_years,
            "requested_calendar_start": sessions.min().date().isoformat(),
            "requested_calendar_end": sessions.max().date().isoformat(),
            "sessions_requested": int(len(sessions)),
            "sessions_verified": int(len(records)),
            "partition_policy": contract["snapshot_contract"]["partition_policy"],
            "verified_sessions": records,
            "pages_by_trade_year": pages_by_year,
            "source_rows_by_trade_year": source_rows_by_year,
            "rows_by_trade_year": rows_by_year,
            "normalization_quality": {
                "source_rows": source_rows,
                **quality_totals,
                "source_row_reconciliation_errors": 0,
                "duplicate_event_keys": 0,
                "missing_snapshot_values": 0,
                "negative_stored_raw_count_rows": 0,
                "out_of_range_factor_rows": 0,
                "all_daily_partitions_count_verified": True,
                "dates_with_at_least_six_names_and_two_values_before_quality_or_listing_gates": len(
                    ready_records
                ),
                "such_dates_by_year": {
                    str(year): int(count)
                    for year, count in pd.Series(
                        [
                            pd.Timestamp(record["trade_date"]).year
                            for record in ready_records
                        ],
                        dtype="int64",
                    )
                    .value_counts(sort=False)
                    .sort_index()
                    .items()
                },
            },
            "rows_written": rows_written,
            "trade_start": records[0]["trade_date"],
            "trade_end": records[-1]["trade_date"],
            "output": str(output.resolve()),
            "sha256": output_sha256,
            "price_fields_loaded": [],
            "open_close_or_forward_return_fields_read": False,
            "forward_return_fields_read": False,
            "selection_or_promotion_allowed": False,
            "point_in_time_policy": contract["point_in_time_policy"],
            "regulatory_regime_context": contract["regulatory_regime_context"],
            "limitations": [
                "The public consolidated table is queried as it exists today and may revise historical rows.",
                "Historical machine-verifiable publication timestamps are unavailable; the signal assumes prior-session data was published before the following session opened.",
                "Rows with zero sell-plus-repay activity remain missing and are excluded rather than imputed.",
                "Regulatory dates are retained as context only and cannot be used to filter, split, invert, or retune this frozen candidate.",
                "This is a capacity candidate only until a separate no-return gate is frozen and passed.",
            ],
        }
        manifest_content = (
            json.dumps(result, ensure_ascii=False, indent=2, default=_json_default)
            + "\n"
        )
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=manifest.parent, delete=False
        ) as handle:
            handle.write(manifest_content)
            temporary_manifest = Path(handle.name)
        temporary_output.replace(output)
        temporary_manifest.replace(manifest)
        result["manifest_sha256"] = file_sha256(manifest)
        completed = True
        return result
    finally:
        if executor is not None:
            executor.shutdown(wait=False, cancel_futures=True)
        if writer is not None:
            writer.close()
        if not completed:
            temporary_output.unlink(missing_ok=True)
            if temporary_manifest is not None:
                temporary_manifest.unlink(missing_ok=True)


def sync_institutional_survey_events(
    start_year: int, end_year: int, output: Path, manifest: Path
) -> dict[str, Any]:
    """Download long-history institutional-survey notice aggregates.

    The detailed public report is paginated.  Annual requests fail at high
    page offsets, so the fixed intake begins with calendar months and bisects
    any month above the safe page ceiling.  Every accepted partition verifies
    its advertised row count before the final snapshot is written.  Each page
    is normalized immediately so participant identities never enter storage.
    """

    if end_year < start_year:
        raise ValueError("--end-year must not be earlier than --start-year")
    session = _eastmoney_session()
    detail_frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_detail_rows_by_year: dict[str, int] = {}
    partition_records: list[dict[str, Any]] = []
    for month_start, month_end in institutional_survey_month_ranges(
        start_year, end_year
    ):
        frames, records = fetch_institutional_survey_partition_details(
            session,
            month_start,
            month_end,
            maximum_pages=INSTITUTIONAL_SURVEY_MAX_PAGES_PER_PARTITION,
            page_pause_seconds=INSTITUTIONAL_SURVEY_PAGE_PAUSE_SECONDS,
        )
        detail_frames.extend(frames)
        partition_records.extend(records)
        month_pages = sum(int(record["pages"]) for record in records)
        month_rows = sum(int(record["source_rows"]) for record in records)
        year = month_start[:4]
        pages_by_year[year] = pages_by_year.get(year, 0) + month_pages
        source_detail_rows_by_year[year] = (
            source_detail_rows_by_year.get(year, 0) + month_rows
        )
        print(
            f"institutional surveys {month_start[:7]}: {len(records)} verified partitions, "
            f"{month_pages} pages, {month_rows} source detail rows"
        )
    details = (
        pd.concat(detail_frames, ignore_index=True)
        if detail_frames
        else pd.DataFrame(
            columns=[
                "instrument",
                "announcement_date",
                "receive_start_date",
                "receive_end_date",
                "institutional_survey_org_count",
            ]
        )
    )
    merged = aggregate_institutional_survey_details(details)
    if merged.empty:
        raise RuntimeError(
            "institutional-survey sync produced no usable A-share notice events"
        )
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_INSTITUTIONAL_SURVEY_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "dated_institutional_survey_notice",
        "years": list(range(start_year, end_year + 1)),
        "partition_policy": {
            "initial_partition": "calendar_month",
            "maximum_pages_per_partition": INSTITUTIONAL_SURVEY_MAX_PAGES_PER_PARTITION,
            "oversized_partition_policy": "bisect_calendar_dates_until_within_page_ceiling",
            "advertised_source_count_must_equal_rows_fetched": True,
            "partial_snapshot_written_on_failure": False,
        },
        "verified_partitions": partition_records,
        "pages_by_year": pages_by_year,
        "source_detail_rows_by_year": source_detail_rows_by_year,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The public source is queried as it exists today and may revise or omit historical survey notices.",
            "The compact survey-statistics report retains only short recent history, so this snapshot aggregates the long-history detailed report by issuer, NOTICE_DATE, and received-date range.",
            "The request fixes NUMBERNEW=1 to retain a single detailed row per disclosure; participant names and identities are neither requested nor stored, while SUM is retained as the provider's reported institution count.",
            "The join waits until the local trading day after NOTICE_DATE because the source has no reliable intraday publication timestamp.",
            "This is a research event snapshot, not an exchange-grade point-in-time announcement database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_institutional_survey_timing_events(
    output: Path = DEFAULT_INSTITUTIONAL_SURVEY_TIMING_EVENTS,
    manifest: Path = DEFAULT_INSTITUTIONAL_SURVEY_TIMING_EVENT_MANIFEST,
) -> dict[str, Any]:
    """Build the frozen 2019--2025 disclosure-lag snapshot without price data."""

    contract = load_institutional_survey_timing_data_contract()
    source_contract = contract["source"]
    start_year = pd.Timestamp(source_contract["announcement_start"]).year
    end_year = pd.Timestamp(source_contract["announcement_end"]).year
    session = _eastmoney_session()
    detail_frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_detail_rows_by_year: dict[str, int] = {}
    partition_records: list[dict[str, Any]] = []
    for month_start, month_end in institutional_survey_month_ranges(
        start_year, end_year
    ):
        frames, records = fetch_institutional_survey_partition_details(
            session,
            month_start,
            month_end,
            maximum_pages=INSTITUTIONAL_SURVEY_MAX_PAGES_PER_PARTITION,
            page_pause_seconds=INSTITUTIONAL_SURVEY_PAGE_PAUSE_SECONDS,
        )
        detail_frames.extend(frames)
        partition_records.extend(records)
        month_pages = sum(int(record["pages"]) for record in records)
        month_rows = sum(int(record["source_rows"]) for record in records)
        year = month_start[:4]
        pages_by_year[year] = pages_by_year.get(year, 0) + month_pages
        source_detail_rows_by_year[year] = (
            source_detail_rows_by_year.get(year, 0) + month_rows
        )
        print(
            f"institutional survey timing {month_start[:7]}: {len(records)} verified partitions, "
            f"{month_pages} pages, {month_rows} source detail rows"
        )
    details = (
        pd.concat(detail_frames, ignore_index=True)
        if detail_frames
        else pd.DataFrame(
            columns=[
                "instrument",
                "announcement_date",
                "receive_start_date",
                "receive_end_date",
                "institutional_survey_org_count",
            ]
        )
    )
    timing, timing_quality = aggregate_institutional_survey_timing_details(details)
    if timing.empty:
        raise RuntimeError(
            "institutional-survey timing sync produced no usable A-share notice events"
        )
    requested_years = list(range(start_year, end_year + 1))
    observed_years = sorted(
        pd.to_datetime(timing["announcement_date"]).dt.year.unique().tolist()
    )
    if observed_years != requested_years:
        raise RuntimeError(
            "institutional-survey timing snapshot does not cover every requested year"
        )
    if timing.duplicated(["instrument", "announcement_date"]).any():
        raise RuntimeError(
            "institutional-survey timing snapshot contains duplicate event keys"
        )
    if timing["institutional_survey_disclosure_lag_days"].lt(0).any():
        raise RuntimeError(
            "institutional-survey timing snapshot contains a negative disclosure lag"
        )
    _atomic_write_parquet(output, timing)
    result = {
        "status": "completed",
        "data_contract": {
            "path": str(DEFAULT_INSTITUTIONAL_SURVEY_TIMING_DATA_CONTRACT.resolve()),
            "sha256": file_sha256(DEFAULT_INSTITUTIONAL_SURVEY_TIMING_DATA_CONTRACT),
            "preregistered_at": contract["preregistered_at"],
            "forward_return_fields_read": False,
        },
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_INSTITUTIONAL_SURVEY_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
            "requested_columns": source_contract["requested_columns"],
            "participant_identities_requested_or_stored": False,
        },
        "event_frequency": "dated_institutional_survey_disclosure_timing",
        "years": requested_years,
        "partition_policy": contract["snapshot_contract"]["partition_policy"],
        "verified_partitions": partition_records,
        "pages_by_year": pages_by_year,
        "source_detail_rows_by_year": source_detail_rows_by_year,
        "timing_quality": timing_quality,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in timing.groupby(
                pd.to_datetime(timing["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": int(len(timing)),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "price_fields_loaded": [],
        "open_close_or_forward_return_fields_read": False,
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "The public source is queried as it exists today and may revise or omit historical survey notices.",
            "Negative disclosure lags are treated as source anomalies and excluded without clipping or imputation.",
            "The factor becomes usable only after the public NOTICE_DATE, never on a received date.",
            "This is a research event snapshot, not an exchange-grade point-in-time announcement database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_repurchase_plan_events(output: Path, manifest: Path) -> dict[str, Any]:
    """Download the complete public repurchase-plan list as a dated snapshot."""

    session = _eastmoney_session()
    first = _eastmoney_repurchase_request(session, page_number=1)
    result = first["result"]
    pages = int(result.get("pages") or 0)
    if pages < 1:
        raise RuntimeError("repurchase-plan source reported no pages")
    frames: list[pd.DataFrame] = []
    source_rows = 0
    for page_number in range(1, pages + 1):
        payload = (
            first
            if page_number == 1
            else _eastmoney_repurchase_request(session, page_number)
        )
        rows = list((payload.get("result") or {}).get("data") or [])
        source_rows += len(rows)
        normalized = normalize_repurchase_plan_rows(rows)
        if not normalized.empty:
            frames.append(normalized)
    merged = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=REPURCHASE_EVENT_COLUMNS)
    )
    merged = (
        merged.sort_values(["instrument", "announcement_date"], kind="stable")
        .drop_duplicates(["instrument", "announcement_date"], keep="first")
        .reset_index(drop=True)
    )
    if merged.empty:
        raise RuntimeError(
            "repurchase-plan sync produced no usable A-share plan events"
        )
    _atomic_write_parquet(output, merged)
    report = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_REPURCHASE_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "dated_repurchase_plan_announcement",
        "pages": pages,
        "source_rows": source_rows,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The source is a current public snapshot and may revise or omit historical plans.",
            "DIM_DATE is treated as the initial public plan-record date and is made effective only on the strictly next local trading session.",
            "UPDATEDATE, implementation progress, completed share count, and completed repurchase amount are excluded because they can reflect later information.",
            "This is a research event snapshot, not an exchange-grade point-in-time disclosure database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(report, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return report


def sync_holder_count_events(
    start_year: int, end_year: int, output: Path, manifest: Path
) -> dict[str, Any]:
    """Download dated public shareholder-count changes for every quarter end."""

    report_dates = quarterly_report_dates(start_year, end_year)
    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    pages_by_report_date: dict[str, int] = {}
    source_rows_by_report_date: dict[str, int] = {}
    for report_date in report_dates:
        first = _eastmoney_holder_count_request(session, report_date, page_number=1)
        result = first["result"]
        pages = int(result.get("pages") or 0)
        pages_by_report_date[report_date] = pages
        source_rows = 0
        for page_number in range(1, pages + 1):
            payload = (
                first
                if page_number == 1
                else _eastmoney_holder_count_request(session, report_date, page_number)
            )
            rows = list((payload.get("result") or {}).get("data") or [])
            source_rows += len(rows)
            normalized = normalize_holder_count_rows(rows)
            if not normalized.empty:
                frames.append(normalized)
        source_rows_by_report_date[report_date] = source_rows
        print(f"{report_date}: {pages} pages; {source_rows} holder-count source rows")
    merged = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=HOLDER_COUNT_EVENT_COLUMNS)
    )
    merged = (
        merged.sort_values(["instrument", "announcement_date"], kind="stable")
        .drop_duplicates(["instrument", "announcement_date"], keep="last")
        .reset_index(drop=True)
    )
    if merged.empty:
        raise RuntimeError("holder-count sync produced no usable A-share notice events")
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_HOLDER_COUNT_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "quarterly_end_dated_holder_count_notice",
        "report_dates": report_dates,
        "pages_by_report_date": pages_by_report_date,
        "source_rows_by_report_date": source_rows_by_report_date,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The public source is queried as it exists today and can revise or omit historical records.",
            "END_DATE is a holder-count cutoff, not a score-time date; the join uses only the strictly later local session after HOLD_NOTICE_DATE.",
            "INTERVAL_CHRATE, AVG_MARKET_CAP, AVG_HOLD_NUM, TOTAL_MARKET_CAP, and TOTAL_A_SHARES are excluded at request time because they are price- or later-state-derived fields outside this hypothesis.",
            "This is a research event snapshot, not an exchange-grade point-in-time disclosure database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_pledge_events(
    start_year: int, end_year: int, output: Path, manifest: Path
) -> dict[str, Any]:
    """Download all dated public share-pledge notices in the requested years."""

    if start_year > end_year:
        raise ValueError("start_year must not be after end_year")
    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    for year in range(start_year, end_year + 1):
        first = _eastmoney_pledge_request(session, year, page_number=1)
        result = first["result"]
        pages = int(result.get("pages") or 0)
        pages_by_year[str(year)] = pages
        source_rows = 0
        for page_number in range(1, pages + 1):
            payload = (
                first
                if page_number == 1
                else _eastmoney_pledge_request(session, year, page_number)
            )
            rows = list((payload.get("result") or {}).get("data") or [])
            source_rows += len(rows)
            normalized = normalize_pledge_rows(rows)
            if not normalized.empty:
                frames.append(normalized)
        source_rows_by_year[str(year)] = source_rows
        print(f"{year}: {pages} pages; {source_rows} pledge source rows")
    merged = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=PLEDGE_EVENT_COLUMNS)
    )
    merged = (
        merged.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            pledge_share_count=(
                "pledge_share_count",
                lambda values: values.sum(min_count=1),
            ),
            pledge_total_share_ratio=(
                "pledge_total_share_ratio",
                lambda values: values.sum(min_count=1),
            ),
            pledge_event_count=("pledge_event_count", "sum"),
        )
        .loc[:, list(PLEDGE_EVENT_COLUMNS)]
        .sort_values(["instrument", "announcement_date"], kind="stable")
        .reset_index(drop=True)
    )
    if merged.empty:
        raise RuntimeError("pledge sync produced no usable A-share notice events")
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_PLEDGE_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "dated_share_pledge_notice",
        "years": list(range(start_year, end_year + 1)),
        "pages_by_year": pages_by_year,
        "source_rows_by_year": source_rows_by_year,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The public source is queried as it exists today and can revise or omit historical disclosures.",
            "NOTICE_DATE is treated as the public notice date and is made effective only on the strictly next local trading session.",
            "Only PF_NUM (disclosed pledged share count) and PF_TSR (the notice record's reported total-share ratio) are requested. Current prices, current trade date, current market value, warning/liquidation lines, and unfreeze state/dates are excluded at request time.",
            "This is a research event snapshot, not an exchange-grade point-in-time disclosure database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def sync_dividend_plan_events(
    start_year: int, end_year: int, output: Path, manifest: Path
) -> dict[str, Any]:
    """Download all dated public dividend-plan notices in the requested years."""

    if start_year > end_year:
        raise ValueError("start_year must not be after end_year")
    session = _eastmoney_session()
    frames: list[pd.DataFrame] = []
    pages_by_year: dict[str, int] = {}
    source_rows_by_year: dict[str, int] = {}
    for year in range(start_year, end_year + 1):
        first = _eastmoney_dividend_plan_request(session, year, page_number=1)
        result = first["result"]
        pages = int(result.get("pages") or 0)
        pages_by_year[str(year)] = pages
        source_rows = 0
        for page_number in range(1, pages + 1):
            payload = (
                first
                if page_number == 1
                else _eastmoney_dividend_plan_request(session, year, page_number)
            )
            rows = list((payload.get("result") or {}).get("data") or [])
            source_rows += len(rows)
            normalized = normalize_dividend_plan_rows(rows)
            if not normalized.empty:
                frames.append(normalized)
        source_rows_by_year[str(year)] = source_rows
        print(f"{year}: {pages} pages; {source_rows} dividend-plan source rows")
    merged = (
        pd.concat(frames, ignore_index=True)
        if frames
        else pd.DataFrame(columns=DIVIDEND_PLAN_EVENT_COLUMNS)
    )
    merged = (
        merged.groupby(["instrument", "announcement_date"], as_index=False, sort=True)
        .agg(
            dividend_cash_per_ten=(
                "dividend_cash_per_ten",
                lambda values: values.sum(min_count=1),
            ),
            dividend_share_ratio=(
                "dividend_share_ratio",
                lambda values: values.sum(min_count=1),
            ),
            dividend_plan_event_count=("dividend_plan_event_count", "sum"),
        )
        .loc[:, list(DIVIDEND_PLAN_EVENT_COLUMNS)]
        .sort_values(["instrument", "announcement_date"], kind="stable")
        .reset_index(drop=True)
    )
    if merged.empty:
        raise RuntimeError(
            "dividend-plan sync produced no usable A-share notice events"
        )
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "source": {
            "provider": "Eastmoney public datacenter",
            "endpoint": EASTMONEY_DATACENTER_URL,
            "report": EASTMONEY_DIVIDEND_PLAN_REPORT,
            "retrieved_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        "event_frequency": "dated_dividend_plan_notice",
        "years": list(range(start_year, end_year + 1)),
        "pages_by_year": pages_by_year,
        "source_rows_by_year": source_rows_by_year,
        "rows_by_announcement_year": {
            str(year): int(len(group))
            for year, group in merged.groupby(
                pd.to_datetime(merged["announcement_date"]).dt.year, sort=True
            )
        },
        "rows_written": len(merged),
        "output": str(output.resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "The public source is queried as it exists today and can revise or omit historical plan records.",
            "PLAN_NOTICE_DATE is treated as the initial public plan notice and is made effective only on the strictly next local trading session.",
            "Only PRETAX_BONUS_RMB (cash dividend per ten shares) and BONUS_IT_RATIO (announced total bonus/share-transfer ratio) are requested. ASSIGN_PROGRESS, NOTICE_DATE, equity-record/ex-dividend dates, dividend yield, financial fields, and forward-return fields are excluded at request time.",
            "This is a research event snapshot, not an exchange-grade point-in-time disclosure database.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def merge_quarterly_fundamentals(
    input_paths: Iterable[Path], output: Path, manifest: Path
) -> dict[str, Any]:
    """Atomically combine independently downloaded quarterly snapshot chunks.

    Public report downloads can be lengthy.  This recovery path permits small
    date-range downloads without treating any individual chunk as a complete
    research source.  The final output remains a single de-duplicated,
    auditable snapshot.
    """

    paths = [Path(path).expanduser() for path in input_paths]
    if not paths:
        raise ValueError("at least one quarterly snapshot input is required")
    missing = [str(path) for path in paths if not path.exists()]
    if missing:
        raise FileNotFoundError(
            f"quarterly snapshot inputs do not exist: {', '.join(missing)}"
        )
    frames = [load_fundamentals(path) for path in paths]
    merged = pd.concat(frames, ignore_index=True)
    merged = merged.sort_values(
        ["instrument", "report_date", "announcement_date"], kind="stable"
    )
    merged = merged.drop_duplicates(
        ["instrument", "report_date"], keep="first"
    ).reset_index(drop=True)
    if merged.empty:
        raise RuntimeError("quarterly snapshot merge produced no usable rows")
    report_dates = sorted(
        pd.Timestamp(value).date().isoformat()
        for value in merged["report_date"].unique()
    )
    rows_by_report_date = {
        report_date: int((merged["report_date"] == pd.Timestamp(report_date)).sum())
        for report_date in report_dates
    }
    _atomic_write_parquet(output, merged)
    result = {
        "status": "completed",
        "report_frequency": "quarterly",
        "source": {
            "provider": "Eastmoney public datacenter",
            "merged_at": dt.datetime.now(dt.timezone.utc).isoformat(),
            "input_files": [str(path.resolve()) for path in paths],
            "input_sha256": {str(path.resolve()): file_sha256(path) for path in paths},
        },
        "report_dates": report_dates,
        "rows_by_report_date": rows_by_report_date,
        "rows_written": len(merged),
        "output": str(output.expanduser().resolve()),
        "sha256": file_sha256(output),
        "limitations": [
            "Every chunk is a current public snapshot; later corrections may not reproduce the original disclosure values.",
            "The research join waits until the trading day after announcement_date, but it is not a substitute for an exchange-grade point-in-time fundamentals vendor.",
        ],
    }
    _atomic_write_text(
        manifest,
        json.dumps(result, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return result


def load_fundamentals(path: Path) -> pd.DataFrame:
    """Load and validate the local accounting-quality snapshot."""

    if not path.exists():
        raise FileNotFoundError(
            f"fundamental snapshot does not exist: {path}; run sync-fundamentals first"
        )
    frame = pd.read_parquet(path)
    missing = sorted(set(FUNDAMENTAL_COLUMNS) - set(frame.columns))
    if missing:
        raise ValueError(
            f"fundamental snapshot is missing columns: {', '.join(missing)}"
        )
    frame = frame.loc[:, list(FUNDAMENTAL_COLUMNS)].copy()
    for column in ("report_date", "announcement_date"):
        frame[column] = pd.to_datetime(frame[column], errors="coerce")
    for column in ("roe", "net_profit", "revenue_yoy", "profit_yoy"):
        frame[column] = pd.to_numeric(frame[column], errors="coerce")
    frame = frame.dropna(subset=["instrument", "report_date", "announcement_date"])
    return frame.sort_values(
        ["instrument", "announcement_date", "report_date"], kind="stable"
    ).reset_index(drop=True)


