def canonicalize_tushare_cash_conversion_audit_events(
    factor_frame: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Exclude same-announcement multi-period collisions without choosing one."""

    required = set(TUSHARE_CASH_CONVERSION_COLUMNS)
    if missing := sorted(required - set(factor_frame.columns)):
        raise ValueError(
            "Tushare cash-conversion capacity frame is missing columns: "
            + ", ".join(missing)
        )
    events = factor_frame.loc[:, list(TUSHARE_CASH_CONVERSION_COLUMNS)].copy()
    for column in (
        "announcement_date",
        "income_actual_announcement_date",
        "cashflow_actual_announcement_date",
        "report_period",
    ):
        events[column] = pd.to_datetime(events[column], errors="coerce").dt.normalize()
    events[TUSHARE_CASH_CONVERSION_FACTOR_NAME] = pd.to_numeric(
        events[TUSHARE_CASH_CONVERSION_FACTOR_NAME], errors="coerce"
    )
    if (
        events[list(TUSHARE_CASH_CONVERSION_COLUMNS)].isna().any().any()
        or events.duplicated(["instrument", "announcement_date", "report_period"]).any()
        or not np.isfinite(events[TUSHARE_CASH_CONVERSION_FACTOR_NAME]).all()
    ):
        raise ValueError("Tushare cash-conversion audit event keys are invalid")
    sessions = pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    if sessions.empty:
        raise ValueError("Tushare cash-conversion availability calendar is empty")
    positions = sessions.searchsorted(events["announcement_date"], side="right")
    if (positions >= len(sessions)).any():
        raise ValueError(
            "Tushare cash-conversion audit event lacks a strict-next session"
        )
    events["event_effective_date"] = sessions.take(positions)
    collision_mask = events.duplicated(["instrument", "announcement_date"], keep=False)
    collision_groups = int(
        events.loc[collision_mask]
        .groupby(["instrument", "announcement_date"], sort=False)
        .ngroups
    )
    collision_rows = int(collision_mask.sum())
    canonical = (
        events.loc[~collision_mask]
        .copy()
        .sort_values(
            ["event_effective_date", "instrument", "report_period"], kind="stable"
        )
    )
    if canonical.duplicated(["instrument", "event_effective_date"]).any():
        raise ValueError(
            "Tushare cash-conversion same-effective-date ambiguity survived exclusion"
        )
    return canonical.reset_index(drop=True), {
        "source_factor_events": int(len(events)),
        "same_instrument_same_announcement_multi_period_collision_groups_excluded": (
            collision_groups
        ),
        "same_instrument_same_announcement_multi_period_collision_rows_excluded": (
            collision_rows
        ),
        "canonical_factor_events_after_collision_exclusion": int(len(canonical)),
        "collision_period_selection_performed": False,
        "strictly_next_local_session_availability_applied": True,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def canonicalize_tushare_audit_opinion_events(
    factor_frame: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Map every frozen audit event to the strict next local session."""

    required = set(TUSHARE_AUDIT_OPINION_COLUMNS)
    if missing := sorted(required - set(factor_frame.columns)):
        raise ValueError(
            "Tushare audit-opinion events are missing columns: " + ", ".join(missing)
        )
    events = factor_frame.loc[:, list(TUSHARE_AUDIT_OPINION_COLUMNS)].copy()
    events["announcement_date"] = pd.to_datetime(
        events["announcement_date"], errors="coerce"
    ).dt.normalize()
    events[TUSHARE_AUDIT_OPINION_RAW_COLUMN] = pd.to_numeric(
        events[TUSHARE_AUDIT_OPINION_RAW_COLUMN], errors="coerce"
    )
    if (
        events[["announcement_date", "instrument"]].isna().any().any()
        or events.duplicated(["instrument", "announcement_date"]).any()
        or not events[TUSHARE_AUDIT_OPINION_RAW_COLUMN].isin([0, 1]).all()
        or set(events["provider"].astype(str)) != {"tushare"}
    ):
        raise ValueError("Tushare audit-opinion event keys or values are invalid")
    sessions = pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    positions = sessions.searchsorted(events["announcement_date"], side="right")
    if (positions >= len(sessions)).any():
        raise ValueError(
            "Tushare audit-opinion event lacks a strict-next-session mapping"
        )
    events["event_effective_date"] = sessions.take(positions)
    if not events["event_effective_date"].gt(events["announcement_date"]).all():
        raise ValueError(
            "Tushare audit-opinion availability is not strictly next-session"
        )
    events[TUSHARE_AUDIT_OPINION_FACTOR_NAME] = events[
        TUSHARE_AUDIT_OPINION_RAW_COLUMN
    ].astype("float64")
    return events.reset_index(drop=True), {
        "source_factor_events": int(len(events)),
        "strictly_next_local_session_availability_applied": True,
        "same_session_trade_allowed": False,
        "event_formula_recomputed_from_frozen_binary_column": True,
        "text_or_report_period_selection_performed": False,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def expand_tushare_audit_opinion_events_to_sessions(
    canonical_events: pd.DataFrame,
    target_sessions: pd.DatetimeIndex,
    *,
    maximum_event_age_days: int,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Expand strict-next-session events through announcement plus three days."""

    if maximum_event_age_days != 3:
        raise ValueError("Tushare audit-opinion event age changed")
    required = {
        "instrument",
        "announcement_date",
        "event_effective_date",
        TUSHARE_AUDIT_OPINION_FACTOR_NAME,
    }
    if missing := sorted(required - set(canonical_events.columns)):
        raise ValueError(
            "Tushare audit-opinion canonical events are missing columns: "
            + ", ".join(missing)
        )
    sessions = pd.DatetimeIndex(target_sessions).normalize().unique().sort_values()
    rows: list[dict[str, Any]] = []
    for event in canonical_events.itertuples(index=False):
        announcement = pd.Timestamp(event.announcement_date).normalize()
        effective = pd.Timestamp(event.event_effective_date).normalize()
        expiry = announcement + pd.Timedelta(days=maximum_event_age_days)
        first = int(sessions.searchsorted(effective, side="left"))
        last = int(sessions.searchsorted(expiry, side="right"))
        for session in sessions[first:last]:
            rows.append(
                {
                    "datetime": pd.Timestamp(session),
                    "instrument": str(event.instrument),
                    "announcement_date": announcement,
                    "event_effective_date": effective,
                    "event_age_days": int((pd.Timestamp(session) - announcement).days),
                    TUSHARE_AUDIT_OPINION_FACTOR_NAME: float(
                        getattr(event, TUSHARE_AUDIT_OPINION_FACTOR_NAME)
                    ),
                }
            )
    columns = [
        "datetime",
        "instrument",
        "announcement_date",
        "event_effective_date",
        "event_age_days",
        TUSHARE_AUDIT_OPINION_FACTOR_NAME,
    ]
    expanded = pd.DataFrame(rows, columns=columns)
    before_latest = int(len(expanded))
    if not expanded.empty:
        expanded = expanded.sort_values(
            [
                "instrument",
                "datetime",
                "event_effective_date",
                "announcement_date",
            ],
            kind="stable",
        ).drop_duplicates(["instrument", "datetime"], keep="last")
    if (
        expanded.duplicated(["instrument", "datetime"]).any()
        or not expanded["event_age_days"].between(1, maximum_event_age_days).all()
    ):
        raise ValueError("Tushare audit-opinion session expansion is invalid")
    return expanded.reset_index(drop=True), {
        "target_session_count": int(len(sessions)),
        "expanded_rows_before_latest_effective_event_rule": before_latest,
        "older_overlapping_event_rows_superseded": before_latest - int(len(expanded)),
        "expanded_rows": int(len(expanded)),
        "maximum_event_age_calendar_days_from_announcement": maximum_event_age_days,
        "strict_next_session_and_announcement_age_rule_applied": True,
        "future_event_or_return_used_for_overlap_resolution": False,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def tushare_audit_opinion_capacity(
    factor_frame: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    research_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    capacity_contract: dict[str, Any],
    event_contract: dict[str, Any],
) -> dict[str, Any]:
    """Count fixed three-session binary audit-event cohorts without prices."""

    sessions = pd.DatetimeIndex(research_calendar).normalize().unique().sort_values()
    hold_days = int(capacity_contract["holding_period_trading_days"])
    if len(sessions) <= hold_days:
        raise ValueError("Tushare audit-opinion capacity calendar is too short")
    rebalances = sessions[:-hold_days:hold_days]
    canonical, canonical_audit = canonicalize_tushare_audit_opinion_events(
        factor_frame, full_calendar
    )
    expanded, expansion_audit = expand_tushare_audit_opinion_events_to_sessions(
        canonical,
        rebalances,
        maximum_event_age_days=int(event_contract["maximum_event_age_calendar_days"]),
    )
    if expanded.empty:
        active = expanded.copy()
    else:

        def active_on_signal(row: Any) -> bool:
            signal = pd.Timestamp(row.datetime).normalize()
            return any(
                pd.Timestamp(start).normalize()
                <= signal
                <= pd.Timestamp(end).normalize()
                for start, end in instrument_intervals.get(str(row.instrument), [])
            )

        expanded["instrument_active"] = [
            active_on_signal(row) for row in expanded.itertuples(index=False)
        ]
        active = expanded.loc[expanded["instrument_active"]].copy()
    active = attach_listing_age_sessions(active, instrument_intervals, full_calendar)
    active = active.rename(
        columns={"announcement_date": "audit_opinion_announcement_date"}
    )
    active = attach_quality_asof(
        active,
        fundamentals,
        max_age_days=int(capacity_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    eligible = active.loc[active["quality_eligible"].fillna(False)].copy()
    values = pd.to_numeric(eligible[TUSHARE_AUDIT_OPINION_FACTOR_NAME], errors="coerce")
    valid = eligible.loc[np.isfinite(values)].copy()
    valid[TUSHARE_AUDIT_OPINION_FACTOR_NAME] = values.loc[valid.index]
    cross_sections = valid.groupby("datetime", sort=True).agg(
        valid_names=("instrument", "nunique"),
        distinct_factor_values=(TUSHARE_AUDIT_OPINION_FACTOR_NAME, "nunique"),
        clean_names=(TUSHARE_AUDIT_OPINION_FACTOR_NAME, "sum"),
    )
    complete = cross_sections.loc[
        cross_sections["valid_names"].ge(
            int(capacity_contract["minimum_eligible_names_per_cross_section"])
        )
        & cross_sections["distinct_factor_values"].ge(
            int(capacity_contract["minimum_distinct_factor_values"])
        )
    ]
    by_year = {
        str(int(year)): int(count)
        for year, count in complete.groupby(complete.index.year).size().items()
    }
    cohort_count = int(len(complete))
    observed_years = len(by_year)
    passed = bool(
        cohort_count >= int(capacity_contract["minimum_required_cohorts"])
        and observed_years >= int(capacity_contract["minimum_observed_years"])
    )
    return {
        "factor": TUSHARE_AUDIT_OPINION_FACTOR_NAME,
        "source_rows": int(len(factor_frame)),
        "event_canonicalization": canonical_audit,
        "rebalance_expansion": expansion_audit,
        "non_overlapping_rebalance_capacity": int(len(rebalances)),
        "active_holding_event_rows": int(len(active)),
        "quality_and_listing_eligible_event_rows": int(len(eligible)),
        "valid_factor_rows": int(len(valid)),
        "dates_with_any_valid_name": int(len(cross_sections)),
        "dates_with_at_least_six_valid_names": int(
            cross_sections["valid_names"]
            .ge(int(capacity_contract["minimum_eligible_names_per_cross_section"]))
            .sum()
        ),
        "dates_with_both_binary_values": int(
            cross_sections["distinct_factor_values"].ge(2).sum()
        ),
        "potential_complete_cohorts": cohort_count,
        "potential_complete_cohorts_by_year": by_year,
        "observed_calendar_years": observed_years,
        "minimum_required_cohorts": int(capacity_contract["minimum_required_cohorts"]),
        "minimum_observed_calendar_years": int(
            capacity_contract["minimum_observed_years"]
        ),
        "minimum_valid_names_per_factor_cohort": int(
            capacity_contract["minimum_eligible_names_per_cross_section"]
        ),
        "minimum_distinct_factor_values_per_cohort": int(
            capacity_contract["minimum_distinct_factor_values"]
        ),
        "capacity_gate_passed": passed,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def prepare_tushare_audit_opinion_uniqueness_sessions(
    factor_frame: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    event_contract: dict[str, Any],
    uniqueness_contract: dict[str, Any],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Build quality/listing-eligible 2025 binary event sessions without prices."""

    sessions = pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    sessions = sessions[
        (sessions >= pd.Timestamp(uniqueness_contract["screen_start"]))
        & (sessions <= pd.Timestamp(uniqueness_contract["screen_end"]))
    ]
    canonical, canonical_audit = canonicalize_tushare_audit_opinion_events(
        factor_frame, full_calendar
    )
    expanded, expansion_audit = expand_tushare_audit_opinion_events_to_sessions(
        canonical,
        sessions,
        maximum_event_age_days=int(event_contract["maximum_event_age_calendar_days"]),
    )
    if not expanded.empty:

        def active_on_signal(row: Any) -> bool:
            signal = pd.Timestamp(row.datetime).normalize()
            return any(
                pd.Timestamp(start).normalize()
                <= signal
                <= pd.Timestamp(end).normalize()
                for start, end in instrument_intervals.get(str(row.instrument), [])
            )

        expanded["instrument_active"] = [
            active_on_signal(row) for row in expanded.itertuples(index=False)
        ]
        expanded = expanded.loc[expanded["instrument_active"]].copy()
    expanded = attach_listing_age_sessions(
        expanded, instrument_intervals, full_calendar
    )
    expanded = expanded.rename(
        columns={"announcement_date": "audit_opinion_announcement_date"}
    )
    expanded = attach_quality_asof(
        expanded,
        fundamentals,
        max_age_days=int(uniqueness_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    values = pd.to_numeric(expanded[TUSHARE_AUDIT_OPINION_FACTOR_NAME], errors="coerce")
    eligible = expanded.loc[
        expanded["quality_eligible"].fillna(False) & np.isfinite(values)
    ].copy()
    eligible[TUSHARE_AUDIT_OPINION_FACTOR_NAME] = values.loc[eligible.index]
    return eligible.reset_index(drop=True), {
        "event_canonicalization": canonical_audit,
        "session_expansion": expansion_audit,
        "screen_sessions": int(len(sessions)),
        "active_quality_listing_eligible_factor_rows": int(len(eligible)),
        "eligible_factor_sessions": int(eligible["datetime"].nunique()),
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def expand_tushare_cash_conversion_events_to_sessions(
    canonical_events: pd.DataFrame,
    target_sessions: pd.DatetimeIndex,
    *,
    maximum_event_age_days: int,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Expand accepted events to fixed sessions and prefer only newer disclosures."""

    if maximum_event_age_days < 0:
        raise ValueError("Tushare cash-conversion maximum event age is invalid")
    required = {
        "instrument",
        "announcement_date",
        "report_period",
        "event_effective_date",
        TUSHARE_CASH_CONVERSION_FACTOR_NAME,
    }
    if missing := sorted(required - set(canonical_events.columns)):
        raise ValueError(
            "Tushare cash-conversion canonical events are missing columns: "
            + ", ".join(missing)
        )
    sessions = pd.DatetimeIndex(target_sessions).normalize().unique().sort_values()
    rows: list[dict[str, Any]] = []
    for event in canonical_events.itertuples(index=False):
        effective = pd.Timestamp(event.event_effective_date).normalize()
        first = int(sessions.searchsorted(effective, side="left"))
        last = int(
            sessions.searchsorted(
                effective + pd.Timedelta(days=maximum_event_age_days), side="right"
            )
        )
        for session in sessions[first:last]:
            rows.append(
                {
                    "datetime": pd.Timestamp(session),
                    "instrument": str(event.instrument),
                    "announcement_date": pd.Timestamp(
                        event.announcement_date
                    ).normalize(),
                    "report_period": pd.Timestamp(event.report_period).normalize(),
                    "event_effective_date": effective,
                    "event_age_days": int((pd.Timestamp(session) - effective).days),
                    TUSHARE_CASH_CONVERSION_FACTOR_NAME: float(
                        getattr(event, TUSHARE_CASH_CONVERSION_FACTOR_NAME)
                    ),
                }
            )
    columns = [
        "datetime",
        "instrument",
        "announcement_date",
        "report_period",
        "event_effective_date",
        "event_age_days",
        TUSHARE_CASH_CONVERSION_FACTOR_NAME,
    ]
    expanded = pd.DataFrame(rows, columns=columns)
    before_latest = int(len(expanded))
    if not expanded.empty:
        expanded = expanded.sort_values(
            [
                "instrument",
                "datetime",
                "event_effective_date",
                "announcement_date",
                "report_period",
            ],
            kind="stable",
        ).drop_duplicates(["instrument", "datetime"], keep="last")
    overlapping_rows_superseded = before_latest - int(len(expanded))
    if (
        expanded.duplicated(["instrument", "datetime"]).any()
        or not expanded["event_age_days"].between(0, maximum_event_age_days).all()
    ):
        raise ValueError("Tushare cash-conversion session expansion is invalid")
    return expanded.reset_index(drop=True), {
        "target_session_count": int(len(sessions)),
        "expanded_rows_before_latest_effective_event_rule": before_latest,
        "older_overlapping_event_rows_superseded": overlapping_rows_superseded,
        "expanded_rows": int(len(expanded)),
        "maximum_event_age_calendar_days": maximum_event_age_days,
        "future_event_or_return_used_for_overlap_resolution": False,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def tushare_cash_conversion_capacity(
    factor_frame: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    research_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    capacity_contract: dict[str, Any],
    event_contract: dict[str, Any],
) -> dict[str, Any]:
    """Count fixed three-session accounting-event cohorts without prices."""

    sessions = pd.DatetimeIndex(research_calendar).normalize().unique().sort_values()
    hold_days = int(capacity_contract["holding_period_trading_days"])
    if len(sessions) <= hold_days:
        raise ValueError("Tushare cash-conversion capacity calendar is too short")
    rebalances = sessions[:-hold_days:hold_days]
    canonical, canonical_audit = canonicalize_tushare_cash_conversion_audit_events(
        factor_frame, full_calendar
    )
    expanded, expansion_audit = expand_tushare_cash_conversion_events_to_sessions(
        canonical,
        rebalances,
        maximum_event_age_days=int(event_contract["maximum_event_age_calendar_days"]),
    )
    if expanded.empty:
        active = expanded.copy()
    else:

        def active_on_signal(row: Any) -> bool:
            signal = pd.Timestamp(row.datetime).normalize()
            return any(
                pd.Timestamp(start).normalize()
                <= signal
                <= pd.Timestamp(end).normalize()
                for start, end in instrument_intervals.get(str(row.instrument), [])
            )

        expanded["instrument_active"] = [
            active_on_signal(row) for row in expanded.itertuples(index=False)
        ]
        active = expanded.loc[expanded["instrument_active"]].copy()
    active = attach_listing_age_sessions(
        active,
        instrument_intervals,
        pd.DatetimeIndex(full_calendar),
    )
    active = active.rename(
        columns={
            "announcement_date": "cash_conversion_announcement_date",
            "report_period": "cash_conversion_report_period",
        }
    )
    active = attach_quality_asof(
        active,
        fundamentals,
        max_age_days=int(capacity_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    eligible = active.loc[active["quality_eligible"].fillna(False)].copy()
    values = pd.to_numeric(
        eligible[TUSHARE_CASH_CONVERSION_FACTOR_NAME], errors="coerce"
    )
    valid = eligible.loc[np.isfinite(values)].copy()
    valid[TUSHARE_CASH_CONVERSION_FACTOR_NAME] = values.loc[valid.index]
    cross_sections = valid.groupby("datetime", sort=True).agg(
        valid_names=("instrument", "nunique"),
        distinct_factor_values=(TUSHARE_CASH_CONVERSION_FACTOR_NAME, "nunique"),
    )
    complete = cross_sections.loc[
        cross_sections["valid_names"].ge(
            int(capacity_contract["minimum_eligible_names_per_cross_section"])
        )
        & cross_sections["distinct_factor_values"].ge(
            int(capacity_contract["minimum_distinct_factor_values"])
        )
    ]
    by_year = {
        str(int(year)): int(count)
        for year, count in complete.groupby(complete.index.year).size().items()
    }
    cohort_count = int(len(complete))
    observed_years = len(by_year)
    passed = bool(
        cohort_count >= int(capacity_contract["minimum_required_cohorts"])
        and observed_years >= int(capacity_contract["minimum_observed_years"])
    )
    return {
        "factor": TUSHARE_CASH_CONVERSION_FACTOR_NAME,
        "source_rows": int(len(factor_frame)),
        "event_canonicalization": canonical_audit,
        "rebalance_expansion": expansion_audit,
        "non_overlapping_rebalance_capacity": int(len(rebalances)),
        "active_holding_event_rows": int(len(active)),
        "quality_and_listing_eligible_event_rows": int(len(eligible)),
        "valid_factor_rows": int(len(valid)),
        "dates_with_any_valid_name": int(len(cross_sections)),
        "potential_complete_cohorts": cohort_count,
        "potential_complete_cohorts_by_year": by_year,
        "observed_calendar_years": observed_years,
        "minimum_required_cohorts": int(capacity_contract["minimum_required_cohorts"]),
        "minimum_observed_calendar_years": int(
            capacity_contract["minimum_observed_years"]
        ),
        "minimum_valid_names_per_factor_cohort": int(
            capacity_contract["minimum_eligible_names_per_cross_section"]
        ),
        "minimum_distinct_factor_values_per_cohort": int(
            capacity_contract["minimum_distinct_factor_values"]
        ),
        "capacity_gate_passed": passed,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def summarize_tushare_cash_conversion_uniqueness(
    factor_sessions: pd.DataFrame,
    comparison_frame: pd.DataFrame,
    *,
    contract: dict[str, Any],
    factor_name: str = TUSHARE_CASH_CONVERSION_FACTOR_NAME,
    factor_label: str = "Tushare cash-conversion",
) -> dict[str, Any]:
    """Gate one sparse factor against 54 fields and two quality composites."""

    factor_columns = [
        "datetime",
        "instrument",
        factor_name,
    ]
    if missing := sorted(set(factor_columns) - set(factor_sessions.columns)):
        raise ValueError(
            f"{factor_label} uniqueness factor frame is missing columns: "
            + ", ".join(missing)
        )
    all_fields = (
        *TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS,
        *TUSHARE_CASH_CONVERSION_ADDITIONAL_SEMANTIC_FIELDS,
    )
    comparison_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *all_fields,
    ]
    if missing := sorted(set(comparison_columns) - set(comparison_frame.columns)):
        raise ValueError(
            f"{factor_label} comparison frame is missing columns: " + ", ".join(missing)
        )
    if (
        tuple(contract.get("comparison_factors") or ())
        != TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS
        or tuple(
            contract.get("additional_composite_semantic_checks_not_counted_twice") or ()
        )
        != TUSHARE_CASH_CONVERSION_ADDITIONAL_SEMANTIC_FIELDS
    ):
        raise ValueError(f"{factor_label} uniqueness comparison catalog changed")
    start = pd.Timestamp(contract["screen_start"]).normalize()
    end = pd.Timestamp(contract["screen_end"]).normalize()
    minimum_names = int(contract["minimum_pairwise_names_per_session"])
    minimum_sessions = int(contract["minimum_pairwise_sessions_per_comparison"])
    maximum_correlation = float(
        contract["maximum_allowed_absolute_median_daily_rank_correlation"]
    )
    factor = factor_sessions.loc[:, factor_columns].copy()
    factor["datetime"] = pd.to_datetime(
        factor["datetime"], errors="coerce"
    ).dt.normalize()
    factor[factor_name] = pd.to_numeric(factor[factor_name], errors="coerce")
    factor = factor.loc[factor["datetime"].between(start, end)].copy()
    if (
        factor[["datetime", "instrument"]].isna().any().any()
        or factor.duplicated(["instrument", "datetime"]).any()
        or not np.isfinite(factor[factor_name]).all()
    ):
        raise ValueError(f"{factor_label} uniqueness factor keys are invalid")
    comparison = comparison_frame.loc[:, comparison_columns].copy()
    comparison["datetime"] = pd.to_datetime(
        comparison["datetime"], errors="coerce"
    ).dt.normalize()
    comparison = comparison.loc[comparison["datetime"].between(start, end)].copy()
    if (
        comparison[["datetime", "instrument"]].isna().any().any()
        or comparison.duplicated(["instrument", "datetime"]).any()
        or not (
            comparison["quality_eligible"].fillna(False)
            == (
                comparison["fundamental_quality_eligible"].fillna(False)
                & comparison["listing_seasoning_eligible"].fillna(False)
            )
        ).all()
    ):
        raise ValueError(f"{factor_label} comparison keys or quality gate are invalid")
    comparison = comparison.loc[comparison["quality_eligible"].fillna(False)].copy()
    merged = comparison.merge(
        factor,
        on=["datetime", "instrument"],
        how="inner",
        validate="one_to_one",
    )
    if merged.empty:
        raise ValueError(f"{factor_label} uniqueness has no eligible rows")

    def compare_field(field: str) -> dict[str, Any]:
        values = merged.loc[
            :,
            [
                "datetime",
                "instrument",
                factor_name,
                field,
            ],
        ].copy()
        values[field] = pd.to_numeric(values[field], errors="coerce")
        values = values.loc[
            np.isfinite(values[factor_name]) & np.isfinite(values[field])
        ]
        correlations: list[float] = []
        pairwise_counts: list[int] = []
        sessions_with_minimum_names = 0
        sessions_with_two_values = 0
        for _, daily in values.groupby("datetime", sort=True):
            count = int(daily["instrument"].nunique())
            if count < minimum_names:
                continue
            sessions_with_minimum_names += 1
            pairwise_counts.append(count)
            if (
                daily[factor_name].nunique(dropna=True) < 2
                or daily[field].nunique(dropna=True) < 2
            ):
                continue
            sessions_with_two_values += 1
            correlation = float(
                daily[factor_name]
                .rank(method="average", pct=True)
                .corr(daily[field].rank(method="average", pct=True))
            )
            if math.isfinite(correlation):
                correlations.append(correlation)
        series = pd.Series(correlations, dtype="float64")
        median = float(series.median()) if len(series) else None
        enough = len(series) >= minimum_sessions
        independent = bool(median is not None and abs(median) < maximum_correlation)
        return {
            "comparison_field": field,
            "pairwise_rows": int(len(values)),
            "sessions_with_minimum_pairwise_names": sessions_with_minimum_names,
            "sessions_with_minimum_names_and_two_values": sessions_with_two_values,
            "valid_daily_rank_correlation_sessions": int(len(series)),
            "minimum_pairwise_names_observed": (
                int(min(pairwise_counts)) if pairwise_counts else 0
            ),
            "median_daily_rank_correlation": median,
            "absolute_median_daily_rank_correlation": (
                abs(median) if median is not None else None
            ),
            "p05_daily_rank_correlation": (
                float(series.quantile(0.05)) if len(series) else None
            ),
            "p95_daily_rank_correlation": (
                float(series.quantile(0.95)) if len(series) else None
            ),
            "minimum_sessions_gate_passed": enough,
            "absolute_median_correlation_gate_passed": independent,
            "uniqueness_gate_passed": bool(enough and independent),
        }

    field_results = [
        compare_field(field) for field in TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS
    ]
    composite_results = [
        compare_field(field)
        for field in TUSHARE_CASH_CONVERSION_ADDITIONAL_SEMANTIC_FIELDS
    ]
    every_result = [*field_results, *composite_results]
    nearest = max(
        every_result,
        key=lambda item: float(
            item["absolute_median_daily_rank_correlation"]
            if item["absolute_median_daily_rank_correlation"] is not None
            else -1.0
        ),
    )
    passed = all(item["uniqueness_gate_passed"] for item in every_result)
    return {
        "factor": factor_name,
        "comparison_field_count": len(field_results),
        "additional_composite_semantic_check_count": len(composite_results),
        "eligible_factor_comparison_rows": int(len(merged)),
        "eligible_factor_comparison_sessions": int(merged["datetime"].nunique()),
        "minimum_pairwise_names_per_session": minimum_names,
        "minimum_pairwise_sessions_per_comparison": minimum_sessions,
        "maximum_allowed_absolute_median_daily_rank_correlation": (maximum_correlation),
        "fields_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in field_results)
        ),
        "fields_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in field_results
            )
        ),
        "additional_composites_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in composite_results)
        ),
        "additional_composites_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in composite_results
            )
        ),
        "nearest_existing_or_semantic_field": nearest["comparison_field"],
        "maximum_observed_absolute_median_daily_rank_correlation": nearest[
            "absolute_median_daily_rank_correlation"
        ],
        "field_results": field_results,
        "additional_composite_semantic_results": composite_results,
        "uniqueness_gate_passed": passed,
        "same_quality_listing_and_factor_complete_cross_section_applied": True,
        "future_open_close_or_return_fields_derived": [],
        "forward_return_fields_read": False,
    }


def summarize_tushare_free_float_scarcity_uniqueness(
    factor_frame: pd.DataFrame,
    comparison_frame: pd.DataFrame,
    *,
    contract: dict[str, Any],
) -> dict[str, Any]:
    """Gate structural scarcity against the exact 54 close-known fields."""

    factor_columns = [
        "trade_date",
        "instrument",
        TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME,
    ]
    comparison_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *TUSHARE_FREE_FLOAT_SCARCITY_COMPARISON_FIELDS,
    ]
    if missing := sorted(set(factor_columns) - set(factor_frame.columns)):
        raise ValueError(
            "Tushare free-float-scarcity uniqueness factor frame is missing columns: "
            + ", ".join(missing)
        )
    if missing := sorted(set(comparison_columns) - set(comparison_frame.columns)):
        raise ValueError(
            "Tushare free-float-scarcity comparison frame is missing columns: "
            + ", ".join(missing)
        )
    if (
        tuple(contract.get("comparison_factors") or ())
        != TUSHARE_FREE_FLOAT_SCARCITY_COMPARISON_FIELDS
        or contract.get("required_named_near_neighbor") != "free_float_cap_proxy"
    ):
        raise ValueError(
            "Tushare free-float-scarcity uniqueness comparison catalog changed"
        )
    start = pd.Timestamp(contract["screen_start"]).normalize()
    end = pd.Timestamp(contract["screen_end"]).normalize()
    minimum_names = int(contract["minimum_pairwise_names_per_session"])
    minimum_sessions = int(contract["minimum_pairwise_sessions_per_comparison"])
    maximum_correlation = float(
        contract["maximum_allowed_absolute_median_daily_rank_correlation"]
    )
    factor = factor_frame.loc[:, factor_columns].copy()
    factor["trade_date"] = pd.to_datetime(
        factor["trade_date"], errors="coerce"
    ).dt.normalize()
    factor[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME] = pd.to_numeric(
        factor[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME], errors="coerce"
    )
    factor = factor.loc[factor["trade_date"].between(start, end)].copy()
    values = factor[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME]
    if (
        factor[["trade_date", "instrument"]].isna().any().any()
        or factor.duplicated(["instrument", "trade_date"]).any()
        or not np.isfinite(values).all()
        or not values.ge(0.0).all()
        or not values.lt(1.0).all()
    ):
        raise ValueError("Tushare free-float-scarcity uniqueness input is invalid")

    comparison = comparison_frame.loc[:, comparison_columns].copy()
    comparison["datetime"] = pd.to_datetime(
        comparison["datetime"], errors="coerce"
    ).dt.normalize()
    comparison = comparison.loc[comparison["datetime"].between(start, end)].copy()
    if (
        comparison[["datetime", "instrument"]].isna().any().any()
        or comparison.duplicated(["instrument", "datetime"]).any()
        or not (
            comparison["quality_eligible"].fillna(False)
            == (
                comparison["fundamental_quality_eligible"].fillna(False)
                & comparison["listing_seasoning_eligible"].fillna(False)
            )
        ).all()
    ):
        raise ValueError(
            "Tushare free-float-scarcity comparison keys or quality gate are invalid"
        )
    comparison = comparison.loc[comparison["quality_eligible"].fillna(False)].copy()
    merged = comparison.merge(
        factor.rename(columns={"trade_date": "datetime"}),
        on=["datetime", "instrument"],
        how="inner",
        validate="one_to_one",
    )
    if merged.empty:
        raise ValueError("Tushare free-float-scarcity uniqueness has no eligible rows")

    field_results: list[dict[str, Any]] = []
    for field in TUSHARE_FREE_FLOAT_SCARCITY_COMPARISON_FIELDS:
        pairwise = merged.loc[
            :,
            [
                "datetime",
                "instrument",
                TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME,
                field,
            ],
        ].copy()
        pairwise[field] = pd.to_numeric(pairwise[field], errors="coerce")
        pairwise = pairwise.loc[
            np.isfinite(pairwise[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME])
            & np.isfinite(pairwise[field])
        ]
        correlations: list[float] = []
        pairwise_counts: list[int] = []
        sessions_with_minimum_names = 0
        sessions_with_two_values = 0
        for _, daily in pairwise.groupby("datetime", sort=True):
            count = int(daily["instrument"].nunique())
            if count < minimum_names:
                continue
            sessions_with_minimum_names += 1
            pairwise_counts.append(count)
            if (
                daily[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME].nunique(dropna=True) < 2
                or daily[field].nunique(dropna=True) < 2
            ):
                continue
            sessions_with_two_values += 1
            correlation = float(
                daily[TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME]
                .rank(method="average", pct=True)
                .corr(daily[field].rank(method="average", pct=True))
            )
            if math.isfinite(correlation):
                correlations.append(correlation)
        series = pd.Series(correlations, dtype="float64")
        median = float(series.median()) if len(series) else None
        enough = len(series) >= minimum_sessions
        independent = bool(median is not None and abs(median) < maximum_correlation)
        field_results.append(
            {
                "comparison_field": field,
                "pairwise_rows": int(len(pairwise)),
                "sessions_with_minimum_pairwise_names": sessions_with_minimum_names,
                "sessions_with_minimum_names_and_two_values": sessions_with_two_values,
                "valid_daily_rank_correlation_sessions": int(len(series)),
                "minimum_pairwise_names_observed": (
                    int(min(pairwise_counts)) if pairwise_counts else 0
                ),
                "median_daily_rank_correlation": median,
                "absolute_median_daily_rank_correlation": (
                    abs(median) if median is not None else None
                ),
                "p05_daily_rank_correlation": (
                    float(series.quantile(0.05)) if len(series) else None
                ),
                "p95_daily_rank_correlation": (
                    float(series.quantile(0.95)) if len(series) else None
                ),
                "minimum_sessions_gate_passed": enough,
                "absolute_median_correlation_gate_passed": independent,
                "uniqueness_gate_passed": bool(enough and independent),
            }
        )
    nearest = max(
        field_results,
        key=lambda item: float(
            item["absolute_median_daily_rank_correlation"]
            if item["absolute_median_daily_rank_correlation"] is not None
            else -1.0
        ),
    )
    named_neighbor = next(
        item
        for item in field_results
        if item["comparison_field"] == "free_float_cap_proxy"
    )
    passed = all(item["uniqueness_gate_passed"] for item in field_results)
    return {
        "factor": TUSHARE_FREE_FLOAT_SCARCITY_FACTOR_NAME,
        "comparison_field_count": len(field_results),
        "eligible_factor_comparison_rows": int(len(merged)),
        "eligible_factor_comparison_sessions": int(merged["datetime"].nunique()),
        "minimum_pairwise_names_per_session": minimum_names,
        "minimum_pairwise_sessions_per_comparison": minimum_sessions,
        "maximum_allowed_absolute_median_daily_rank_correlation": maximum_correlation,
        "fields_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in field_results)
        ),
        "fields_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in field_results
            )
        ),
        "nearest_existing_field": nearest["comparison_field"],
        "maximum_observed_absolute_median_daily_rank_correlation": nearest[
            "absolute_median_daily_rank_correlation"
        ],
        "named_near_neighbor": named_neighbor,
        "field_results": field_results,
        "uniqueness_gate_passed": passed,
        "same_quality_listing_and_factor_complete_cross_section_applied": True,
        "future_open_close_or_return_fields_derived": [],
        "forward_return_fields_read": False,
    }


def summarize_tushare_daily_pb_uniqueness(
    pb_frame: pd.DataFrame,
    comparison_frame: pd.DataFrame,
    *,
    contract: dict[str, Any],
) -> dict[str, Any]:
    """Compare PB with every frozen close-known field without reading returns."""

    pb_columns = ["trade_date", "instrument", TUSHARE_DAILY_PB_FACTOR_NAME]
    required_pb = set(pb_columns)
    if missing := sorted(required_pb - set(pb_frame.columns)):
        raise ValueError(
            "Tushare daily PB uniqueness frame is missing columns: "
            + ", ".join(missing)
        )
    comparison_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *TUSHARE_DAILY_PB_COMPARISON_FIELDS,
    ]
    required_comparison = set(comparison_columns)
    if missing := sorted(required_comparison - set(comparison_frame.columns)):
        raise ValueError(
            "Tushare daily PB comparison frame is missing columns: "
            + ", ".join(missing)
        )
    if (
        tuple(contract.get("comparison_fields") or ())
        != TUSHARE_DAILY_PB_COMPARISON_FIELDS
    ):
        raise ValueError("Tushare daily PB uniqueness comparison-field order changed")

    start = pd.Timestamp(str(contract["start"])).normalize()
    end = pd.Timestamp(str(contract["end"])).normalize()
    minimum_names = int(contract["minimum_pairwise_names_per_session"])
    minimum_sessions = int(contract["minimum_pairwise_sessions_per_comparison"])
    maximum_correlation = float(
        contract["maximum_allowed_absolute_median_daily_rank_correlation"]
    )
    pb = pb_frame.loc[:, pb_columns].copy()
    pb["trade_date"] = pd.to_datetime(pb["trade_date"], errors="coerce").dt.normalize()
    pb[TUSHARE_DAILY_PB_FACTOR_NAME] = pd.to_numeric(
        pb[TUSHARE_DAILY_PB_FACTOR_NAME], errors="coerce"
    )
    pb = pb.loc[pb["trade_date"].between(start, end)].copy()
    if (
        pb[["trade_date", "instrument"]].isna().any().any()
        or pb.duplicated(["instrument", "trade_date"]).any()
        or not pb[TUSHARE_DAILY_PB_FACTOR_NAME].gt(0.0).all()
        or not np.isfinite(pb[TUSHARE_DAILY_PB_FACTOR_NAME]).all()
    ):
        raise ValueError("Tushare daily PB uniqueness input is invalid")

    comparison = comparison_frame.loc[:, comparison_columns].copy()
    comparison["datetime"] = pd.to_datetime(
        comparison["datetime"], errors="coerce"
    ).dt.normalize()
    comparison = comparison.loc[comparison["datetime"].between(start, end)].copy()
    if (
        comparison[["datetime", "instrument"]].isna().any().any()
        or comparison.duplicated(["instrument", "datetime"]).any()
    ):
        raise ValueError("Tushare daily PB comparison keys are invalid")
    quality_consistent = comparison["quality_eligible"].fillna(False) == (
        comparison["fundamental_quality_eligible"].fillna(False)
        & comparison["listing_seasoning_eligible"].fillna(False)
    )
    if not quality_consistent.all():
        raise ValueError(
            "Tushare daily PB comparison quality/listing gate is inconsistent"
        )
    comparison = comparison.loc[comparison["quality_eligible"].fillna(False)].copy()
    merged = comparison.merge(
        pb.rename(columns={"trade_date": "datetime"}),
        on=["datetime", "instrument"],
        how="inner",
        validate="one_to_one",
    )
    if merged.empty:
        raise ValueError("Tushare daily PB uniqueness has no common eligible rows")

    field_results: list[dict[str, Any]] = []
    for field in TUSHARE_DAILY_PB_COMPARISON_FIELDS:
        values = merged.loc[
            :,
            ["datetime", "instrument", TUSHARE_DAILY_PB_FACTOR_NAME, field],
        ].copy()
        values[field] = pd.to_numeric(values[field], errors="coerce")
        finite = np.isfinite(values[TUSHARE_DAILY_PB_FACTOR_NAME]) & np.isfinite(
            values[field]
        )
        values = values.loc[finite]
        correlations: list[float] = []
        pairwise_name_counts: list[int] = []
        sessions_with_minimum_names = 0
        sessions_with_two_values = 0
        for _, daily in values.groupby("datetime", sort=True):
            pairwise_names = int(daily["instrument"].nunique())
            if pairwise_names < minimum_names:
                continue
            sessions_with_minimum_names += 1
            pairwise_name_counts.append(pairwise_names)
            if (
                daily[TUSHARE_DAILY_PB_FACTOR_NAME].nunique(dropna=True) < 2
                or daily[field].nunique(dropna=True) < 2
            ):
                continue
            sessions_with_two_values += 1
            pb_rank = daily[TUSHARE_DAILY_PB_FACTOR_NAME].rank(
                method="average", pct=True
            )
            comparison_rank = daily[field].rank(method="average", pct=True)
            correlation = float(pb_rank.corr(comparison_rank, method="pearson"))
            if math.isfinite(correlation):
                correlations.append(correlation)
        correlation_series = pd.Series(correlations, dtype="float64")
        median_correlation = (
            float(correlation_series.median()) if len(correlation_series) else None
        )
        enough_sessions = len(correlations) >= minimum_sessions
        below_threshold = bool(
            median_correlation is not None
            and abs(median_correlation) < maximum_correlation
        )
        field_results.append(
            {
                "comparison_field": field,
                "pairwise_rows": int(len(values)),
                "sessions_with_minimum_pairwise_names": sessions_with_minimum_names,
                "sessions_with_minimum_names_and_two_values": sessions_with_two_values,
                "valid_daily_rank_correlation_sessions": int(len(correlations)),
                "minimum_pairwise_names_observed": (
                    int(min(pairwise_name_counts)) if pairwise_name_counts else 0
                ),
                "median_daily_rank_correlation": median_correlation,
                "absolute_median_daily_rank_correlation": (
                    abs(median_correlation) if median_correlation is not None else None
                ),
                "p05_daily_rank_correlation": (
                    float(correlation_series.quantile(0.05))
                    if len(correlation_series)
                    else None
                ),
                "p95_daily_rank_correlation": (
                    float(correlation_series.quantile(0.95))
                    if len(correlation_series)
                    else None
                ),
                "minimum_sessions_gate_passed": enough_sessions,
                "absolute_median_correlation_gate_passed": below_threshold,
                "uniqueness_gate_passed": bool(enough_sessions and below_threshold),
            }
        )
    nearest = max(
        field_results,
        key=lambda item: float(
            item["absolute_median_daily_rank_correlation"]
            if item["absolute_median_daily_rank_correlation"] is not None
            else -1.0
        ),
    )
    passed = all(item["uniqueness_gate_passed"] for item in field_results)
    return {
        "factor": TUSHARE_DAILY_PB_FACTOR_NAME,
        "comparison_field_count": len(field_results),
        "eligible_pb_comparison_rows": int(len(merged)),
        "eligible_pb_comparison_sessions": int(merged["datetime"].nunique()),
        "minimum_pairwise_names_per_session": minimum_names,
        "minimum_pairwise_sessions_per_comparison": minimum_sessions,
        "maximum_allowed_absolute_median_daily_rank_correlation": maximum_correlation,
        "fields_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in field_results)
        ),
        "fields_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in field_results
            )
        ),
        "nearest_existing_field": nearest["comparison_field"],
        "maximum_observed_absolute_median_daily_rank_correlation": nearest[
            "absolute_median_daily_rank_correlation"
        ],
        "field_results": field_results,
        "uniqueness_gate_passed": passed,
        "same_quality_listing_and_pb_complete_cross_section_applied": True,
        "forward_open_close_or_return_fields_derived": [],
        "forward_return_fields_read": False,
    }


def summarize_tushare_sw_industry_breadth_uniqueness(
    factor_frame: pd.DataFrame,
    comparison_frame: pd.DataFrame,
    *,
    contract: dict[str, Any],
    minimum_pairwise_names_per_session: int,
) -> dict[str, Any]:
    """Compare SW breadth with all 45 frozen close-known factor fields."""

    factor_columns = [
        "trade_date",
        "instrument",
        TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME,
    ]
    if missing := sorted(set(factor_columns) - set(factor_frame.columns)):
        raise ValueError(
            "Tushare SW uniqueness factor frame is missing columns: "
            + ", ".join(missing)
        )
    comparison_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *TUSHARE_SW_INDUSTRY_BREADTH_COMPARISON_FIELDS,
    ]
    if missing := sorted(set(comparison_columns) - set(comparison_frame.columns)):
        raise ValueError(
            "Tushare SW uniqueness comparison frame is missing columns: "
            + ", ".join(missing)
        )
    if (
        tuple(contract.get("comparison_factors") or ())
        != TUSHARE_SW_INDUSTRY_BREADTH_COMPARISON_FIELDS
    ):
        raise ValueError("Tushare SW uniqueness comparison-field order changed")

    start = pd.Timestamp(str(contract["screen_start"])).normalize()
    end = pd.Timestamp(str(contract["screen_end"])).normalize()
    minimum_names = int(minimum_pairwise_names_per_session)
    minimum_sessions = int(contract["minimum_pairwise_sessions"])
    maximum_correlation = float(
        contract["maximum_allowed_absolute_median_daily_rank_correlation"]
    )
    if minimum_names < 2 or minimum_sessions < 1:
        raise ValueError("Tushare SW uniqueness pairwise thresholds are invalid")

    factor = factor_frame.loc[:, factor_columns].copy()
    factor["trade_date"] = pd.to_datetime(
        factor["trade_date"], errors="coerce"
    ).dt.normalize()
    factor["instrument"] = factor["instrument"].astype("string")
    factor[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME] = pd.to_numeric(
        factor[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME], errors="coerce"
    )
    factor = factor.loc[factor["trade_date"].between(start, end)].copy()
    if (
        factor[["trade_date", "instrument"]].isna().any().any()
        or factor.duplicated(["instrument", "trade_date"]).any()
        or not np.isfinite(factor[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME]).all()
        or not factor[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME].between(0.0, 1.0).all()
    ):
        raise ValueError("Tushare SW uniqueness factor input is invalid")

    comparison = comparison_frame.loc[:, comparison_columns].copy()
    comparison["datetime"] = pd.to_datetime(
        comparison["datetime"], errors="coerce"
    ).dt.normalize()
    comparison["instrument"] = comparison["instrument"].astype("string")
    comparison = comparison.loc[comparison["datetime"].between(start, end)].copy()
    if (
        comparison[["datetime", "instrument"]].isna().any().any()
        or comparison.duplicated(["instrument", "datetime"]).any()
    ):
        raise ValueError("Tushare SW uniqueness comparison keys are invalid")
    quality_consistent = comparison["quality_eligible"].fillna(False) == (
        comparison["fundamental_quality_eligible"].fillna(False)
        & comparison["listing_seasoning_eligible"].fillna(False)
    )
    if not quality_consistent.all():
        raise ValueError("Tushare SW uniqueness quality/listing gate is inconsistent")
    comparison = comparison.loc[comparison["quality_eligible"].fillna(False)].copy()
    merged = comparison.merge(
        factor.rename(columns={"trade_date": "datetime"}),
        on=["datetime", "instrument"],
        how="inner",
        validate="one_to_one",
    )
    if merged.empty:
        raise ValueError("Tushare SW uniqueness has no common eligible rows")

    field_results: list[dict[str, Any]] = []
    for field in TUSHARE_SW_INDUSTRY_BREADTH_COMPARISON_FIELDS:
        values = merged.loc[
            :,
            [
                "datetime",
                "instrument",
                TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME,
                field,
            ],
        ].copy()
        values[field] = pd.to_numeric(values[field], errors="coerce")
        finite = np.isfinite(
            values[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME]
        ) & np.isfinite(values[field])
        values = values.loc[finite]
        correlations: list[float] = []
        pairwise_name_counts: list[int] = []
        sessions_with_minimum_names = 0
        sessions_with_two_values = 0
        for _, daily in values.groupby("datetime", sort=True):
            pairwise_names = int(daily["instrument"].nunique())
            if pairwise_names < minimum_names:
                continue
            sessions_with_minimum_names += 1
            pairwise_name_counts.append(pairwise_names)
            if (
                daily[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME].nunique(dropna=True) < 2
                or daily[field].nunique(dropna=True) < 2
            ):
                continue
            sessions_with_two_values += 1
            breadth_rank = daily[TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME].rank(
                method="average", pct=True
            )
            comparison_rank = daily[field].rank(method="average", pct=True)
            correlation = float(breadth_rank.corr(comparison_rank, method="pearson"))
            if math.isfinite(correlation):
                correlations.append(correlation)
        correlation_series = pd.Series(correlations, dtype="float64")
        median_correlation = (
            float(correlation_series.median()) if len(correlation_series) else None
        )
        enough_sessions = len(correlations) >= minimum_sessions
        below_threshold = bool(
            median_correlation is not None
            and abs(median_correlation) < maximum_correlation
        )
        field_results.append(
            {
                "comparison_field": field,
                "pairwise_rows": int(len(values)),
                "sessions_with_minimum_pairwise_names": (sessions_with_minimum_names),
                "sessions_with_minimum_names_and_two_values": (
                    sessions_with_two_values
                ),
                "valid_daily_rank_correlation_sessions": int(len(correlations)),
                "minimum_pairwise_names_observed": (
                    int(min(pairwise_name_counts)) if pairwise_name_counts else 0
                ),
                "median_daily_rank_correlation": median_correlation,
                "absolute_median_daily_rank_correlation": (
                    abs(median_correlation) if median_correlation is not None else None
                ),
                "p05_daily_rank_correlation": (
                    float(correlation_series.quantile(0.05))
                    if len(correlation_series)
                    else None
                ),
                "p95_daily_rank_correlation": (
                    float(correlation_series.quantile(0.95))
                    if len(correlation_series)
                    else None
                ),
                "minimum_sessions_gate_passed": enough_sessions,
                "absolute_median_correlation_gate_passed": below_threshold,
                "uniqueness_gate_passed": bool(enough_sessions and below_threshold),
            }
        )
    nearest = max(
        field_results,
        key=lambda item: float(
            item["absolute_median_daily_rank_correlation"]
            if item["absolute_median_daily_rank_correlation"] is not None
            else -1.0
        ),
    )
    passed = all(item["uniqueness_gate_passed"] for item in field_results)
    return {
        "factor": TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME,
        "comparison_field_count": len(field_results),
        "eligible_factor_comparison_rows": int(len(merged)),
        "eligible_factor_comparison_sessions": int(merged["datetime"].nunique()),
        "minimum_pairwise_names_per_session": minimum_names,
        "minimum_pairwise_names_source": (
            "derived_from_capacity_minimum_eligible_names_per_cross_section"
        ),
        "minimum_pairwise_sessions_per_comparison": minimum_sessions,
        "maximum_allowed_absolute_median_daily_rank_correlation": (maximum_correlation),
        "fields_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in field_results)
        ),
        "fields_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in field_results
            )
        ),
        "nearest_existing_field": nearest["comparison_field"],
        "maximum_observed_absolute_median_daily_rank_correlation": nearest[
            "absolute_median_daily_rank_correlation"
        ],
        "field_results": field_results,
        "uniqueness_gate_passed": passed,
        "same_quality_listing_and_factor_complete_cross_section_applied": True,
        "forward_open_close_or_return_fields_derived": [],
        "forward_return_fields_read": False,
    }


def load_tushare_sw_terminal_comparison_factors(
    *,
    start: str,
    end: str,
) -> tuple[pd.DataFrame, pd.DataFrame, dict[str, Any]]:
    """Revalidate and load only the frozen 2025 moneyflow and PB comparisons."""

    if start != "2025-01-01" or end != "2025-12-31":
        raise ValueError("Tushare SW rich-factor comparison window changed")
    for label, path, digest in (
        (
            "Tushare moneyflow",
            DEFAULT_TUSHARE_MONEYFLOW_FULL_MANIFEST,
            TUSHARE_MONEYFLOW_FULL_MANIFEST_SHA256,
        ),
        (
            "Tushare daily PB",
            DEFAULT_TUSHARE_DAILY_PB_FULL_MANIFEST,
            TUSHARE_DAILY_PB_FULL_MANIFEST_SHA256,
        ),
    ):
        resolved = path.expanduser().resolve()
        if not resolved.exists() or file_sha256(resolved) != digest:
            raise ValueError(f"{label} terminal comparison manifest changed")

    screen_start = pd.Timestamp(start)
    screen_end = pd.Timestamp(end)
    moneyflow_spec = load_tushare_moneyflow_capacity_preregistration()
    moneyflow_full, moneyflow_evidence = validate_tushare_moneyflow_full_snapshot(
        DEFAULT_TUSHARE_MONEYFLOW_FULL_MANIFEST,
        moneyflow_spec,
    )
    moneyflow = moneyflow_full.loc[
        pd.to_datetime(moneyflow_full["trade_date"])
        .dt.normalize()
        .between(screen_start, screen_end),
        ["trade_date", "instrument", TUSHARE_MONEYFLOW_FACTOR_NAME],
    ].copy()
    del moneyflow_full
    gc.collect()
    if (
        moneyflow.empty
        or moneyflow.duplicated(["instrument", "trade_date"]).any()
        or not np.isfinite(moneyflow[TUSHARE_MONEYFLOW_FACTOR_NAME]).all()
        or not moneyflow[TUSHARE_MONEYFLOW_FACTOR_NAME].between(-1.0, 1.0).all()
    ):
        raise ValueError("Tushare SW moneyflow comparison values are invalid")

    pb_spec = load_tushare_daily_pb_capacity_preregistration()
    pb_full, pb_evidence = validate_tushare_daily_pb_full_snapshot(
        DEFAULT_TUSHARE_DAILY_PB_FULL_MANIFEST,
        pb_spec,
    )
    pb = pb_full.loc[
        pd.to_datetime(pb_full["trade_date"])
        .dt.normalize()
        .between(screen_start, screen_end),
        ["trade_date", "instrument", TUSHARE_DAILY_PB_FACTOR_NAME],
    ].copy()
    del pb_full
    gc.collect()
    if (
        pb.empty
        or pb.duplicated(["instrument", "trade_date"]).any()
        or not np.isfinite(pb[TUSHARE_DAILY_PB_FACTOR_NAME]).all()
        or not pb[TUSHARE_DAILY_PB_FACTOR_NAME].gt(0.0).all()
    ):
        raise ValueError("Tushare SW PB comparison values are invalid")

    return (
        moneyflow,
        pb,
        {
            "comparison_window_start": start,
            "comparison_window_end": end,
            "tushare_moneyflow": {
                "manifest": moneyflow_evidence["manifest"],
                "factor": TUSHARE_MONEYFLOW_FACTOR_NAME,
                "screen_rows": int(len(moneyflow)),
                "screen_sessions": int(moneyflow["trade_date"].nunique()),
                "full_snapshot_revalidated": True,
            },
            "tushare_daily_pb": {
                "manifest": pb_evidence["manifest"],
                "factor": TUSHARE_DAILY_PB_FACTOR_NAME,
                "screen_rows": int(len(pb)),
                "screen_sessions": int(pb["trade_date"].nunique()),
                "full_snapshot_revalidated": True,
            },
            "price_fields_loaded": [],
            "forward_return_fields_read": False,
        },
    )


def prepare_tushare_cash_conversion_uniqueness_sessions(
    factor_frame: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    event_contract: dict[str, Any],
    uniqueness_contract: dict[str, Any],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Build quality/listing-eligible 2025 factor sessions without prices."""

    screen_sessions = pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    screen_sessions = screen_sessions[
        (screen_sessions >= pd.Timestamp(uniqueness_contract["screen_start"]))
        & (screen_sessions <= pd.Timestamp(uniqueness_contract["screen_end"]))
    ]
    canonical, canonical_audit = canonicalize_tushare_cash_conversion_audit_events(
        factor_frame, full_calendar
    )
    expanded, expansion_audit = expand_tushare_cash_conversion_events_to_sessions(
        canonical,
        screen_sessions,
        maximum_event_age_days=int(event_contract["maximum_event_age_calendar_days"]),
    )
    if not expanded.empty:

        def active_on_signal(row: Any) -> bool:
            signal = pd.Timestamp(row.datetime).normalize()
            return any(
                pd.Timestamp(start).normalize()
                <= signal
                <= pd.Timestamp(end).normalize()
                for start, end in instrument_intervals.get(str(row.instrument), [])
            )

        expanded["instrument_active"] = [
            active_on_signal(row) for row in expanded.itertuples(index=False)
        ]
        expanded = expanded.loc[expanded["instrument_active"]].copy()
    expanded = attach_listing_age_sessions(
        expanded,
        instrument_intervals,
        full_calendar,
    )
    expanded = expanded.rename(
        columns={
            "announcement_date": "cash_conversion_announcement_date",
            "report_period": "cash_conversion_report_period",
        }
    )
    expanded = attach_quality_asof(
        expanded,
        fundamentals,
        max_age_days=int(uniqueness_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    values = pd.to_numeric(
        expanded[TUSHARE_CASH_CONVERSION_FACTOR_NAME], errors="coerce"
    )
    eligible = expanded.loc[
        expanded["quality_eligible"].fillna(False) & np.isfinite(values)
    ].copy()
    eligible[TUSHARE_CASH_CONVERSION_FACTOR_NAME] = values.loc[eligible.index]
    return eligible.reset_index(drop=True), {
        "event_canonicalization": canonical_audit,
        "session_expansion": expansion_audit,
        "screen_sessions": int(len(screen_sessions)),
        "active_quality_listing_eligible_factor_rows": int(len(eligible)),
        "eligible_factor_sessions": int(eligible["datetime"].nunique()),
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def load_tushare_cash_conversion_comparison_frame(
    provider_uri: Path,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    *,
    uniqueness_contract: dict[str, Any],
    comparison_sources: dict[str, Any],
    batch_size: int = 128,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Load the exact 54 close-known comparison fields only after capacity."""

    screen_start = str(uniqueness_contract["screen_start"])
    screen_end = str(uniqueness_contract["screen_end"])
    if screen_start != "2025-01-01" or screen_end != "2025-12-31":
        raise ValueError("Tushare cash-conversion uniqueness window changed")
    moneyflow, pb, rich_evidence = load_tushare_sw_terminal_comparison_factors(
        start=screen_start,
        end=screen_end,
    )
    sw_spec = load_tushare_sw_industry_breadth_capacity_preregistration()
    sw_manifest = resolve_repository_record_path(
        comparison_sources["terminal_tushare_sw_breadth"]["full_manifest_path"]
    )
    membership_intervals, context_frames, sw_validation = (
        validate_tushare_sw_industry_membership_snapshot(sw_manifest, sw_spec)
    )
    if not sw_validation["coverage"][
        "membership_coverage_gate_passed_before_close_known_inputs"
    ]:
        raise ValueError(
            "Tushare cash-conversion SW comparison membership coverage failed"
        )
    sw_factor, sw_construction = load_tushare_sw_industry_breadth_factor(
        provider_uri,
        membership_intervals,
        context_frames,
        sw_spec,
        batch_size=256,
        window_start=screen_start,
        window_end=screen_end,
    )
    extended_start = (
        (pd.Timestamp(screen_start) - pd.Timedelta(days=7)).date().isoformat()
    )
    market = load_market_data(
        provider_uri,
        start=extended_start,
        end=screen_end,
        batch_size=batch_size,
    )
    market = attach_quality_asof(
        market,
        fundamentals,
        max_age_days=int(uniqueness_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    billboard_source = comparison_sources["daily_billboard"]
    holder_source = comparison_sources["holder_count_changes"]
    market = attach_billboard_events_asof(
        market,
        load_billboard_events(resolve_repository_record_path(billboard_source["path"])),
        max_age_days=int(billboard_source["maximum_age_days"]),
    )
    market = attach_holder_count_events_asof(
        market,
        load_holder_count_events(resolve_repository_record_path(holder_source["path"])),
        max_age_days=int(holder_source["maximum_age_days"]),
    )
    ranked = rank_factor_frame(market)
    ranked = ranked.loc[
        pd.to_datetime(ranked["datetime"])
        .dt.normalize()
        .between(screen_start, screen_end)
    ].copy()
    local_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *TUSHARE_DAILY_PB_COMPARISON_FIELDS,
        *BILLBOARD_FACTOR_DIAGNOSTIC_COLUMNS,
        *HOLDER_COUNT_FACTOR_DIAGNOSTIC_COLUMNS,
        *TUSHARE_CASH_CONVERSION_ADDITIONAL_SEMANTIC_FIELDS,
    ]
    comparison = ranked.loc[:, local_columns].copy()
    del market, ranked
    gc.collect()
    for rich_frame, factor_name in (
        (moneyflow, TUSHARE_MONEYFLOW_FACTOR_NAME),
        (pb, TUSHARE_DAILY_PB_FACTOR_NAME),
        (sw_factor, TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME),
    ):
        rich = rich_frame.rename(columns={"trade_date": "datetime"}).copy()
        rich["datetime"] = pd.to_datetime(
            rich["datetime"], errors="coerce"
        ).dt.normalize()
        rich["instrument"] = rich["instrument"].astype(str)
        comparison = comparison.merge(
            rich.loc[:, ["datetime", "instrument", factor_name]],
            on=["datetime", "instrument"],
            how="left",
            validate="one_to_one",
        )
    if (
        comparison.duplicated(["instrument", "datetime"]).any()
        or tuple(
            field
            for field in TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS
            if field in comparison.columns
        )
        != TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS
    ):
        raise ValueError(
            "Tushare cash-conversion comparison frame catalog or keys changed"
        )
    return comparison, {
        "comparison_window_start": screen_start,
        "comparison_window_end": screen_end,
        "comparison_field_count": len(TUSHARE_CASH_CONVERSION_COMPARISON_FIELDS),
        "additional_composite_semantic_fields": list(
            TUSHARE_CASH_CONVERSION_ADDITIONAL_SEMANTIC_FIELDS
        ),
        "terminal_moneyflow_and_pb": rich_evidence,
        "terminal_sw_breadth": {
            "source_evidence": sw_validation["source_evidence"],
            "membership_coverage": sw_validation["coverage"],
            "factor_construction": sw_construction,
            "screen_rows": int(len(sw_factor)),
        },
        "daily_billboard": billboard_source,
        "holder_count_changes": holder_source,
        "same_session_close_known_market_inputs_transiently_loaded": [
            "$close",
            "$open",
            "$high",
            "$low",
            "$volume",
            "$amount",
            "$factor",
            "$turnover",
            "$vwap",
        ],
        "future_open_close_or_return_fields_read": False,
        "forward_return_fields_read": False,
    }


def require_unconsumed_jqdata_moneyflow_capacity(
    experiment_root: Path,
    *,
    source_manifest_sha256: str,
) -> None:
    """Allow one completed no-return capacity audit per immutable full snapshot."""

    for path in sorted(
        experiment_root.expanduser().glob("*_jqdata_moneyflow_capacity_audit.json")
    ):
        record = load_json_record(path)
        source = (
            (record.get("preregistration") or {}).get("source_evidence") or {}
        ).get("manifest") or {}
        if (
            record.get("status") == "completed"
            and record.get("purpose") == JQDATA_MONEYFLOW_CAPACITY_PURPOSE
            and source.get("sha256") == source_manifest_sha256
        ):
            raise ValueError(
                f"JQData moneyflow capacity snapshot is already consumed: {path}"
            )


def run_jqdata_moneyflow_capacity_audit(args: argparse.Namespace) -> dict[str, Any]:
    """Run the frozen JQData classified-flow capacity gate without prices."""

    spec = load_jqdata_moneyflow_capacity_preregistration()
    factor_frame, source_evidence = validate_jqdata_moneyflow_full_snapshot(
        Path(args.manifest), spec
    )
    experiment_root = Path(args.experiment_root).expanduser()
    require_unconsumed_jqdata_moneyflow_capacity(
        experiment_root,
        source_manifest_sha256=source_evidence["manifest"]["sha256"],
    )
    contract = spec["run_contract"]
    provider_uri = Path(args.provider_uri).expanduser().resolve()
    calendar_path = provider_uri / "calendars" / "day.txt"
    source_calendar_sha256 = source_evidence["local_calendar"]["sha256"]
    if (
        not calendar_path.exists()
        or file_sha256(calendar_path) != source_calendar_sha256
    ):
        raise ValueError(
            "JQData moneyflow capacity provider calendar does not match the source snapshot"
        )
    holding_universe_path = (
        provider_uri / "instruments" / f"{contract['holding_universe']}.txt"
    )
    if not holding_universe_path.exists():
        raise FileNotFoundError(
            f"JQData moneyflow holding-universe file is missing: {holding_universe_path}"
        )
    point_in_time = spec["point_in_time_context"]
    holding_contract = point_in_time["holding_universe"]
    holding_fingerprint = point_in_time_interval_fingerprint(
        holding_universe_path,
        start=point_in_time["fingerprint_range_start"],
        end=point_in_time["fingerprint_range_end"],
    )
    if holding_fingerprint != {
        "sha256": holding_contract["sha256"],
        "intervals": holding_contract["intervals"],
    }:
        raise ValueError(
            "JQData moneyflow holding universe differs from its preregistration"
        )
    full_calendar, research_calendar, intervals = local_market_capacity_context(
        provider_uri,
        market=contract["holding_universe"],
        start=contract["start"],
        end=contract["end"],
    )
    quality = spec["quarterly_quality_snapshot"]
    fundamentals = load_fundamentals(resolve_repository_record_path(quality["path"]))
    capacity = jqdata_moneyflow_capacity(
        factor_frame,
        fundamentals,
        full_calendar,
        research_calendar,
        intervals,
        contract=contract,
    )
    admitted = bool(capacity["capacity_gate_passed"])
    decision = (
        "eligible_only_for_separate_fingerprint_bound_return_diagnostic_preregistration"
        if admitted
        else "rejected_before_return_diagnostic_insufficient_quality_listing_seasoned_cohorts"
    )
    run_id = _timestamp()
    audit = {
        "kind": "a_share_jqdata_moneyflow_capacity_audit",
        "run_id": run_id,
        "status": "completed",
        "purpose": JQDATA_MONEYFLOW_CAPACITY_PURPOSE,
        "preregistration": {
            "path": str(DEFAULT_JQDATA_MONEYFLOW_CAPACITY_SPEC.resolve()),
            "sha256": file_sha256(DEFAULT_JQDATA_MONEYFLOW_CAPACITY_SPEC),
            "preregistered_at": spec["preregistered_at"],
            "source_evidence": source_evidence,
        },
        "factor_catalog": [JQDATA_MONEYFLOW_FACTOR_NAME],
        "later_diagnostic_direction_if_capacity_passes": spec[
            "later_diagnostic_direction_if_capacity_passes"
        ],
        "run_contract": contract,
        "source_capacity": capacity,
        "source_admitted_for_separate_return_diagnostic_preregistration": admitted,
        "decision": decision,
        "data": {
            "provider_uri": str(provider_uri),
            "full_calendar_start": full_calendar.min().date().isoformat(),
            "full_calendar_end": full_calendar.max().date().isoformat(),
            "research_calendar_start": research_calendar.min().date().isoformat(),
            "research_calendar_end": research_calendar.max().date().isoformat(),
            "calendar_path": str(calendar_path),
            "calendar_sha256": file_sha256(calendar_path),
            "holding_universe": contract["holding_universe"],
            "holding_universe_path": str(holding_universe_path),
            "holding_universe_sha256": file_sha256(holding_universe_path),
            "holding_universe_clipped_fingerprint": holding_fingerprint,
            "instrument_span_count": int(len(intervals)),
            "price_fields_loaded": [],
            "open_close_or_forward_return_fields_read": False,
        },
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "Capacity is only a no-outcome upper bound; passing does not imply association, tradability, or a usable strategy.",
            "No open, close, forward return, score, current selection, or order field is loaded by this audit.",
            "A pass authorizes only a new immutable return-diagnostic preregistration bound to this audit fingerprint.",
            "The licensed JQData product and local historical snapshot are user-provided evidence and are not bundled in Git.",
        ],
    }
    experiment_root.mkdir(parents=True, exist_ok=True)
    destination = experiment_root / f"{run_id}_jqdata_moneyflow_capacity_audit.json"
    _atomic_write_text(
        destination,
        json.dumps(audit, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return {
        "status": "completed",
        "audit_path": str(destination.resolve()),
        "factor_capacity": capacity,
        "source_admitted_for_separate_return_diagnostic_preregistration": admitted,
        "decision": decision,
        "forward_return_fields_read": False,
    }


