def validate_eastmoney_balance_sheet_resilience_full_snapshot(
    manifest_path: Path,
    spec: dict[str, Any],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Revalidate all quarterly factor rows without loading market outcomes."""

    manifest_path = manifest_path.expanduser().resolve()
    full_record = load_eastmoney_balance_sheet_resilience_full_source_record()
    if (
        manifest_path
        != DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_FULL_MANIFEST.resolve()
        or file_sha256(manifest_path)
        != EASTMONEY_BALANCE_SHEET_RESILIENCE_FULL_MANIFEST_SHA256
        or file_sha256(manifest_path)
        != (full_record.get("full_source_manifest") or {}).get("sha256")
    ):
        raise ValueError(
            "Eastmoney balance-sheet-resilience full manifest fingerprint mismatch"
        )
    manifest = load_json_record(manifest_path, kind="a_share_rich_data_snapshot")
    files = sorted(
        list(manifest.get("files") or []), key=lambda item: item.get("report_date", "")
    )
    expected_dates = spec["full_source_snapshot_contract"]["report_dates"]
    request = manifest.get("source_request") or {}
    coverage = manifest.get("coverage") or {}
    if (
        manifest.get("dataset") != "eastmoney_balance_sheet_resilience"
        or manifest.get("provider") != "eastmoney"
        or manifest.get("status")
        != "full_source_coverage_passed_pending_no_return_capacity_and_uniqueness"
        or [item.get("report_date") for item in files] != expected_dates
        or request.get("new_network_partitions") != 27
        or request.get("accepted_partitions_reused_without_network") != 1
        or request.get("new_provider_calls") != 277
        or request.get("unused_transported_fields_persisted") is not False
        or coverage.get("source_coverage_gate_passed") is not True
        or manifest.get("price_fields_loaded") != []
        or manifest.get("forward_return_fields_read") is not False
        or manifest.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError(
            "Eastmoney balance-sheet-resilience full snapshot failed the source gate"
        )
    contract = load_json_record(
        DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_DATA_CONTRACT,
        kind="a_share_eastmoney_balance_sheet_resilience_data_contract",
    )
    universe_link = contract["local_context"]["holding_universe"]
    universe_path = resolve_repository_record_path(universe_link["path"])
    if file_sha256(universe_path) != universe_link["sha256"]:
        raise ValueError("Eastmoney balance-sheet-resilience holding universe changed")
    universe = pd.read_csv(
        universe_path,
        sep="\t",
        header=None,
        names=["instrument", "active_start", "active_end"],
        dtype={"instrument": "string"},
    )
    universe["active_start"] = pd.to_datetime(universe["active_start"]).dt.normalize()
    universe["active_end"] = pd.to_datetime(universe["active_end"]).dt.normalize()
    factor_frames: list[pd.DataFrame] = []
    file_evidence: list[dict[str, Any]] = []
    for item in files:
        report_date = pd.Timestamp(item["report_date"]).normalize()
        partition_path = resolve_repository_record_path(item["path"])
        frame = pd.read_parquet(partition_path)
        if tuple(frame.columns) != EASTMONEY_BALANCE_SHEET_RESILIENCE_COLUMNS:
            raise ValueError(
                "Eastmoney balance-sheet-resilience partition columns changed"
            )
        frame["report_date"] = pd.to_datetime(
            frame["report_date"], errors="coerce"
        ).dt.normalize()
        frame["announcement_date"] = pd.to_datetime(
            frame["announcement_date"], errors="coerce"
        ).dt.normalize()
        assets = pd.to_numeric(frame["total_assets"], errors="coerce")
        liabilities = pd.to_numeric(frame["total_liabilities"], errors="coerce")
        values = pd.to_numeric(
            frame[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME], errors="coerce"
        )
        if (
            len(frame) != int(item["rows"])
            or dataframe_content_sha256(frame) != item["sha256"]
            or frame[["instrument", "report_date", "announcement_date"]]
            .isna()
            .any()
            .any()
            or not frame["report_date"].eq(report_date).all()
            or frame.duplicated(["instrument", "report_date"]).any()
            or not np.isfinite(assets).all()
            or not assets.gt(0.0).all()
            or not np.isfinite(liabilities).all()
            or not liabilities.ge(0.0).all()
            or not liabilities.le(assets).all()
            or not np.isfinite(values).all()
            or not np.allclose(
                values.to_numpy(dtype="float64"),
                1.0
                - liabilities.to_numpy(dtype="float64")
                / assets.to_numpy(dtype="float64"),
                rtol=0.0,
                atol=1e-12,
            )
            or set(frame["provider"].astype(str)) != {"eastmoney"}
        ):
            raise ValueError(
                "Eastmoney balance-sheet-resilience partition formula or keys changed: "
                f"{item['report_date']}"
            )
        membership = frame[["instrument"]].merge(
            universe, on="instrument", how="left", validate="many_to_one"
        )
        if (
            membership[["active_start", "active_end"]].isna().any().any()
            or not membership["active_start"].le(report_date).all()
            or not membership["active_end"].ge(report_date).all()
        ):
            raise ValueError(
                "Eastmoney balance-sheet-resilience row is outside the report-date universe"
            )
        frame[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME] = values
        factor_frames.append(frame)
        file_evidence.append(
            {
                "report_date": item["report_date"],
                "path": str(partition_path),
                "rows": int(len(frame)),
                "content_sha256": item["sha256"],
            }
        )
    events = pd.concat(factor_frames, ignore_index=True)
    if len(events) != 113916 or events.duplicated(["instrument", "report_date"]).any():
        raise ValueError(
            "Eastmoney balance-sheet-resilience full event aggregate changed"
        )
    return events, {
        "manifest": {
            "path": str(manifest_path),
            "sha256": file_sha256(manifest_path),
            "run_id": manifest.get("run_id"),
            "status": manifest.get("status"),
            "rows": int(len(events)),
            "partitions": len(files),
        },
        "full_source_record": {
            "path": str(
                DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_FULL_SOURCE_RECORD.resolve()
            ),
            "sha256": file_sha256(
                DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_FULL_SOURCE_RECORD
            ),
        },
        "files": file_evidence,
        "coverage": coverage,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def materialize_eastmoney_balance_sheet_resilience_states(
    events: pd.DataFrame,
    target_sessions: pd.DatetimeIndex,
    full_calendar: pd.DatetimeIndex,
    *,
    state_spec: dict[str, Any],
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Materialize conservative report-period-reset states on fixed sessions."""

    sessions = pd.DatetimeIndex(target_sessions).normalize().unique().sort_values()
    calendar = pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    if sessions.empty or not sessions.isin(calendar).all():
        raise ValueError(
            "Eastmoney balance-sheet-resilience target sessions are invalid"
        )
    maximum_age = int(
        state_spec["conservative_state_algorithm"]["maximum_factor_age_calendar_days"]
    )
    work = events.loc[
        :,
        [
            "instrument",
            "report_date",
            "announcement_date",
            EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
        ],
    ].copy()
    work["report_date"] = pd.to_datetime(work["report_date"]).dt.normalize()
    work["announcement_date"] = pd.to_datetime(work["announcement_date"]).dt.normalize()

    def next_session(value: pd.Timestamp) -> pd.Timestamp | None:
        position = int(
            calendar.searchsorted(pd.Timestamp(value).normalize(), side="right")
        )
        return None if position >= len(calendar) else pd.Timestamp(calendar[position])

    work["value_availability"] = [
        next_session(value) for value in work["announcement_date"]
    ]
    activation_source = work.groupby("report_date")["announcement_date"].min()
    activation_rows = []
    for report_date, source_date in activation_source.items():
        availability = next_session(pd.Timestamp(source_date))
        if availability is not None:
            activation_rows.append(
                {
                    "report_date": pd.Timestamp(report_date),
                    "activation_source_date": pd.Timestamp(source_date),
                    "activation_availability": availability,
                }
            )
    activations = pd.DataFrame(activation_rows).sort_values(
        ["report_date"], kind="stable"
    )
    rows: list[pd.DataFrame] = []
    target_report_periods: dict[str, int] = {}
    targets_without_active_period = 0
    for session in sessions:
        active = activations.loc[activations["activation_availability"].le(session)]
        if active.empty:
            targets_without_active_period += 1
            continue
        report_date = pd.Timestamp(active["report_date"].max())
        target_report_periods[report_date.date().isoformat()] = (
            target_report_periods.get(report_date.date().isoformat(), 0) + 1
        )
        partition = work.loc[
            work["report_date"].eq(report_date)
            & work["value_availability"].notna()
            & work["value_availability"].le(session)
        ].copy()
        age = (pd.Timestamp(session) - partition["announcement_date"]).dt.days
        partition = partition.loc[age.between(0, maximum_age)].copy()
        if partition.empty:
            continue
        partition.insert(0, "trade_date", pd.Timestamp(session))
        rows.append(
            partition.loc[
                :,
                [
                    "trade_date",
                    "instrument",
                    EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
                    "report_date",
                    "announcement_date",
                ],
            ]
        )
    materialized = (
        pd.concat(rows, ignore_index=True)
        if rows
        else pd.DataFrame(
            columns=[
                "trade_date",
                "instrument",
                EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
                "report_date",
                "announcement_date",
            ]
        )
    )
    values = pd.to_numeric(
        materialized[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME],
        errors="coerce",
    )
    if (
        materialized.duplicated(["instrument", "trade_date"]).any()
        or not np.isfinite(values).all()
        or not values.between(0.0, 1.0).all()
    ):
        raise ValueError(
            "Eastmoney balance-sheet-resilience materialized state is invalid"
        )
    return materialized, {
        "target_session_count": int(len(sessions)),
        "targets_without_active_report_period": targets_without_active_period,
        "materialized_rows": int(len(materialized)),
        "sessions_with_any_factor_value": int(materialized["trade_date"].nunique()),
        "active_report_period_target_counts": target_report_periods,
        "partition_activation_count_within_calendar": int(len(activations)),
        "maximum_factor_age_calendar_days": maximum_age,
        "global_reset_at_first_next_session_after_partition_minimum_announcement": True,
        "older_report_carry_after_partition_activation": False,
        "late_older_correction_can_supersede_newer_report": False,
        "price_fields_loaded": [],
        "forward_return_fields_read": False,
    }


def eastmoney_balance_sheet_resilience_capacity(
    factor_frame: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    research_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    contract: dict[str, Any],
) -> dict[str, Any]:
    """Count quality/listing-ready conservative state cohorts without prices."""

    generic = {
        "holding_period_trading_days": int(contract["holding_period_trading_days"]),
        "minimum_valid_names_per_factor_cohort": int(
            contract["minimum_eligible_names_per_cross_section"]
        ),
        "minimum_distinct_factor_values_per_cohort": int(
            contract["minimum_distinct_factor_values"]
        ),
        "minimum_required_cohorts": int(contract["minimum_required_cohorts"]),
        "minimum_observed_calendar_years": int(contract["minimum_observed_years"]),
        "maximum_quality_age_days": int(contract["maximum_quality_age_calendar_days"]),
    }
    capacity_input = factor_frame.loc[
        :,
        [
            "trade_date",
            "instrument",
            EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
        ],
    ].copy()
    result = jqdata_moneyflow_capacity(
        capacity_input,
        fundamentals,
        full_calendar,
        research_calendar,
        instrument_intervals,
        contract=generic,
        factor_name=EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
    )
    result.update(
        {
            "holding_period_trading_days": int(contract["holding_period_trading_days"]),
            "minimum_listing_sessions": int(contract["minimum_listing_sessions"]),
            "maximum_factor_age_calendar_days": int(
                contract["maximum_factor_age_calendar_days"]
            ),
            "maximum_quality_age_calendar_days": int(
                contract["maximum_quality_age_calendar_days"]
            ),
        }
    )
    return result


def summarize_eastmoney_balance_sheet_resilience_uniqueness(
    factor_frame: pd.DataFrame,
    comparison_frame: pd.DataFrame,
    *,
    contract: dict[str, Any],
) -> dict[str, Any]:
    """Gate the factor against only the frozen 46 dense comparison fields."""

    factor_columns = [
        "trade_date",
        "instrument",
        EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
    ]
    comparison_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS,
    ]
    if missing := sorted(set(factor_columns) - set(factor_frame.columns)):
        raise ValueError(
            "Eastmoney balance-sheet factor frame is missing: " + ", ".join(missing)
        )
    if missing := sorted(set(comparison_columns) - set(comparison_frame.columns)):
        raise ValueError(
            "Eastmoney balance-sheet comparison frame is missing: " + ", ".join(missing)
        )
    if (
        len(EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS) != 46
        or len(EASTMONEY_BALANCE_SHEET_RESILIENCE_SPARSE_COMPARISON_FIELDS) != 8
        or contract.get("dense_comparison_factor_count") != 46
    ):
        raise ValueError(
            "Eastmoney balance-sheet dense/sparse comparison catalogs changed"
        )
    start = pd.Timestamp(contract["screen_start"]).normalize()
    end = pd.Timestamp(contract["screen_end"]).normalize()
    minimum_names = int(contract["minimum_pairwise_names_per_session"])
    minimum_sessions = int(contract["minimum_pairwise_sessions_per_dense_comparison"])
    maximum_correlation = float(
        contract["maximum_allowed_absolute_median_daily_rank_correlation"]
    )
    factor = factor_frame.loc[:, factor_columns].copy()
    factor["trade_date"] = pd.to_datetime(factor["trade_date"]).dt.normalize()
    factor = factor.loc[factor["trade_date"].between(start, end)]
    comparison = comparison_frame.loc[:, comparison_columns].copy()
    comparison["datetime"] = pd.to_datetime(comparison["datetime"]).dt.normalize()
    comparison = comparison.loc[
        comparison["datetime"].between(start, end)
        & comparison["quality_eligible"].fillna(False)
    ].copy()
    merged = comparison.merge(
        factor.rename(columns={"trade_date": "datetime"}),
        on=["datetime", "instrument"],
        how="inner",
        validate="one_to_one",
    )
    if merged.empty:
        raise ValueError("Eastmoney balance-sheet uniqueness has no eligible rows")
    field_results: list[dict[str, Any]] = []
    for field in EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS:
        pairwise = merged[
            [
                "datetime",
                "instrument",
                EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
                field,
            ]
        ].copy()
        pairwise[field] = pd.to_numeric(pairwise[field], errors="coerce")
        pairwise = pairwise.loc[
            np.isfinite(pairwise[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME])
            & np.isfinite(pairwise[field])
        ]
        correlations: list[float] = []
        counts: list[int] = []
        for _, daily in pairwise.groupby("datetime", sort=True):
            count = int(daily["instrument"].nunique())
            if count < minimum_names:
                continue
            counts.append(count)
            if (
                daily[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME].nunique() < 2
                or daily[field].nunique() < 2
            ):
                continue
            correlation = float(
                daily[EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME]
                .rank(method="average", pct=True)
                .corr(daily[field].rank(method="average", pct=True))
            )
            if math.isfinite(correlation):
                correlations.append(correlation)
        series = pd.Series(correlations, dtype="float64")
        median = float(series.median()) if len(series) else None
        enough = len(series) >= minimum_sessions
        independent = bool(median is not None and abs(median) < maximum_correlation)
        field_results.append(
            {
                "comparison_field": field,
                "pairwise_rows": int(len(pairwise)),
                "valid_daily_rank_correlation_sessions": int(len(series)),
                "minimum_pairwise_names_observed": int(min(counts)) if counts else 0,
                "median_daily_rank_correlation": median,
                "absolute_median_daily_rank_correlation": (
                    abs(median) if median is not None else None
                ),
                "p05_daily_rank_correlation": (
                    float(series.quantile(0.05)) if len(series) else None
                ),
                "p95_daily_rank_correlation": (
                    float(series.quantile(0.95)) if len(series) else None
                ),
                "minimum_sessions_gate_passed": enough,
                "absolute_median_correlation_gate_passed": independent,
                "uniqueness_gate_passed": bool(enough and independent),
            }
        )
    nearest = max(
        field_results,
        key=lambda item: float(
            item["absolute_median_daily_rank_correlation"]
            if item["absolute_median_daily_rank_correlation"] is not None
            else -1.0
        ),
    )
    named = {
        field: next(item for item in field_results if item["comparison_field"] == field)
        for field in contract["required_named_near_neighbors"]
    }
    passed = all(item["uniqueness_gate_passed"] for item in field_results)
    return {
        "factor": EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME,
        "dense_comparison_field_count": len(field_results),
        "sparse_event_fields_excluded_from_statistical_pass_fail": list(
            EASTMONEY_BALANCE_SHEET_RESILIENCE_SPARSE_COMPARISON_FIELDS
        ),
        "eligible_factor_comparison_rows": int(len(merged)),
        "eligible_factor_comparison_sessions": int(merged["datetime"].nunique()),
        "minimum_pairwise_names_per_session": minimum_names,
        "minimum_pairwise_sessions_per_dense_comparison": minimum_sessions,
        "maximum_allowed_absolute_median_daily_rank_correlation": maximum_correlation,
        "fields_with_minimum_sessions": int(
            sum(item["minimum_sessions_gate_passed"] for item in field_results)
        ),
        "fields_below_correlation_threshold": int(
            sum(
                item["absolute_median_correlation_gate_passed"]
                for item in field_results
            )
        ),
        "nearest_existing_field": nearest["comparison_field"],
        "maximum_observed_absolute_median_daily_rank_correlation": nearest[
            "absolute_median_daily_rank_correlation"
        ],
        "required_named_near_neighbors": named,
        "field_results": field_results,
        "uniqueness_gate_passed": passed,
        "sparse_mechanism_review_unchanged": True,
        "future_open_close_or_return_fields_derived": [],
        "forward_return_fields_read": False,
    }


def load_eastmoney_balance_sheet_resilience_dense_comparison_frame(
    provider_uri: Path,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    *,
    uniqueness_contract: dict[str, Any],
    comparison_sources: dict[str, Any],
    batch_size: int = 128,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Load exactly 46 dense close-known fields after capacity passes."""

    screen_start = str(uniqueness_contract["screen_start"])
    screen_end = str(uniqueness_contract["screen_end"])
    if screen_start != "2025-01-01" or screen_end != "2025-12-31":
        raise ValueError("Eastmoney balance-sheet uniqueness window changed")
    moneyflow, pb, rich_evidence = load_tushare_sw_terminal_comparison_factors(
        start=screen_start,
        end=screen_end,
    )
    sw_spec = load_tushare_sw_industry_breadth_capacity_preregistration()
    sw_manifest = resolve_repository_record_path(
        comparison_sources["terminal_tushare_sw_breadth"]["full_manifest_path"]
    )
    membership_intervals, context_frames, sw_validation = (
        validate_tushare_sw_industry_membership_snapshot(sw_manifest, sw_spec)
    )
    if not sw_validation["coverage"][
        "membership_coverage_gate_passed_before_close_known_inputs"
    ]:
        raise ValueError(
            "Eastmoney balance-sheet SW comparison membership coverage failed"
        )
    sw_factor, sw_construction = load_tushare_sw_industry_breadth_factor(
        provider_uri,
        membership_intervals,
        context_frames,
        sw_spec,
        batch_size=256,
        window_start=screen_start,
        window_end=screen_end,
    )
    extended_start = (
        (pd.Timestamp(screen_start) - pd.Timedelta(days=7)).date().isoformat()
    )
    market = load_market_data(
        provider_uri,
        start=extended_start,
        end=screen_end,
        batch_size=batch_size,
    )
    market = attach_quality_asof(
        market,
        fundamentals,
        max_age_days=int(uniqueness_contract["maximum_quality_age_days"]),
        availability_calendar=full_calendar,
    )
    ranked = rank_factor_frame(market)
    ranked = ranked.loc[
        pd.to_datetime(ranked["datetime"])
        .dt.normalize()
        .between(screen_start, screen_end)
    ].copy()
    local_columns = [
        "datetime",
        "instrument",
        "fundamental_quality_eligible",
        "listing_seasoning_eligible",
        "quality_eligible",
        *TUSHARE_DAILY_PB_COMPARISON_FIELDS,
    ]
    comparison = ranked.loc[:, local_columns].copy()
    del market, ranked
    gc.collect()
    for rich_frame, factor_name in (
        (moneyflow, TUSHARE_MONEYFLOW_FACTOR_NAME),
        (pb, TUSHARE_DAILY_PB_FACTOR_NAME),
        (sw_factor, TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME),
    ):
        rich = rich_frame.rename(columns={"trade_date": "datetime"}).copy()
        rich["datetime"] = pd.to_datetime(rich["datetime"]).dt.normalize()
        rich["instrument"] = rich["instrument"].astype(str)
        comparison = comparison.merge(
            rich[["datetime", "instrument", factor_name]],
            on=["datetime", "instrument"],
            how="left",
            validate="one_to_one",
        )
    if (
        comparison.duplicated(["instrument", "datetime"]).any()
        or tuple(
            field
            for field in EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS
            if field in comparison.columns
        )
        != EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS
        or any(
            field in comparison.columns
            for field in EASTMONEY_BALANCE_SHEET_RESILIENCE_SPARSE_COMPARISON_FIELDS
        )
    ):
        raise ValueError(
            "Eastmoney balance-sheet dense comparison catalog or keys changed"
        )
    return comparison, {
        "comparison_window_start": screen_start,
        "comparison_window_end": screen_end,
        "dense_comparison_field_count": len(
            EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS
        ),
        "sparse_event_fields_loaded": [],
        "terminal_moneyflow_and_pb": rich_evidence,
        "terminal_sw_breadth": {
            "source_evidence": sw_validation["source_evidence"],
            "membership_coverage": sw_validation["coverage"],
            "factor_construction": sw_construction,
            "screen_rows": int(len(sw_factor)),
        },
        "same_session_close_known_market_inputs_transiently_loaded": [
            "$close",
            "$open",
            "$high",
            "$low",
            "$volume",
            "$amount",
            "$factor",
            "$turnover",
            "$vwap",
        ],
        "future_open_close_or_return_fields_read": False,
        "forward_return_fields_read": False,
    }


def require_unconsumed_eastmoney_balance_sheet_resilience_no_return_audit(
    experiment_root: Path,
    *,
    source_manifest_sha256: str,
) -> None:
    """Allow one completed combined audit for the sole full snapshot."""

    for path in sorted(
        experiment_root.expanduser().glob(
            "*_eastmoney_balance_sheet_resilience_no_return_audit.json"
        )
    ):
        record = load_json_record(path)
        source = (
            (record.get("preregistration") or {}).get("source_evidence") or {}
        ).get("manifest") or {}
        if (
            record.get("status") == "completed"
            and record.get("purpose")
            == EASTMONEY_BALANCE_SHEET_RESILIENCE_NO_RETURN_AUDIT_PURPOSE
            and source.get("sha256") == source_manifest_sha256
        ):
            raise ValueError(
                "Eastmoney balance-sheet no-return snapshot is already consumed: "
                f"{path}"
            )


def run_eastmoney_balance_sheet_resilience_no_return_audit(
    args: argparse.Namespace,
) -> dict[str, Any]:
    """Run conservative state capacity, then conditional dense uniqueness."""

    if DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_RESEARCH_RECORD.exists():
        raise ValueError(
            "Eastmoney balance-sheet-resilience branch already has a terminal research record"
        )
    spec = load_eastmoney_balance_sheet_resilience_no_return_preregistration()
    state_spec = load_eastmoney_balance_sheet_resilience_state_preregistration()
    events, source_evidence = validate_eastmoney_balance_sheet_resilience_full_snapshot(
        Path(args.manifest), spec
    )
    experiment_root = Path(args.experiment_root).expanduser()
    require_unconsumed_eastmoney_balance_sheet_resilience_no_return_audit(
        experiment_root,
        source_manifest_sha256=source_evidence["manifest"]["sha256"],
    )
    provider_uri = Path(args.provider_uri).expanduser().resolve()
    contract_record = load_json_record(
        DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_DATA_CONTRACT,
        kind="a_share_eastmoney_balance_sheet_resilience_data_contract",
    )
    context = contract_record["local_context"]
    capacity_contract = spec["capacity_contract"]
    uniqueness_contract = spec["uniqueness_contract"]
    calendar_path = provider_uri / "calendars" / "day.txt"
    holding_path = provider_uri / "instruments" / "buyable_main_chinext.txt"
    for label, path, digest in (
        ("calendar", calendar_path, context["local_calendar"]["sha256"]),
        ("holding universe", holding_path, context["holding_universe"]["sha256"]),
    ):
        if not path.exists() or file_sha256(path) != digest:
            raise ValueError(
                f"Eastmoney balance-sheet provider {label} differs from the contract"
            )
    full_calendar, research_calendar, intervals = local_market_capacity_context(
        provider_uri,
        market="buyable_main_chinext",
        start="2019-01-01",
        end="2025-12-31",
    )
    quality_link = context["quarterly_quality"]
    quality_path = resolve_repository_record_path(quality_link["path"])
    if file_sha256(quality_path) != quality_link["sha256"]:
        raise ValueError("Eastmoney balance-sheet quarterly quality snapshot changed")
    fundamentals = load_fundamentals(quality_path)
    hold_days = int(capacity_contract["holding_period_trading_days"])
    capacity_targets = research_calendar[:-hold_days:hold_days]
    capacity_states, capacity_materialization = (
        materialize_eastmoney_balance_sheet_resilience_states(
            events,
            capacity_targets,
            full_calendar,
            state_spec=state_spec,
        )
    )
    capacity = eastmoney_balance_sheet_resilience_capacity(
        capacity_states,
        fundamentals,
        full_calendar,
        research_calendar,
        intervals,
        contract=capacity_contract,
    )
    capacity["state_materialization"] = capacity_materialization
    capacity_passed = bool(capacity["capacity_gate_passed"])
    comparison_evidence: dict[str, Any] | None = None
    uniqueness: dict[str, Any] | None = None
    uniqueness_materialization: dict[str, Any] | None = None
    comparison_fields_loaded: list[str] = []
    transient_close_known_inputs: list[str] = []
    if capacity_passed:
        screen_sessions = research_calendar[
            (research_calendar >= pd.Timestamp(uniqueness_contract["screen_start"]))
            & (research_calendar <= pd.Timestamp(uniqueness_contract["screen_end"]))
        ]
        uniqueness_states, uniqueness_materialization = (
            materialize_eastmoney_balance_sheet_resilience_states(
                events,
                screen_sessions,
                full_calendar,
                state_spec=state_spec,
            )
        )
        comparison_catalog = load_tushare_cash_conversion_no_return_preregistration()
        comparison_contract = {
            **uniqueness_contract,
            "maximum_quality_age_days": int(
                capacity_contract["maximum_quality_age_calendar_days"]
            ),
        }
        comparison_frame, comparison_evidence = (
            load_eastmoney_balance_sheet_resilience_dense_comparison_frame(
                provider_uri,
                fundamentals,
                full_calendar,
                uniqueness_contract=comparison_contract,
                comparison_sources=comparison_catalog["comparison_sources"],
            )
        )
        comparison_fields_loaded = list(
            EASTMONEY_BALANCE_SHEET_RESILIENCE_DENSE_COMPARISON_FIELDS
        )
        transient_close_known_inputs = list(
            comparison_evidence[
                "same_session_close_known_market_inputs_transiently_loaded"
            ]
        )
        uniqueness = summarize_eastmoney_balance_sheet_resilience_uniqueness(
            uniqueness_states,
            comparison_frame,
            contract=uniqueness_contract,
        )
        del comparison_frame, uniqueness_states
        gc.collect()
    del capacity_states, events
    gc.collect()

    uniqueness_passed = bool(
        uniqueness is not None and uniqueness["uniqueness_gate_passed"]
    )
    both_passed = bool(capacity_passed and uniqueness_passed)
    if not capacity_passed:
        decision = (
            "rejected_before_dense_comparison_load_and_return_diagnostic_"
            "insufficient_conservative_state_capacity"
        )
    elif not uniqueness_passed:
        decision = (
            "rejected_before_return_diagnostic_near_synonym_or_insufficient_"
            "dense_pairwise_uniqueness_evidence"
        )
    else:
        decision = (
            "eligible_only_for_separate_fingerprint_bound_single_factor_"
            "return_and_execution_diagnostic_preregistration"
        )
    run_id = _timestamp()
    audit = {
        "kind": "a_share_eastmoney_balance_sheet_resilience_no_return_audit",
        "run_id": run_id,
        "status": "completed",
        "purpose": EASTMONEY_BALANCE_SHEET_RESILIENCE_NO_RETURN_AUDIT_PURPOSE,
        "preregistration": {
            "path": str(
                DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_NO_RETURN_SPEC.resolve()
            ),
            "sha256": file_sha256(
                DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_NO_RETURN_SPEC
            ),
            "state_materialization": {
                "path": str(
                    DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_STATE_SPEC.resolve()
                ),
                "sha256": file_sha256(
                    DEFAULT_EASTMONEY_BALANCE_SHEET_RESILIENCE_STATE_SPEC
                ),
            },
            "source_evidence": source_evidence,
        },
        "factor_catalog": [EASTMONEY_BALANCE_SHEET_RESILIENCE_FACTOR_NAME],
        "factor_direction": "higher_is_better",
        "capacity_contract": capacity_contract,
        "uniqueness_contract": uniqueness_contract,
        "run_sequence": [
            {
                "step": "full_source_formula_membership_coverage_and_fingerprint_revalidation",
                "completed": True,
                "passed": True,
                "comparison_fields_loaded": [],
                "price_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "conservative_report_period_reset_and_capacity_grid_materialization",
                "completed": True,
                "passed": True,
                "comparison_fields_loaded": [],
                "price_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "quality_listing_and_non_overlapping_three_session_capacity",
                "completed": True,
                "passed": capacity_passed,
                "comparison_fields_loaded": [],
                "price_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "exact_46_dense_close_known_2025_comparison_materialization",
                "completed": comparison_evidence is not None,
                "skipped_reason": (
                    None
                    if capacity_passed
                    else "capacity_failed_before_comparison_field_load"
                ),
                "comparison_fields_loaded": comparison_fields_loaded,
                "sparse_event_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "46_dense_field_daily_rank_correlation_uniqueness",
                "completed": uniqueness is not None,
                "passed": uniqueness_passed,
                "comparison_fields_loaded": comparison_fields_loaded,
                "forward_return_fields_read": False,
            },
        ],
        "source_capacity": capacity,
        "uniqueness_state_materialization": uniqueness_materialization,
        "comparison_source_evidence": comparison_evidence,
        "uniqueness": uniqueness,
        "source_completeness_gate_passed": True,
        "capacity_gate_passed": capacity_passed,
        "uniqueness_gate_passed": uniqueness_passed,
        "both_no_return_gates_passed": both_passed,
        "source_admitted_for_separate_return_diagnostic_preregistration": both_passed,
        "decision": decision,
        "data": {
            "provider_uri": str(provider_uri),
            "calendar_path": str(calendar_path),
            "calendar_sha256": file_sha256(calendar_path),
            "holding_universe_path": str(holding_path),
            "holding_universe_sha256": file_sha256(holding_path),
            "instrument_span_count": int(len(intervals)),
            "capacity_price_fields_loaded": [],
            "capacity_completed_before_close_known_comparison_fields": True,
            "close_known_dense_comparison_fields_loaded": comparison_fields_loaded,
            "sparse_event_comparison_fields_loaded": [],
            "same_session_close_known_market_inputs_transiently_loaded": (
                transient_close_known_inputs
            ),
            "raw_market_columns_retained_in_audit": [],
            "future_open_close_or_return_fields_read": False,
            "forward_return_fields_read": False,
        },
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "This public source is a current historical snapshot, not an immutable point-in-time version stream.",
            "The global partition reset deliberately discards older values early and can understate capacity; it cannot create an earlier factor value.",
            "Source, capacity, and uniqueness are no-outcome gates and imply no return association or tradable strategy.",
            "No sparse event values, next-session open, future close, forward return, score, current selection, position size, or order field is read or derived.",
        ],
    }
    experiment_root.mkdir(parents=True, exist_ok=True)
    destination = (
        experiment_root
        / f"{run_id}_eastmoney_balance_sheet_resilience_no_return_audit.json"
    )
    _atomic_write_text(
        destination,
        json.dumps(audit, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return {
        "status": "completed",
        "audit_path": str(destination.resolve()),
        "factor_capacity": capacity,
        "uniqueness": uniqueness,
        "both_no_return_gates_passed": both_passed,
        "source_admitted_for_separate_return_diagnostic_preregistration": both_passed,
        "decision": decision,
        "forward_return_fields_read": False,
    }


def load_eastmoney_monetary_funds_asset_intensity_no_return_preregistration(
    path: Path = DEFAULT_EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_NO_RETURN_SPEC,
) -> dict[str, Any]:
    """Verify the frozen monetary-funds full-source and no-return protocol."""

    path = path.expanduser().resolve()
    if (
        file_sha256(path)
        != EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_NO_RETURN_SPEC_SHA256
    ):
        raise ValueError(
            "Eastmoney monetary-funds no-return preregistration fingerprint mismatch"
        )
    spec = load_json_record(
        path,
        kind=(
            "a_share_eastmoney_monetary_funds_asset_intensity_"
            "no_return_preregistration"
        ),
    )
    source = spec.get("source_chain") or {}
    full = spec.get("full_source_snapshot_contract") or {}
    normalization = spec.get("normalization_contract") or {}
    state = spec.get("point_in_time_event_state_contract") or {}
    capacity = spec.get("capacity_contract") or {}
    uniqueness = spec.get("uniqueness_contract") or {}
    expected_dates = [
        f"{year}-{month_day}"
        for year in range(2019, 2026)
        for month_day in ("03-31", "06-30", "09-30", "12-31")
    ]
    expected_source_hashes = {
        "mechanism_audit": (
            "6f195390c950e08f10cd5c0725497c769434f6848ce8eeee22a4b77a6088a419"
        ),
        "data_contract": (
            EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_DATA_CONTRACT_SHA256
        ),
        "acceptance_record": (
            EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_SOURCE_ACCEPTANCE_RECORD_SHA256
        ),
        "acceptance_manifest": (
            "77172da63f5e94eebc04fb3a5493f907c22fc59c734ab84b85e33eb96e2e9907"
        ),
    }
    if (
        spec.get("version") != 1
        or spec.get("status")
        != "frozen_after_source_acceptance_before_other_report_dates_capacity_comparisons_prices_or_returns"
        or spec.get("preregistered_at") != "2026-07-21T06:06:36Z"
        or full.get("report_dates") != expected_dates
        or full.get("required_report_date_count") != 28
        or full.get("accepted_partition_reused_without_network") != "2025-12-31"
        or full.get("new_network_partitions") != 27
        or full.get("maximum_new_provider_calls") != 540
        or full.get("minimum_complete_identity_active_holding_coverage_per_report_date")
        != 0.85
        or full.get("minimum_median_complete_identity_active_holding_coverage") != 0.95
        or full.get("minimum_valid_factor_active_holding_coverage_per_report_date")
        != 0.75
        or full.get("minimum_median_valid_factor_active_holding_coverage") != 0.95
        or tuple(normalization.get("columns") or ())
        != EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_COLUMNS
        or normalization.get("factor_formula") != "monetary_funds / total_assets"
        or normalization.get("direction") != "higher_is_better"
        or normalization.get("maximum_formula_absolute_error") != 1e-12
        or normalization.get("explicit_zero_monetary_funds_allowed") is not True
        or state.get("same_announcement_session_trade_allowed") is not False
        or state.get("maximum_factor_age_calendar_days") != 3
        or state.get("older_report_may_replace_a_newer_report_for_the_same_instrument")
        is not False
        or state.get("missing_or_invalid_new_value_carries_an_older_value") is not False
        or state.get("weekend_or_holiday_extension_beyond_three_calendar_days")
        is not False
        or capacity.get("must_run_before_any_comparison_value_or_price") is not True
        or capacity.get("holding_period_trading_days") != 3
        or capacity.get("non_overlapping_cohorts") is not True
        or capacity.get("minimum_eligible_names_per_cross_section") != 6
        or capacity.get("minimum_distinct_factor_values") != 2
        or capacity.get("minimum_required_cohorts") != 200
        or capacity.get("minimum_observed_years") != 5
        or capacity.get("maximum_factor_age_calendar_days") != 3
        or capacity.get("maximum_quality_age_calendar_days") != 550
        or capacity.get("minimum_listing_sessions") != MIN_LISTING_SESSIONS
        or uniqueness.get("allowed_only_after_capacity_passes") is not True
        or uniqueness.get("comparison_factor_count") != 7
        or tuple(uniqueness.get("comparison_factors") or ())
        != EASTMONEY_MONETARY_FUNDS_ASSET_INTENSITY_COMPARISON_FIELDS
        or uniqueness.get("minimum_pairwise_names_per_session") != 6
        or uniqueness.get("minimum_pairwise_sessions_per_dense_comparison") != 100
        or uniqueness.get("maximum_allowed_absolute_median_daily_rank_correlation")
        != 0.8
        or uniqueness.get("raw_price_or_forward_return_fields_loaded") != []
        or uniqueness.get("forward_return_fields_read") is not False
        or spec.get("historical_provider_rows_observed_before_freeze") is not False
        or spec.get("historical_monetary_funds_factor_values_observed_before_freeze")
        is not False
        or spec.get("comparison_values_observed_for_this_factor_before_freeze")
        is not False
        or spec.get("price_fields_loaded") != []
        or spec.get("forward_return_fields_read") is not False
        or spec.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError(
            "Eastmoney monetary-funds no-return preregistration is inconsistent"
        )
    for label, expected_hash in expected_source_hashes.items():
        link = source.get(label) or {}
        linked_path = resolve_repository_record_path(str(link.get("path") or ""))
        if (
            link.get("sha256") != expected_hash
            or not linked_path.exists()
            or file_sha256(linked_path) != expected_hash
        ):
            raise ValueError(
                f"Eastmoney monetary-funds source evidence changed: {label}"
            )
    accepted = source.get("accepted_frame") or {}
    accepted_path = resolve_repository_record_path(str(accepted.get("path") or ""))
    if not accepted_path.exists() or file_sha256(accepted_path) != accepted.get(
        "file_sha256"
    ):
        raise ValueError("Eastmoney monetary-funds accepted frame changed")
    for label, link in (spec.get("local_context") or {}).items():
        linked_path = resolve_repository_record_path(
            str((link or {}).get("path") or "")
        )
        if not linked_path.exists() or file_sha256(linked_path) != (link or {}).get(
            "sha256"
        ):
            raise ValueError(f"Eastmoney monetary-funds local context changed: {label}")
        manifest_value = (link or {}).get("manifest_path")
        manifest_sha = (link or {}).get("manifest_sha256")
        if manifest_value or manifest_sha:
            manifest_path = resolve_repository_record_path(str(manifest_value or ""))
            if not manifest_path.exists() or file_sha256(manifest_path) != manifest_sha:
                raise ValueError(
                    f"Eastmoney monetary-funds local manifest changed: {label}"
                )
    return spec


