def run_tushare_sw_industry_breadth_no_return_audit(
    args: argparse.Namespace,
) -> dict[str, Any]:
    """Run interval, factor coverage, capacity, and 45-field uniqueness gates."""

    spec = load_tushare_sw_industry_breadth_capacity_preregistration()
    membership_intervals, context_frames, validation = (
        validate_tushare_sw_industry_membership_snapshot(Path(args.manifest), spec)
    )
    source_evidence = validation["source_evidence"]
    membership_coverage = validation["coverage"]
    experiment_root = Path(args.experiment_root).expanduser()
    require_unconsumed_tushare_sw_industry_breadth_no_return_audit(
        experiment_root,
        source_manifest_sha256=source_evidence["manifest"]["sha256"],
    )

    provider_uri = Path(args.provider_uri).expanduser().resolve()
    point_in_time = spec["point_in_time_context"]
    factor_contract = spec["factor_contract"]
    combined_contract = spec["combined_no_return_audit"]
    coverage_contract = combined_contract["membership_coverage"]
    capacity_contract = combined_contract["capacity"]
    uniqueness_contract = combined_contract["uniqueness"]
    provider_calendar_path = provider_uri / "calendars" / "day.txt"
    provider_source_universe_path = (
        provider_uri / "instruments" / "factor_main_chinext_star.txt"
    )
    provider_holding_universe_path = (
        provider_uri / "instruments" / "buyable_main_chinext.txt"
    )
    provider_price_basis_path = provider_uri / PRICE_BASIS_MANIFEST_NAME
    for label, path, expected in (
        (
            "calendar",
            provider_calendar_path,
            point_in_time["local_calendar"]["file_sha256"],
        ),
        (
            "source universe",
            provider_source_universe_path,
            point_in_time["source_universe"]["file_sha256"],
        ),
        (
            "holding universe",
            provider_holding_universe_path,
            point_in_time["holding_universe"]["file_sha256"],
        ),
        (
            "price basis",
            provider_price_basis_path,
            point_in_time["accepted_price_basis"]["sha256"],
        ),
    ):
        if not path.exists() or file_sha256(path) != expected:
            raise ValueError(
                f"Tushare SW provider {label} differs from preregistration"
            )
    require_research_price_basis(provider_uri)

    membership_passed = bool(
        membership_coverage["membership_coverage_gate_passed_before_close_known_inputs"]
    )
    factor_construction: dict[str, Any] | None = None
    factor_coverage: dict[str, Any] | None = None
    capacity: dict[str, Any] | None = None
    uniqueness: dict[str, Any] | None = None
    comparison_source_evidence: dict[str, Any] | None = None
    comparison_fields_loaded: list[str] = []
    transient_market_inputs: list[str] = []
    factor_values_constructed = False
    factor_coverage_passed = False
    capacity_passed = False
    uniqueness_passed = False

    if membership_passed:
        factor_frame, factor_construction = load_tushare_sw_industry_breadth_factor(
            provider_uri,
            membership_intervals,
            context_frames,
            spec,
        )
        factor_values_constructed = True
        factor_frame, factor_coverage = (
            summarize_tushare_sw_industry_breadth_factor_coverage(
                factor_frame,
                context_frames["holding_universe"],
                context_frames["research_calendar"],
                minimum_sessions_with_fifty_values=int(
                    coverage_contract["minimum_sessions_with_fifty_factor_values"]
                ),
            )
        )
        factor_coverage_passed = bool(factor_coverage["factor_coverage_gate_passed"])
        if factor_coverage_passed:
            quality = point_in_time["quarterly_quality"]
            fundamentals = load_fundamentals(
                resolve_repository_record_path(quality["path"])
            )
            holding_intervals = {
                str(row.instrument): [
                    (
                        pd.Timestamp(row.active_start).normalize(),
                        pd.Timestamp(row.active_end).normalize(),
                    )
                ]
                for row in context_frames["holding_universe"].itertuples(index=False)
            }
            capacity = tushare_sw_industry_breadth_capacity(
                factor_frame,
                fundamentals,
                pd.DatetimeIndex(context_frames["full_calendar"]),
                pd.DatetimeIndex(context_frames["research_calendar"]),
                holding_intervals,
                capacity_contract=capacity_contract,
                factor_contract=factor_contract,
            )
            capacity_passed = bool(capacity["capacity_gate_passed"])
            if capacity_passed:
                screen_start = str(uniqueness_contract["screen_start"])
                screen_end = str(uniqueness_contract["screen_end"])
                factor_for_uniqueness = factor_frame.loc[
                    pd.to_datetime(factor_frame["trade_date"])
                    .dt.normalize()
                    .between(screen_start, screen_end),
                    [
                        "trade_date",
                        "instrument",
                        TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME,
                    ],
                ].copy()
                del factor_frame
                gc.collect()
                moneyflow, pb, comparison_source_evidence = (
                    load_tushare_sw_terminal_comparison_factors(
                        start=screen_start,
                        end=screen_end,
                    )
                )
                market = load_market_data(
                    provider_uri,
                    start=screen_start,
                    end=screen_end,
                    batch_size=128,
                )
                market = attach_quality_asof(
                    market,
                    fundamentals,
                    max_age_days=int(factor_contract["maximum_quality_age_days"]),
                    availability_calendar=context_frames["full_calendar"],
                )
                local_comparison_columns = [
                    "datetime",
                    "instrument",
                    "fundamental_quality_eligible",
                    "listing_seasoning_eligible",
                    "quality_eligible",
                    *TUSHARE_DAILY_PB_COMPARISON_FIELDS,
                ]
                comparison_frame = market.loc[:, local_comparison_columns].copy()
                del market
                gc.collect()
                for rich_frame, factor_name in (
                    (moneyflow, TUSHARE_MONEYFLOW_FACTOR_NAME),
                    (pb, TUSHARE_DAILY_PB_FACTOR_NAME),
                ):
                    rich = rich_frame.rename(columns={"trade_date": "datetime"}).copy()
                    rich["datetime"] = pd.to_datetime(
                        rich["datetime"], errors="coerce"
                    ).dt.normalize()
                    rich["instrument"] = rich["instrument"].astype(str)
                    comparison_frame = comparison_frame.merge(
                        rich.loc[:, ["datetime", "instrument", factor_name]],
                        on=["datetime", "instrument"],
                        how="left",
                        validate="one_to_one",
                    )
                del moneyflow, pb
                gc.collect()
                comparison_fields_loaded = list(
                    TUSHARE_SW_INDUSTRY_BREADTH_COMPARISON_FIELDS
                )
                transient_market_inputs = [
                    "$close",
                    "$open",
                    "$high",
                    "$low",
                    "$volume",
                    "$amount",
                    "$factor",
                    "$turnover",
                    "$vwap",
                ]
                uniqueness = summarize_tushare_sw_industry_breadth_uniqueness(
                    factor_for_uniqueness,
                    comparison_frame,
                    contract=uniqueness_contract,
                    minimum_pairwise_names_per_session=int(
                        capacity_contract["minimum_eligible_names_per_cross_section"]
                    ),
                )
                uniqueness_passed = bool(uniqueness["uniqueness_gate_passed"])
                del factor_for_uniqueness, comparison_frame
                gc.collect()
            else:
                del factor_frame
                gc.collect()
        else:
            del factor_frame
            gc.collect()

    all_passed = bool(
        membership_passed
        and factor_coverage_passed
        and capacity_passed
        and uniqueness_passed
    )
    if not membership_passed:
        decision = (
            "rejected_before_close_known_factor_construction_insufficient_"
            "point_in_time_membership_coverage"
        )
    elif not factor_coverage_passed:
        decision = (
            "rejected_before_capacity_insufficient_sessions_with_fifty_"
            "active_holding_factor_values"
        )
    elif not capacity_passed:
        decision = (
            "rejected_before_comparison_field_load_and_return_diagnostic_"
            "insufficient_quality_listing_seasoned_capacity"
        )
    elif not uniqueness_passed:
        decision = (
            "rejected_before_return_diagnostic_near_synonym_or_insufficient_"
            "pairwise_uniqueness_evidence"
        )
    else:
        decision = (
            "eligible_only_for_separate_fingerprint_bound_return_diagnostic_"
            "preregistration"
        )

    run_id = _timestamp()
    audit = {
        "kind": "a_share_tushare_sw_industry_breadth_no_return_audit",
        "run_id": run_id,
        "status": "completed",
        "purpose": TUSHARE_SW_INDUSTRY_BREADTH_NO_RETURN_AUDIT_PURPOSE,
        "preregistration": {
            "path": str(DEFAULT_TUSHARE_SW_INDUSTRY_BREADTH_CAPACITY_SPEC.resolve()),
            "sha256": file_sha256(DEFAULT_TUSHARE_SW_INDUSTRY_BREADTH_CAPACITY_SPEC),
            "preregistered_at": spec["preregistered_at"],
            "source_evidence": source_evidence,
        },
        "factor_catalog": [TUSHARE_SW_INDUSTRY_BREADTH_FACTOR_NAME],
        "factor_direction": factor_contract["direction"],
        "factor_contract": factor_contract,
        "membership_coverage_contract": coverage_contract,
        "capacity_contract": capacity_contract,
        "uniqueness_contract": uniqueness_contract,
        "run_sequence": [
            {
                "step": "full_snapshot_and_context_revalidation",
                "completed": True,
                "close_known_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "membership_interval_and_coverage",
                "completed": True,
                "passed": membership_passed,
                "close_known_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "close_known_factor_construction",
                "completed": factor_values_constructed,
                "skipped_reason": (
                    None
                    if membership_passed
                    else "membership_coverage_gate_failed_before_close_load"
                ),
                "close_known_fields_loaded": (
                    ["$close/Ref($close, 1) - 1"] if factor_values_constructed else []
                ),
                "forward_return_fields_read": False,
            },
            {
                "step": "active_holding_factor_coverage",
                "completed": factor_coverage is not None,
                "passed": factor_coverage_passed,
                "forward_return_fields_read": False,
            },
            {
                "step": "three_session_capacity",
                "completed": capacity is not None,
                "skipped_reason": (
                    None
                    if factor_coverage_passed
                    else "factor_coverage_gate_failed_before_capacity"
                ),
                "passed": capacity_passed,
                "close_known_comparison_fields_loaded": [],
                "forward_return_fields_read": False,
            },
            {
                "step": "close_known_2025_45_factor_uniqueness",
                "completed": uniqueness is not None,
                "skipped_reason": (
                    None
                    if capacity_passed
                    else "capacity_gate_failed_before_comparison_field_load"
                ),
                "passed": uniqueness_passed,
                "close_known_comparison_fields_loaded": comparison_fields_loaded,
                "forward_return_fields_read": False,
            },
        ],
        "membership_coverage": membership_coverage,
        "factor_construction": factor_construction,
        "factor_coverage": factor_coverage,
        "source_capacity": capacity,
        "comparison_source_evidence": comparison_source_evidence,
        "uniqueness": uniqueness,
        "membership_coverage_gate_passed": membership_passed,
        "factor_coverage_gate_passed": factor_coverage_passed,
        "capacity_gate_passed": capacity_passed,
        "uniqueness_gate_passed": uniqueness_passed,
        "both_no_return_gates_passed": all_passed,
        "all_no_return_gates_passed": all_passed,
        "source_admitted_for_separate_return_diagnostic_preregistration": (all_passed),
        "decision": decision,
        "data": {
            "provider_uri": str(provider_uri),
            "full_calendar_start": pd.DatetimeIndex(context_frames["full_calendar"])
            .min()
            .date()
            .isoformat(),
            "full_calendar_end": pd.DatetimeIndex(context_frames["full_calendar"])
            .max()
            .date()
            .isoformat(),
            "research_calendar_start": pd.DatetimeIndex(
                context_frames["research_calendar"]
            )
            .min()
            .date()
            .isoformat(),
            "research_calendar_end": pd.DatetimeIndex(
                context_frames["research_calendar"]
            )
            .max()
            .date()
            .isoformat(),
            "calendar_path": str(provider_calendar_path),
            "calendar_sha256": file_sha256(provider_calendar_path),
            "source_universe_path": str(provider_source_universe_path),
            "source_universe_sha256": file_sha256(provider_source_universe_path),
            "holding_universe_path": str(provider_holding_universe_path),
            "holding_universe_sha256": file_sha256(provider_holding_universe_path),
            "price_basis_path": str(provider_price_basis_path),
            "price_basis_sha256": file_sha256(provider_price_basis_path),
            "membership_interval_count": int(len(membership_intervals)),
            "factor_values_constructed": factor_values_constructed,
            "factor_close_known_input_fields_loaded": (
                ["$close/Ref($close, 1) - 1"] if factor_values_constructed else []
            ),
            "capacity_completed_before_close_known_comparison_fields": True,
            "close_known_comparison_fields_loaded": comparison_fields_loaded,
            "same_session_close_known_market_inputs_transiently_loaded": (
                transient_market_inputs
            ),
            "raw_market_columns_retained_in_audit": [],
            "future_open_close_or_return_fields_read": False,
            "future_open_close_or_return_field_names": [],
            "forward_return_fields_read": False,
        },
        "forward_return_fields_read": False,
        "selection_or_promotion_allowed": False,
        "limitations": [
            "Membership, factor coverage, capacity, and uniqueness are no-outcome gates; passing does not imply association, tradability, or a usable strategy.",
            "The factor uses only current and prior accepted closes; all 45 comparison factors are same-session close-known and load only after capacity passes.",
            "No future open, future close, forward return, score, current selection, position sizing, or order field is read or derived.",
            "A complete pass authorizes only a new immutable single-factor return-diagnostic preregistration bound to this audit fingerprint.",
            "The licensed Tushare snapshots are user-provided evidence and are not bundled in Git.",
        ],
    }
    experiment_root.mkdir(parents=True, exist_ok=True)
    destination = (
        experiment_root / f"{run_id}_tushare_sw_industry_breadth_no_return_audit.json"
    )
    _atomic_write_text(
        destination,
        json.dumps(audit, ensure_ascii=False, indent=2, default=_json_default) + "\n",
    )
    return {
        "status": "completed",
        "audit_path": str(destination.resolve()),
        "membership_coverage": membership_coverage,
        "factor_coverage": factor_coverage,
        "factor_capacity": capacity,
        "uniqueness": uniqueness,
        "all_no_return_gates_passed": all_passed,
        "source_admitted_for_separate_return_diagnostic_preregistration": (all_passed),
        "decision": decision,
        "forward_return_fields_read": False,
    }


def quarterly_acceleration_event_capacity(
    fundamentals: pd.DataFrame,
    calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    acceleration_column: str,
    hold_days: int,
    topk: int,
    minimum_cohorts: int = QUARTERLY_EVENT_CAPACITY_MIN_COHORTS,
) -> dict[str, Any]:
    """Count potential non-overlapping event baskets without reading any return.

    Sparse event ideas must be able to satisfy the existing independent-cohort
    gate before a forward-return audit is allowed.  This function uses only
    filing fields, the local calendar, and buyable-instrument activity spans;
    OHLC fields and post-signal outcomes are neither accepted nor loaded.
    """

    if acceleration_column not in QUARTERLY_ACCELERATION_METRICS:
        choices = ", ".join(sorted(QUARTERLY_ACCELERATION_METRICS))
        raise ValueError(
            f"unknown quarterly acceleration metric; choose one of: {choices}"
        )
    if hold_days < 1 or topk < 1 or minimum_cohorts < 1:
        raise ValueError("hold_days, topk, and minimum_cohorts must all be positive")
    sessions = (
        pd.DatetimeIndex(pd.to_datetime(calendar)).normalize().unique().sort_values()
    )
    if len(sessions) <= hold_days + 1:
        raise ValueError(
            "capacity window is too short for the requested holding period"
        )
    rebalances = sessions[: -(hold_days + 1) : hold_days]
    events = attach_fundamental_accelerations(fundamentals)
    events["quality_effective_date"] = _first_trading_day_after(
        sessions, events["announcement_date"]
    )
    events = events.dropna(subset=["quality_effective_date"])
    events = events.sort_values(
        ["instrument", "quality_effective_date", "report_date", "announcement_date"],
        kind="stable",
    ).drop_duplicates(["instrument", "quality_effective_date"], keep="last")
    events = events.loc[events["quality_effective_date"].isin(rebalances)].copy()

    def active_on_event(row: Any) -> bool:
        event_date = pd.Timestamp(row.quality_effective_date)
        return any(
            pd.Timestamp(start).normalize()
            <= event_date
            <= pd.Timestamp(end).normalize()
            for start, end in instrument_intervals.get(str(row.instrument), [])
        )

    events["buyable_active"] = [
        active_on_event(row) for row in events.itertuples(index=False)
    ]
    quality = (
        events["buyable_active"]
        & events["roe"].ge(5.0)
        & events["net_profit"].gt(0.0)
        & events["revenue_yoy"].gt(0.0)
        & events["profit_yoy"].gt(0.0)
    )
    acceleration = pd.to_numeric(events[acceleration_column], errors="coerce")
    positive = events.loc[quality & acceleration.gt(0.0)].copy()
    counts = positive.groupby("quality_effective_date", sort=True)[
        "instrument"
    ].nunique()
    complete = counts.loc[counts.ge(topk)]
    by_year = {
        str(int(year)): int(count)
        for year, count in complete.groupby(complete.index.year).size().items()
    }
    complete_cohorts = int(len(complete))
    return {
        "metric": acceleration_column,
        "metric_description": QUARTERLY_ACCELERATION_METRICS[acceleration_column],
        "holding_period_trading_days": hold_days,
        "topk": topk,
        "minimum_required_cohorts": minimum_cohorts,
        "calendar_sessions": int(len(sessions)),
        "non_overlapping_rebalance_capacity": int(len(rebalances)),
        "newly_effective_positive_quality_rows": int(len(positive)),
        "event_dates_with_any_positive_name": int(len(counts)),
        "complete_topk_event_cohorts": complete_cohorts,
        "complete_topk_event_cohorts_by_year": by_year,
        "capacity_gate_passed": complete_cohorts >= minimum_cohorts,
        "forward_return_fields_read": False,
        "rule": "If capacity_gate_passed is false, no return audit may be run for this event definition.",
    }


def local_market_instrument_intervals(
    provider_uri: Path, *, market: str, start: str, end: str
) -> tuple[pd.DatetimeIndex, dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]]]:
    """Load only calendar and instrument-activity spans for a no-outcome capacity audit."""

    if str(REPO_ROOT) not in sys.path:
        sys.path.insert(0, str(REPO_ROOT))
    import qlib
    from qlib.data import D

    qlib.init(
        provider_uri=str(provider_uri.expanduser().resolve()), region="cn", kernels=1
    )
    calendar = pd.DatetimeIndex(D.calendar(start_time=start, end_time=end, freq="day"))
    intervals = D.list_instruments(
        D.instruments(market=market), start_time=start, end_time=end, as_list=False
    )
    return calendar, {
        str(instrument): [
            (pd.Timestamp(span_start), pd.Timestamp(span_end))
            for span_start, span_end in spans
        ]
        for instrument, spans in intervals.items()
    }


def local_market_capacity_context(
    provider_uri: Path,
    *,
    market: str,
    start: str,
    end: str,
) -> tuple[
    pd.DatetimeIndex,
    pd.DatetimeIndex,
    dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
]:
    """Load calendars and full listing spans without requesting any price field."""

    if str(REPO_ROOT) not in sys.path:
        sys.path.insert(0, str(REPO_ROOT))
    import qlib
    from qlib.data import D

    provider_uri = provider_uri.expanduser().resolve()
    require_research_price_basis(provider_uri)
    qlib.init(provider_uri=str(provider_uri), region="cn", kernels=1)
    full_calendar = (
        pd.DatetimeIndex(D.calendar(freq="day")).normalize().unique().sort_values()
    )
    research_calendar = (
        pd.DatetimeIndex(D.calendar(start_time=start, end_time=end, freq="day"))
        .normalize()
        .unique()
        .sort_values()
    )
    raw_intervals = D.list_instruments(D.instruments(market=market), as_list=False)
    intervals = {
        str(instrument): [
            (pd.Timestamp(span_start).normalize(), pd.Timestamp(span_end).normalize())
            for span_start, span_end in spans
        ]
        for instrument, spans in raw_intervals.items()
    }
    if full_calendar.empty or research_calendar.empty or not intervals:
        raise RuntimeError(
            "capacity audit requires non-empty calendars and instrument spans"
        )
    return full_calendar, research_calendar, intervals


def sparse_announcement_source_capacity(
    events: pd.DataFrame,
    fundamentals: pd.DataFrame,
    full_calendar: pd.DatetimeIndex,
    research_calendar: pd.DatetimeIndex,
    instrument_intervals: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
    *,
    source_name: str,
    event_columns: Iterable[str],
    factor_raw_columns: dict[str, str],
    max_age_days: int,
    hold_days: int,
    topk: int,
    minimum_required_cohorts: int,
    maximum_quality_age_days: int,
    event_date_column: str = "announcement_date",
    strictly_after_event_date: bool = True,
) -> dict[str, Any]:
    """Count factor-ready event cohorts without accepting or loading any price outcome."""

    expected_factors = tuple(ANNOUNCEMENT_CAPACITY_SOURCE_FACTORS.get(source_name, ()))
    if not expected_factors or tuple(factor_raw_columns) != expected_factors:
        raise ValueError(
            f"unknown or incomplete sparse-announcement source catalog: {source_name}"
        )
    if max_age_days < 0 or hold_days < 1 or topk < 1 or minimum_required_cohorts < 1:
        raise ValueError(
            "capacity age, holding period, TopK, and minimum cohorts must be valid"
        )
    minimum_names = max(2, 2 * topk)
    sessions = pd.DatetimeIndex(research_calendar).normalize().unique().sort_values()
    availability_calendar = (
        pd.DatetimeIndex(full_calendar).normalize().unique().sort_values()
    )
    if len(sessions) <= hold_days + 1:
        raise ValueError("capacity research calendar is too short")
    rebalances = sessions[: -(hold_days + 1) : hold_days]
    required_event_columns = tuple(event_columns)
    if missing := sorted(set(required_event_columns) - set(events.columns)):
        raise ValueError(
            f"{source_name} capacity events are missing columns: {', '.join(missing)}"
        )
    if event_date_column not in required_event_columns:
        raise ValueError(
            f"{source_name} event date is absent from the frozen event columns"
        )

    source = events.loc[:, list(required_event_columns)].copy()
    source[event_date_column] = pd.to_datetime(source[event_date_column]).dt.normalize()
    availability_mapper = (
        _first_trading_day_after
        if strictly_after_event_date
        else _first_trading_day_on_or_after
    )
    source["event_effective_date"] = availability_mapper(
        availability_calendar, source[event_date_column]
    )
    source = source.dropna(
        subset=["instrument", event_date_column, "event_effective_date"]
    )
    source = source.sort_values(
        ["instrument", "event_effective_date", event_date_column], kind="stable"
    ).drop_duplicates(["instrument", "event_effective_date"], keep="last")
    source = source.loc[
        source["event_effective_date"].le(rebalances[-1])
        & source["event_effective_date"]
        .add(pd.Timedelta(days=max_age_days))
        .ge(rebalances[0])
    ].copy()

    expanded: list[dict[str, Any]] = []
    payload_columns = [
        column for column in required_event_columns if column != event_date_column
    ]
    for row in source.itertuples(index=False):
        effective_date = pd.Timestamp(row.event_effective_date).normalize()
        first = int(rebalances.searchsorted(effective_date, side="left"))
        last = int(
            rebalances.searchsorted(
                effective_date + pd.Timedelta(days=max_age_days), side="right"
            )
        )
        payload = {column: getattr(row, column) for column in payload_columns}
        for rebalance_date in rebalances[first:last]:
            expanded.append(
                {
                    **payload,
                    "datetime": pd.Timestamp(rebalance_date),
                    "event_effective_date": effective_date,
                    "event_age_days": int(
                        (pd.Timestamp(rebalance_date) - effective_date).days
                    ),
                }
            )
    candidate_columns = [
        "instrument",
        "datetime",
        "event_effective_date",
        "event_age_days",
        *[column for column in payload_columns if column != "instrument"],
    ]
    candidates = pd.DataFrame(expanded, columns=candidate_columns)
    if candidates.empty:
        factor_capacity = {
            factor: {
                "potential_complete_cohorts": 0,
                "potential_complete_cohorts_by_year": {},
                "capacity_gate_passed": False,
            }
            for factor in expected_factors
        }
        return {
            "source": source_name,
            "source_event_rows": int(len(events)),
            "candidate_event_rows": 0,
            "quality_and_listing_eligible_event_rows": 0,
            "factor_capacity": factor_capacity,
            "source_admitted_for_return_rebuild": False,
        }

    candidates = candidates.sort_values(
        ["instrument", "datetime", "event_effective_date"], kind="stable"
    ).drop_duplicates(["instrument", "datetime"], keep="last")

    def active_on_date(row: Any) -> bool:
        signal_date = pd.Timestamp(row.datetime).normalize()
        return any(
            start <= signal_date <= end
            for start, end in instrument_intervals.get(str(row.instrument), [])
        )

    candidates["instrument_active"] = [
        active_on_date(row) for row in candidates.itertuples(index=False)
    ]
    candidates = candidates.loc[candidates["instrument_active"]].copy()
    candidates = attach_listing_age_sessions(
        candidates, instrument_intervals, availability_calendar
    )
    candidates = attach_quality_asof(
        candidates,
        fundamentals,
        max_age_days=maximum_quality_age_days,
        availability_calendar=availability_calendar,
    )
    eligible = candidates.loc[candidates["quality_eligible"].fillna(False)].copy()

    factor_capacity: dict[str, dict[str, Any]] = {}
    for factor, raw_column in factor_raw_columns.items():
        if raw_column not in eligible.columns:
            raise ValueError(f"capacity raw factor column is missing: {raw_column}")
        valid = eligible.loc[
            pd.to_numeric(eligible[raw_column], errors="coerce").notna()
        ].copy()
        valid["_factor_value"] = pd.to_numeric(valid[raw_column], errors="coerce")
        cross_sections = valid.groupby("datetime", sort=True).agg(
            valid_names=("instrument", "nunique"),
            distinct_factor_values=("_factor_value", "nunique"),
        )
        complete = cross_sections.loc[
            cross_sections["valid_names"].ge(minimum_names)
            & cross_sections["distinct_factor_values"].ge(2)
        ]
        by_year = {
            str(int(year)): int(count)
            for year, count in complete.groupby(complete.index.year).size().items()
        }
        cohort_count = int(len(complete))
        factor_capacity[factor] = {
            "raw_column": raw_column,
            "valid_factor_rows": int(len(valid)),
            "event_dates_with_any_valid_name": int(len(cross_sections)),
            "potential_complete_cohorts": cohort_count,
            "potential_complete_cohorts_by_year": by_year,
            "capacity_gate_passed": cohort_count >= minimum_required_cohorts,
        }
    admitted = any(item["capacity_gate_passed"] for item in factor_capacity.values())
    return {
        "source": source_name,
        "source_event_rows": int(len(events)),
        "candidate_event_rows": int(len(candidates)),
        "quality_and_listing_eligible_event_rows": int(len(eligible)),
        "factor_capacity": factor_capacity,
        "source_admitted_for_return_rebuild": admitted,
    }


