def load_sparse_announcement_capacity_audits(
    experiment_root: Path,
) -> list[dict[str, Any]]:
    """Read no-return sparse-announcement capacity gates for the research log."""

    audits: list[dict[str, Any]] = []
    for path in sorted(
        experiment_root.expanduser().glob("*_sparse_announcement_capacity_audit.json")
    ):
        try:
            audit = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if audit.get("status") != "completed":
            continue
        data = audit.get("data") or {}
        contract = audit.get("run_contract") or {}
        source_rows: list[dict[str, Any]] = []
        for source_name, source in (audit.get("source_capacity") or {}).items():
            admitted = bool(source.get("source_admitted_for_return_rebuild", False))
            for factor_name, capacity in (source.get("factor_capacity") or {}).items():
                source_rows.append(
                    {
                        "source": str(source_name),
                        "factor": str(factor_name),
                        "complete_cohorts": int(
                            capacity.get("potential_complete_cohorts") or 0
                        ),
                        "factor_passed": bool(
                            capacity.get("capacity_gate_passed", False)
                        ),
                        "source_admitted": admitted,
                    }
                )
        audits.append(
            {
                "run_id": str(audit.get("run_id", path.stem)),
                "calendar_start": str(
                    data.get("research_calendar_start", contract.get("start", "—"))
                ),
                "calendar_end": str(
                    data.get("research_calendar_end", contract.get("end", "—"))
                ),
                "minimum_cohorts": int(contract.get("minimum_required_cohorts") or 0),
                "source_rows": source_rows,
                "forward_return_fields_read": bool(
                    audit.get("forward_return_fields_read", True)
                ),
                "path": str(path.resolve()),
            }
        )
    return audits


