def load_securities_lending_source_coverage_audit(
    path: Path = DEFAULT_SECURITIES_LENDING_SOURCE_COVERAGE_AUDIT,
) -> dict[str, Any] | None:
    """Load the immutable no-return rejection of the lending source."""

    path = path.expanduser().resolve()
    if not path.exists():
        return None
    if file_sha256(path) != SECURITIES_LENDING_SOURCE_COVERAGE_AUDIT_SHA256:
        raise ValueError(
            "securities-lending source coverage audit fingerprint mismatch"
        )
    audit = load_json_record(
        path, kind="a_share_securities_lending_source_coverage_audit"
    )
    results = audit.get("results") or {}
    acceptance = audit.get("acceptance") or {}
    decision = audit.get("decision") or {}
    missing = list(results.get("missing_sessions") or [])
    if (
        audit.get("version") != 1
        or audit.get("status")
        != "rejected_before_full_snapshot_capacity_or_return_access"
        or results.get("sessions_expected") != 1699
        or results.get("sessions_with_published_positive_partitions") != 1695
        or [item.get("trade_date") for item in missing]
        != ["2019-12-31", "2020-06-30", "2020-12-31", "2021-06-30"]
        or results.get("final_parquet_written") is not False
        or results.get("final_manifest_written") is not False
        or acceptance.get("full_snapshot_accepted") is not False
        or acceptance.get("capacity_audit_allowed") is not False
        or acceptance.get("return_diagnostic_allowed") is not False
        or decision.get("outcome") != "stop_source_candidate_before_capacity_or_returns"
        or audit.get("forward_return_fields_read") is not False
        or audit.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError("securities-lending source coverage audit is inconsistent")
    return {
        "audited_at": str(audit["audited_at"]),
        "sessions_expected": int(results["sessions_expected"]),
        "sessions_published": int(
            results["sessions_with_published_positive_partitions"]
        ),
        "missing_dates": [str(item["trade_date"]) for item in missing],
        "outcome": str(decision["outcome"]),
        "forward_return_fields_read": False,
        "path": str(path),
    }


def load_official_securities_lending_source_acceptance_audit(
    path: Path = DEFAULT_OFFICIAL_SECURITIES_LENDING_SOURCE_ACCEPTANCE_AUDIT,
) -> dict[str, Any] | None:
    """Load the immutable no-return rejection of the official exchange route."""

    path = path.expanduser().resolve()
    if not path.exists():
        return None
    if file_sha256(path) != OFFICIAL_SECURITIES_LENDING_SOURCE_ACCEPTANCE_AUDIT_SHA256:
        raise ValueError(
            "official securities-lending source acceptance audit fingerprint mismatch"
        )
    audit = load_json_record(
        path, kind="a_share_official_securities_lending_source_acceptance_audit"
    )
    contract = audit.get("data_contract") or {}
    frontier = audit.get("frontier_extension") or {}
    results = audit.get("results") or {}
    sse = results.get("sse") or {}
    szse = results.get("szse") or {}
    acceptance = audit.get("acceptance") or {}
    decision = audit.get("decision") or {}
    samples = list(sse.get("sample_partitions") or [])
    sample_dates = [str(item.get("trade_date")) for item in samples]
    expected_dates = [
        "2018-12-28",
        "2019-12-31",
        "2020-06-30",
        "2020-12-31",
        "2021-06-30",
        "2025-12-31",
    ]
    if (
        audit.get("version") != 1
        or audit.get("status")
        != "rejected_before_full_snapshot_capacity_or_return_access"
        or contract.get("sha256") != OFFICIAL_SECURITIES_LENDING_DATA_CONTRACT_SHA256
        or file_sha256(DEFAULT_OFFICIAL_SECURITIES_LENDING_DATA_CONTRACT)
        != OFFICIAL_SECURITIES_LENDING_DATA_CONTRACT_SHA256
        or frontier.get("sha256") != RESEARCH_FRONTIER_EXTENSION_SHA256
        or file_sha256(DEFAULT_RESEARCH_FRONTIER_EXTENSION)
        != RESEARCH_FRONTIER_EXTENSION_SHA256
        or sse.get("semantic_gate_passed") is not True
        or sample_dates != expected_dates
        or any(
            int(item.get("advertised_rows") or 0)
            != int(item.get("received_rows") or -1)
            for item in samples
        )
        or szse.get("semantic_gate_passed") is not False
        or szse.get("source_schema_or_rows_observed") is not False
        or results.get("two_exchange_sample_gate_passed") is not False
        or results.get("full_snapshot_started") is not False
        or results.get("raw_or_factor_parquet_written") is not False
        or results.get("manifest_written") is not False
        or acceptance.get("partial_sse_only_source_allowed") is not False
        or acceptance.get("cross_provider_partition_fill_allowed") is not False
        or acceptance.get("capacity_audit_allowed") is not False
        or acceptance.get("return_diagnostic_allowed") is not False
        or decision.get("outcome")
        != "stop_official_source_candidate_before_full_snapshot_capacity_or_returns"
        or audit.get("forward_return_fields_read") is not False
        or audit.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError(
            "official securities-lending source acceptance audit is inconsistent"
        )
    return {
        "audited_at": str(audit["audited_at"]),
        "sse_sample_dates": sample_dates,
        "sse_sample_rows": [int(item["received_rows"]) for item in samples],
        "old_gap_dates_present_at_sse": list(
            sse.get("old_consolidator_gap_dates_present_at_official_source") or []
        ),
        "szse_failure_class": str(szse["failure_class"]),
        "outcome": str(decision["outcome"]),
        "forward_return_fields_read": False,
        "path": str(path),
    }


def load_public_five_minute_source_availability_audit(
    path: Path = DEFAULT_PUBLIC_FIVE_MINUTE_SOURCE_AVAILABILITY_AUDIT,
) -> dict[str, Any] | None:
    """Load the immutable no-return rejection of two public five-minute routes."""

    path = path.expanduser().resolve()
    if not path.exists():
        return None
    if file_sha256(path) != PUBLIC_FIVE_MINUTE_SOURCE_AVAILABILITY_AUDIT_SHA256:
        raise ValueError(
            "public five-minute source availability audit fingerprint mismatch"
        )
    audit = load_json_record(
        path, kind="a_share_public_five_minute_source_availability_audit"
    )
    target = audit.get("target_history") or {}
    sources = audit.get("sources") or {}
    eastmoney = sources.get("eastmoney") or {}
    eastmoney_observations = eastmoney.get("observations") or {}
    sina = sources.get("sina") or {}
    sina_observations = sina.get("observations") or {}
    four_symbol_checks = list(sina_observations.get("four_symbol_depth_checks") or [])
    single_symbol_checks = list(
        sina_observations.get("single_symbol_depth_checks") or []
    )
    data_use = audit.get("data_use") or {}
    acceptance = audit.get("acceptance") or {}
    decision = audit.get("decision") or {}
    if (
        audit.get("version") != 1
        or audit.get("status")
        != "rejected_before_historical_snapshot_factor_values_or_returns"
        or target.get("start") != "2020-01-01"
        or target.get("end") != "2025-12-31"
        or target.get("frequency") != "5m"
        or target.get("expected_complete_session_bars") != 48
        or eastmoney_observations.get("four_symbol_three_anchor_attempts") != 12
        or eastmoney_observations.get("four_symbol_three_anchor_result")
        != "remote_connection_closed_without_response"
        or eastmoney_observations.get("source_schema_or_rows_observed") is not False
        or [item.get("requested_rows") for item in four_symbol_checks] != [1023, 1024]
        or any(item.get("symbols_checked") != 4 for item in four_symbol_checks)
        or any(
            item.get("rows_per_symbol") != item.get("requested_rows")
            or item.get("unique_timestamps_per_symbol") != item.get("requested_rows")
            for item in four_symbol_checks
        )
        or sina_observations.get("successful_maximum_depth_observed") != 1500
        or sina_observations.get("successful_maximum_depth_start")
        != "2026-05-29 14:05:00"
        or not any(
            item.get("requested_rows") == 2000 and item.get("returned_rows") == 0
            for item in single_symbol_checks
        )
        or sina_observations.get("historical_date_cursor_observed") is not False
        or sina_observations.get("requested_2020_2025_history_observed") is not False
        or data_use.get("source_row_values_persisted") is not False
        or data_use.get("local_daily_open_close_or_return_fields_loaded") is not False
        or data_use.get("factor_values_constructed") is not False
        or data_use.get("forward_return_fields_read") is not False
        or acceptance.get("public_five_minute_historical_adapter_allowed") is not False
        or acceptance.get("full_snapshot_allowed") is not False
        or acceptance.get("factor_diagnostic_allowed") is not False
        or acceptance.get("aggregation_scoring_selection_or_ordering_allowed")
        is not False
        or decision.get("outcome")
        != "stop_public_five_minute_history_candidates_before_adapter_or_returns"
        or audit.get("forward_return_fields_read") is not False
        or audit.get("selection_or_promotion_allowed") is not False
    ):
        raise ValueError("public five-minute source availability audit is inconsistent")
    successful_depth = next(
        item for item in single_symbol_checks if item.get("requested_rows") == 1500
    )
    return {
        "audited_at": str(audit["audited_at"]),
        "target_start": str(target["start"]),
        "target_end": str(target["end"]),
        "eastmoney_attempts": int(
            eastmoney_observations["four_symbol_three_anchor_attempts"]
        ),
        "eastmoney_result": str(
            eastmoney_observations["four_symbol_three_anchor_result"]
        ),
        "sina_fields": list(sina_observations["returned_fields"]),
        "sina_successful_depth": int(
            sina_observations["successful_maximum_depth_observed"]
        ),
        "sina_window_start": str(successful_depth["min_timestamp"]),
        "sina_window_end": str(successful_depth["max_timestamp"]),
        "sina_first_empty_requested_depth": 2000,
        "outcome": str(decision["outcome"]),
        "forward_return_fields_read": False,
        "path": str(path),
    }


