    report.add_argument(
        "--prospective-factor-ledger-path",
        default=str(DEFAULT_PROSPECTIVE_FACTOR_LEDGER),
    )
    report.add_argument("--output", default=str(DEFAULT_RESEARCH_REPORT))
    return parser.parse_args()


